INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(1, 'entity', 1, '/ˈentəti/', 'that which is perceived or known or inferred to have its own distinct existence (living or nonliving)', NULL),
(2, 'abstraction', 1, '/æbˈstræk.ʃən/', 'a general concept formed by extracting common features from specific examples', NULL),
(3, 'abstraction', 1, '/æbˈstræk.ʃən/', 'the act of withdrawing or removing something', NULL),
(4, 'abstraction', 1, '/æbˈstræk.ʃən/', 'an abstract painting', NULL),
(5, 'abstraction', 1, '/æbˈstræk.ʃən/', 'the process of formulating general concepts by abstracting common properties of instances', NULL),
(6, 'abstraction', 1, '/æbˈstræk.ʃən/', 'a concept or idea not associated with any specific instance', '\"he loved her only in the abstract--not in person\"'),
(7, 'thing', 1, '/θɪŋ/', 'a separate and self-contained entity', NULL),
(8, 'thing', 1, '/θɪŋ/', 'an action', '\"how could you do such a thing?\"'),
(9, 'thing', 1, '/θɪŋ/', 'an artifact', '\"how does this thing work?\"'),
(10, 'thing', 1, '/θɪŋ/', 'an entity that is not named specifically', '\"I couldn\'t tell what the thing was\"'),
(11, 'thing', 1, '/θɪŋ/', 'any attribute or quality considered as having its own existence', '\"the thing I like about her is ...\"'),
(12, 'thing', 1, '/θɪŋ/', 'a special abstraction', '\"a thing of the spirit\"; \"things of the heart\"'),
(13, 'thing', 1, '/θɪŋ/', 'a special objective', '\"the thing is to stay in bounds\"'),
(14, 'thing', 1, '/θɪŋ/', 'a statement regarded as an object', '\"to say the same thing in other terms\"; \"how can you say such a thing?\"'),
(15, 'thing', 1, '/θɪŋ/', 'an event', '\"a funny thing happened on the way to the...\"'),
(16, 'thing', 1, '/θɪŋ/', 'a persistent illogical feeling of desire or aversion', '\"he has a thing about seafood\"; \"she has a thing about him\"'),
(17, 'thing', 1, '/θɪŋ/', 'a special situation', '\"this thing has got to end\"; \"it is a remarkable thing\"'),
(18, 'object', 1, '/ˈɒb.dʒekt/', 'a tangible and visible entity; an entity that can cast a shadow', '\"it was full of rackets, balls and other objects\"'),
(19, 'object', 1, '/ˈɒb.dʒekt/', 'the focus of cognitions or feelings', '\"objects of thought\"; \"the object of my affection\"'),
(20, 'object', 1, '/ˈɒb.dʒekt/', '(computing) a discrete item that provides a description of virtually anything known to a computer', '\"in object-oriented programming, objects include data and define its status, its methods of operation and how it interacts with other objects\"'),
(21, 'object', 1, '/ˈɒb.dʒekt/', '(grammar) a constituent that is acted upon', '\"the object of the verb\"'),
(22, 'object', 2, '/ˈɒb.dʒekt/', 'express or raise an objection or protest or criticism or express dissent', '\"She never objected to the amount of work her boss charged her with\"; \"When asked to drive the truck, she objected that she did not have a driver\'s license\"'),
(23, 'object', 2, '/ˈɒb.dʒekt/', 'be averse to or express disapproval of', '\"My wife objects to modern furniture\"'),
(24, 'whole', 1, '/həʊl/', 'an assemblage of parts that is regarded as a single entity', '\"how big is that part compared to the whole?\"; \"the team is a unit\"'),
