INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(365, 'touch', 1, '/tʌtʃ/', 'the sensation produced by pressure receptors in the skin', '\"she likes the touch of silk on her skin\"; \"the surface had a greasy feeling\"'),
