(367, 'touch', 1, '/tʌtʃ/', 'the act of soliciting money (as a gift or loan)', '\"he watched the beggar trying to make a touch\"'),
(368, 'touch', 1, '/tʌtʃ/', 'the event of something coming in contact with the body', '\"he longed for the touch of her hand\"; \"the cooling touch of the night air\"'),
(369, 'touch', 1, '/tʌtʃ/', 'a slight but appreciable amount', '\"this dish could use a touch of garlic\"'),
