(2032, 'trigger', 2, '/ˈtrɪɡ.ər/', 'release or pull the trigger on', '\"Trigger a gun\"'),
(2033, 'compulsion', 1, '/kəmˈpʌl.ʃən/', 'using force to cause something to occur', '\"though pressed into rugby under compulsion I began to enjoy the game\"; \"they didn\'t have to use coercion\"');
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(2034, 'compulsion', 1, '/kəmˈpʌl.ʃən/', 'an urge to do or say something that might be better left undone or unsaid', '\"he felt a compulsion to babble on about the accident\"'),
(2035, 'compulsion', 1, '/kəmˈpʌl.ʃən/', 'an irrational motive for performing trivial or repetitive actions, even against your will', '\"her compulsion to wash her hands repeatedly\"'),
(2036, 'influence', 1, '/ˈɪn.flu.əns/', 'causing something without any direct or apparent effort', NULL),
(2037, 'influence', 1, '/ˈɪn.flu.əns/', 'a power to affect persons or events especially power based on prestige etc', '\"used her parents\' influence to get the job\"'),
(2038, 'influence', 1, '/ˈɪn.flu.əns/', 'a cognitive factor that tends to have an effect on what you do', '\"her wishes had a great influence on his thinking\"'),
(2039, 'influence', 1, '/ˈɪn.flu.əns/', 'one having power to influence another', '\"she was the most important influence in my life\"; \"he was a bad influence on the children\"'),
(2040, 'influence', 1, '/ˈɪn.flu.əns/', 'the effect of one thing (or person) on another', '\"the influence of mechanical action\"'),
(2041, 'influence', 2, '/ˈɪn.flu.əns/', 'have and exert influence or effect', '\"The artist\'s work influenced the young painter\"; \"She worked on her friends to support the political candidate\"'),
(2042, 'exposure', 1, '/ɪkˈspəʊ.ʒər/', 'the act of subjecting someone to an influencing experience', '\"she denounced the exposure of children to pornography\"'),
(2043, 'exposure', 1, '/ɪkˈspəʊ.ʒər/', 'abandoning without shelter or protection (as by leaving as infant out in the open)', NULL),
(2044, 'exposure', 1, '/ɪkˈspəʊ.ʒər/', 'presentation to view in an open or public manner', '\"the exposure of his anger was shocking\"'),
(2045, 'exposure', 1, '/ɪkˈspəʊ.ʒər/', 'the act of exposing film to light', NULL),
(2046, 'exposure', 1, '/ɪkˈspəʊ.ʒər/', 'vulnerability to the elements; to the action of heat or cold or wind or rain; \"exposure to the weather\" or \"they died from exposure\";', NULL),
(2047, 'exposure', 1, '/ɪkˈspəʊ.ʒər/', 'aspect resulting from the direction a building or window faces', '\"the studio had a northern exposure\"'),
(2048, 'exposure', 1, '/ɪkˈspəʊ.ʒər/', 'the disclosure of something secret', '\"they feared exposure of their campaign plans\"'),
(2049, 'exposure', 1, '/ɪkˈspəʊ.ʒər/', 'the intensity of light falling on a photographic film or plate', '\"he used the wrong exposure\"'),
(2050, 'overexposure', 1, '/ˌəʊ.vər.ɪkˈspəʊ.ʒər/', 'the act of exposing someone excessively to an influencing experience', '\"an overexposure to violence on television\"'),
(2051, 'overexposure', 1, '/ˌəʊ.vər.ɪkˈspəʊ.ʒər/', 'the act of exposing film to too much light or for too long a time', NULL),
(2052, 'underexposure', 1, '/ˌʌndərɪkˈspəʊʒə/', 'inadequate publicity', NULL),
(2053, 'underexposure', 1, '/ˌʌndərɪkˈspəʊʒə/', 'the act of exposing film to too little light or for too short a time', NULL),
(2054, 'manipulation', 1, '/məˌnɪp.jəˈleɪ.ʃən/', 'exerting shrewd or devious influence especially for one\'s own advantage', '\"his manipulation of his friends was scandalous\"'),
(2055, 'autosuggestion', 1, '/ˌɔː.təʊ.səˈdʒes.tʃən/', 'a system for self-improvement developed by Emile Coue which was popular in the 1920s and 1930s', NULL),
(2056, 'hypnotism', 1, '/ˈhɪp.nə.tɪ.zəm/', 'the act of inducing hypnosis', NULL),
(2057, 'inducement', 1, '/ɪnˈdʒuːs.mənt/', 'act of bringing about a desired result', '\"inducement of sleep\"'),
(2058, 'corruption', 1, '/kəˈrʌp.ʃən/', 'inducement (as of a public official) by improper means (as bribery) to violate duty (as by commiting a felony)', '\"he was held on charges of corruption and racketeering\"'),
(2059, 'corruption', 1, '/kəˈrʌp.ʃən/', 'destroying someone\'s (or some group\'s) honesty or loyalty; undermining moral integrity', '\"corruption of a minor\"; \"the big city\'s subversion of rural innocence\"'),
(2060, 'corruption', 1, '/kəˈrʌp.ʃən/', 'moral perversion; impairment of virtue and moral principles', '\"the luxury and corruption among the upper classes\"; \"moral degeneracy followed intellectual degeneration\"; \"its brothels, its opium parlors, its depravity\"; \"Rome had fallen into moral putrefaction\"'),
(2061, 'corruption', 1, '/kəˈrʌp.ʃən/', 'decay of matter (as by rot or oxidation)', NULL),
(2062, 'enticement', 1, '/ɪnˈtaɪs.mənt/', 'the act of influencing by exciting hope or desire', '\"his enticements were shameless\"'),
(2063, 'ingratiation', 1, '/ɪnɡreɪʃɪˈeɪʃən/', 'the act of gaining acceptance or affection for yourself by persuasive and subtle blandishments', '\"she refused to use insinuation in order to gain favor\"'),
