(2081, 'decision', 1, '/dɪˈsɪʒ.ən/', 'a position or opinion or judgment reached after consideration', '\"a decision unfavorable to the opposition\"; \"his conclusion took the evidence into account\"; \"satisfied with the panel\'s determination\"'),
(2082, 'decision', 1, '/dɪˈsɪʒ.ən/', 'the outcome of a game or contest', '\"the team dropped three decisions in a row\"'),
