(2114, 'call', 2, '/kɔːl/', 'declare in the capacity of an umpire or referee', '\"call a runner out\"'),
(2115, 'call', 2, '/kɔːl/', 'challenge (somebody) to make good on a statement; charge with or censure for an offense', '\"He deserves to be called on that\"'),
