(2372, 'solution', 1, '/səˈluː.ʃən/', 'the set of values that give a true statement when substituted into an equation', NULL),
(2373, 'solution', 1, '/səˈluː.ʃən/', 'a homogeneous mixture of two or more substances; frequently (but not necessarily) a liquid solution', '\"he used a solution of peroxide and water\"'),
(2374, 'change', 1, '/tʃeɪndʒ/', 'the action of changing something', '\"the change of government had no impact on the economy\"; \"his change on abortion cost him the election\"'),
(2375, 'change', 1, '/tʃeɪndʒ/', 'a different or fresh set of clothes', '\"she brought a change in her overnight bag\"'),
(2376, 'change', 1, '/tʃeɪndʒ/', 'a thing that is different', '\"he inspected several changes before selecting one\"'),
(2377, 'change', 1, '/tʃeɪndʒ/', 'an event that occurs when something passes from one state or phase to another', '\"the change was intended to increase sales\"; \"this storm is certainly a change for the worse\"; \"the neighborhood had undergone few modifications since his last visit years ago\"'),
(2378, 'change', 1, '/tʃeɪndʒ/', 'the result of alteration or modification', '\"there were marked changes in the lining of the lungs\"; \"there had been no change in the mountains\"'),
(2379, 'change', 1, '/tʃeɪndʒ/', 'money received in return for its equivalent in a larger denomination or a different currency', '\"he got change for a twenty and used it to pay the taxi driver\"'),
(2380, 'change', 1, '/tʃeɪndʒ/', 'the balance of money received when the amount you tender is greater than the amount due', '\"I paid with a twenty and pocketed the change\"'),
(2381, 'change', 1, '/tʃeɪndʒ/', 'coins of small denomination regarded collectively', '\"he had a pocketful of change\"'),
(2382, 'change', 1, '/tʃeɪndʒ/', 'a relational difference between states; especially between states before and after some event', '\"he attributed the change to their marriage\"'),
(2383, 'change', 2, '/tʃeɪndʒ/', 'undergo a change; become different in essence; losing one\'s or its original nature', '\"She changed completely as she grew older\"; \"The weather changed last night\"'),
(2384, 'change', 2, '/tʃeɪndʒ/', 'become different in some particular way, without permanently losing one\'s or its former characteristics or essence', '\"her mood changes in accordance with the weather\"; \"The supermarket\'s selection of vegetables varies according to the season\"'),
(2385, 'change', 2, '/tʃeɪndʒ/', 'cause to change; make different; cause a transformation', '\"The advent of the automobile may have altered the growth pattern of the city\"; \"The discussion has changed my thinking about the issue\"'),
(2386, 'change', 2, '/tʃeɪndʒ/', 'exchange or replace with another, usually of the same kind or category', '\"Could you convert my dollars into pounds?\"; \"He changed his name\"; \"convert centimeters into inches\"; \"convert holdings into shares\"'),
(2387, 'change', 2, '/tʃeɪndʒ/', 'remove or replace the coverings of', '\"Father had to learn how to change the baby\"; \"After each guest we changed the bed linens\"'),
(2388, 'change', 2, '/tʃeɪndʒ/', 'change clothes; put on different clothes', '\"Change before you go to the opera\"'),
(2389, 'filtration', 1, '/fɪlˈtreɪ.ʃən/', 'the act of changing a fluid by passing it through a filter', NULL),
(2390, 'filtration', 1, '/fɪlˈtreɪ.ʃən/', 'the process whereby fluids pass through a filter or a filtering medium', NULL),
(2391, 'percolation', 1, '/ˌpɜː.kəˈleɪ.ʃən/', 'the filtration of a liquid for extraction or purification', NULL),
(2392, 'percolation', 1, '/ˌpɜː.kəˈleɪ.ʃən/', 'the act of making coffee in a percolator', NULL),
(2393, 'percolation', 1, '/ˌpɜː.kəˈleɪ.ʃən/', 'the slow passage of a liquid through a filtering medium', '\"the percolation of rainwater through the soil\"; \"the infiltration of seawater through the lava\"'),
(2394, 'reduction', 1, '/rɪˈdʌk.ʃən/', 'the act of reducing complexity', NULL),
(2395, 'reduction', 1, '/rɪˈdʌk.ʃən/', 'any process in which electrons are added to an atom or ion (as by removing oxygen or adding hydrogen); always occurs accompanied by oxidation of the reducing agent', NULL),
(2396, 'schematization', 1, '/ˌskiːmətʌɪˈzeɪʃən/', 'the act of reducing to a scheme or formula', NULL),
(2397, 'schematization', 1, '/ˌskiːmətʌɪˈzeɪʃən/', 'providing a chart or outline of a system', NULL),
(2398, 'economy', 1, '/iˈkɒn.ə.mi/', 'an act of economizing; reduction in cost', '\"it was a small economy to walk to work every day\"; \"there was a saving of 50 cents\"');
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(2399, 'economy', 1, '/iˈkɒn.ə.mi/', 'frugality in the expenditure of money or resources', '\"the Scots are famous for their economy\"'),
(2400, 'economy', 1, '/iˈkɒn.ə.mi/', 'the efficient use of resources', '\"economy of effort\"'),
