(2403, 'retrenchment', 1, '/rɪˈtrentʃ.mənt/', 'entrenchment consisting of an additional interior fortification to prolong the defense', NULL),
(2404, 'accommodation', 1, '/əˌkɒm.əˈdeɪ.ʃən/', '(physiology) the automatic adjustment in focal length of the natural lens of the eye', NULL),
