(3602, 'carry', 1, '/ˈkær.i/', 'the act of carrying something', NULL),
(3603, 'carry', 2, '/ˈkær.i/', 'continue or extend', '\"The civil war carried into the neighboring province\"; \"The disease extended into the remote mountain provinces\"'),
