(3629, 'carry', 2, '/ˈkær.i/', 'have or possess something abstract', '\"I carry her image in my mind\'s eye\"; \"I will carry the secret to my grave\"; \"I carry these thoughts in the back of my head\"; \"I carry a lot of life insurance\"'),
(3630, 'carry', 2, '/ˈkær.i/', 'keep up with financial support', '\"The Federal Government carried the province for many years\"'),
