(6506, 'thermotherapy', 1, '/ˌθɜːməʊˈθɛrəpɪ/', 'the use of heat to treat a disease or disorder; heating pads or hot compresses or hot-water bottles are used to promote circulation in peripheral vascular disease or to relax tense muscles', NULL);
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(6507, 'chiropractic', 1, '/ˌkaɪə.rəʊˈpræk.tɪk/', 'a method of treatment that manipulates body structures (especially the spine) to relieve low back pain or even headache or high blood pressure', NULL),
