(6510, 'disinfection', 1, '/ˌdɪs.ɪnˈfek.ʃən/', 'treatment to destroy harmful microorganisms', NULL),
(6511, 'chlorination', 1, '/ˌklɔːrɪˈneɪʃn/', 'disinfection of water by the addition of small amounts of chlorine or a chlorine compound', NULL),
