INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(7313, 'security', 1, '/sɪˈkjʊə.rə.ti/', 'defense against financial failure; financial independence', '\"his pension gave him security in his old age\"; \"insurance provided protection against loss of wages due to illness\"'),
(7314, 'security', 1, '/sɪˈkjʊə.rə.ti/', 'property that your creditor can claim in case you default on your obligation', '\"bankers are reluctant to lend without good security\"'),
(7315, 'security', 1, '/sɪˈkjʊə.rə.ti/', 'a formal declaration that documents a fact of relevance to finance and investment; the holder has a right to receive interest or dividends', '\"he held several valuable securities\"'),
(7316, 'security', 1, '/sɪˈkjʊə.rə.ti/', 'the state of being free from danger or injury', '\"we support the armed services in the name of national security\"'),
(7317, 'defense', 1, '/dɪˈfens/', 'the act of defending someone or something against attack or injury', '\"a good boxer needs a good defense\"; \"defense against hurricanes is an urgent problem\"'),
(7318, 'defense', 1, '/dɪˈfens/', 'protection from harm', '\"sanitation is the best defense against disease\"'),
(7319, 'defense', 1, '/dɪˈfens/', '(military) military action or resources protecting a country against potential enemies', '\"they died in the defense of Stalingrad\"; \"they were developed for the defense program\"'),
(7320, 'defense', 1, '/dɪˈfens/', 'a defendant\'s answer or plea denying the truth of the charges against him', '\"he gave evidence for the defense\"'),
(7321, 'defense', 1, '/dɪˈfens/', 'the justification for some act or belief', '\"he offered a persuasive defense of the theory\"'),
(7322, 'defense', 1, '/dɪˈfens/', 'an organization of defenders that provides resistance against attack', '\"he joined the defense against invasion\"'),
