(8106, 'use', 2, '/juːz/', 'put into service; make work or employ for a particular purpose or for its inherent or natural purpose', '\"use your head!\"; \"we only use Spanish at home\"; \"I can\'t use this tool\"; \"Apply a magnetic field here\"; \"This thinking was applied to many projects\"; \"How do you utilize this tool?\"; \"I apply this rule to get good results\"; \"use the plastic bags to store the food\"; \"He doesn\'t know how to use a computer\"'),
(8107, 'use', 2, '/juːz/', 'take or consume (regularly or habitually)', '\"She uses drugs rarely\"'),
(8108, 'use', 2, '/juːz/', 'habitually do something (use only in the past tense)', '\"She used to call her mother every week but now she calls only occasionally\"; \"I used to get sick when I ate in that dining hall\"; \"They used to vacation in the Bahamas\"'),
(8109, 'use', 2, '/juːz/', 'seek or achieve an end by using to one\'s advantage', '\"She uses her influential friends to get jobs\"; \"The president\'s wife used her good connections\"'),
