(14302, 'catchall', 1, '/ˈkætʃ.ɔːl/', 'an enclosure or receptacle for odds and ends', '\"The drawer became a catchall for old receipts and papers.\"'),
(14303, 'catchment', 1, '/ˈkætʃ.mənt/', 'a structure in which water is collected (especially a natural drainage area)', '\"The catchment area for the reservoir was vast and spread over several hills.\"'),
(14304, 'catgut', 1, '/ˈkæt.ɡʌt/', 'a strong cord made from the intestines of sheep and used in surgery', '\"He decided that proceedings from the sale of the catgut business should be used for a foundation to fund the library.\"'),
(14305, 'catgut', 1, '/ˈkæt.ɡʌt/', 'perennial subshrub of eastern North America having downy leaves yellowish and rose flowers and; source of rotenone', '\"Catgut is used in the production of certain musical instrument strings.\"'),
(14306, 'cathedra', 1, '/kəˈθiː.drə/', 'a throne that is the official chair of a bishop', '\"The bishop took his seat in the cathedra during the ceremony.\"'),
(14307, 'cathedral', 1, '/kəˈθiː.drəl/', 'any large and important church', '\"I was woken up by the chimes of the cathedral bells.\"'),
(14308, 'cathedral', 1, '/kəˈθiː.drəl/', 'the principal Christian church building of a bishop\'s diocese', '\"The wedding was held in the city\'s grand cathedral, which dates back to the 12th century.\"'),
(14309, 'cathedral', 3, '/kəˈθiː.drəl/', 'relating to or containing or issuing from a bishop\'s office or throne', '\"A cathedral church\"'),
(14310, 'catheter', 1, '/ˈkæθ.ə.tə(r)/', 'a thin flexible tube inserted into the body to permit introduction or withdrawal of fluids or to keep the passageway open', '\"The catheter was removed and the guide-wire was left in the distal vessel.\"'),
(14311, 'cathode', 1, '/ˈkæθ.əʊd/', 'a negatively charged electrode that is the source of electrons entering an electrical device', '\"In a vacuum tube, the cathode emits electrons toward the positively charged anode.\"'),
(14312, 'cathode', 1, '/ˈkæθ.əʊd/', 'the positively charged terminal of a voltaic cell or storage battery that supplies current', '\"In a battery, the cathode is where the current flows out during discharge.\"'),
(14313, 'catling', 1, '/ˈkæt.lɪŋ/', 'a long double-edged knife used for amputations', '\"NULL\"'),
(14314, 'catwalk', 1, '/ˈkæt.wɔːk/', 'narrow pathway high in the air (as above a stage or between parts of a building or along a bridge)', '\"The surgeon reached for the catling to begin the amputation procedure.\"'),
(14315, 'catwalk', 1, '/ˈkæt.wɔːk/', 'narrow platform extending out into an auditorium', '\"Models displayed clothes on a catwalk at the fashion show\"'),
(14316, 'causeway', 1, '/ˈkɔːz.weɪ/', 'a road that is raised above water or marshland or sand', '\"Several filtering techniques were employed to enhance causeways and other linear and curvilinear features.\"'),
(14317, 'causeway', 2, '/ˈkɔːz.weɪ/', 'pave a road with cobblestones or pebbles', '\"Workers were assigned to causeway the rural paths before the rainy season.\"'),
(14318, 'causeway', 2, '/ˈkɔːz.weɪ/', 'provide with a causeway', '\"A causewayed swamp\"'),
(14319, 'cefadroxil', 1, '/ˌsef.əˈdrɒk.sɪl/', 'a cephalosporin antibiotic (trade name Ultracef)', '\"NULL\"'),
(14320, 'cefotaxime', 1, '/ˌsef.əˈtæk.siːm/', 'a parenteral cephalosporin (trade name Claforan) used for severe infections of the lungs or throat or ears or urinary tract', '\"NULL\"'),
(14321, 'ceftazidime', 1, '/ˌsefˈtæz.ɪ.diːm/', 'a parenteral cephalosporin (trade names Fortaz and Tazicef) used to treat moderate infections', '\"NULL\"'),
(14322, 'ceftriaxone', 1, '/ˌsef.triˈæk.səʊn/', 'a parenteral cephalosporin (trade name Rocephin) used for severe infection of the lungs or throat or ears or urinary tract', '\"NULL\"');
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(14323, 'cefuroxime', 1, '/ˌsef.jʊˈrɒk.siːm/', 'a cephalosporin that can be given parenterally (trade name Zinacef) or orally by tablets (trade name Ceftin); indicated for infections of the lungs or throat or ears or urinary tract or meninges', '\"NULL\"'),
(14324, 'ceiling', 1, '/ˈsiː.lɪŋ/', 'the overhead upper surface of a covered space', '\"He hated painting the ceiling\"'),
(14325, 'ceiling', 1, '/ˈsiː.lɪŋ/', '(meteorology) altitude of the lowest layer of clouds', '\"The flight was delayed due to a low cloud ceiling over the airport.\"'),
(14326, 'ceiling', 1, '/ˈsiː.lɪŋ/', 'maximum altitude at which a plane can fly (under specified conditions)', '\"This fighter jet has a service ceiling of 50,000 feet.\"'),
(14327, 'ceiling', 1, '/ˈsiː.lɪŋ/', 'an upper limit on what is allowed', '\"He put a ceiling on the number of women who worked for him\"; \"there was a roof on salaries\"; \"they established a cap for prices\"'),
(14328, 'celecoxib', 1, '/ˌsɛləˈkɒksɪb/', 'a Cox-2 inhibitor (trade name Celebrex) that relieves pain and inflammation without harming the digestive tract', '\"Naproxen, celecoxib and rofecoxib, did not figure - possibly because of a low sample size.\"'),
(14329, 'celesta', 1, '/sɪˈles.tə/', 'a musical instrument consisting of graduated steel plates that are struck by hammers activated by a keyboard', '\"Tinkling chimes, celesta, glockenspiel, and harp set a magical tone.\"'),
(14330, 'cellar', 1, '/ˈsel.ər/', 'storage space where wines are stored', '\"He\'s got an impressively large store of wine in his cellar.\"'),
(14331, 'cellblock', 1, '/ˈsɛlˌblɒk/', 'a division of a prison (usually consisting of several cells)', '\"The cellblock was an addition erected later by the Sisterhood.\"'),
(14332, 'cello', 1, '/ˈtʃel.əʊ/', 'a large stringed instrument; seated player holds it upright while playing', '\"My girlfriend plays the cello.\"'),
(14333, 'cellophane', 1, '/ˈsel.ə.feɪn/', 'a transparent paperlike product that is impervious to moisture and used to wrap candy or cigarettes etc.', '\"The dessert buns were then wrapped individually in cellophane bags and stored in a freezer before shipping.\"'),
(14334, 'cenotaph', 1, '/ˈsen.ə.tɑːf/', 'a monument built to honor people whose remains are interred elsewhere or whose remains cannot be recovered', '\"These memorials to be erected in the schools should be regarded as a kind of cenotaph of those who have died.\"'),
(14335, 'censer', 1, '/ˈsen.sə/', 'a container for burning incense (especially one that is swung on a chain in a religious ritual)', '\"A priest began walking through the congregation swinging a censer.\"'),
(14336, 'centerboard', 1, '/ˈsɛntəˌbɔːd/', 'a retractable fin keel used on sailboats to prevent drifting to leeward', '\"You raise and lower a centerboard in a sailing boat so as to add keel.\"'),
(14337, 'centerpiece', 1, '/ˈsen.tə.piːs/', 'something placed at the center of something else (as on a table)', '\"A vase of fresh flowers served as the centerpiece on the dining table.\"'),
(14338, 'centerpiece', 1, '/ˈsen.tə.piːs/', 'the central or most important feature', '\"Education was the centerpiece of the Democratic Party\'s political platform\"'),
(14339, 'central', 1, '/ˈsen.trəl/', 'a workplace that serves as a telecommunications facility where lines from telephones can be connected together to permit communication', '\"The old building once served as the central for all local telephone connections.\"'),
(14340, 'central', 3, '/ˈsen.trəl/', 'in or near a center or constituting a center; the inner area', '\"A central position\"'),
(14341, 'centrex', 1, '/ˈsen.treks/', '(CENTRal EXchange) a kind of telephone exchange', '\"The company uses a Centrex system to manage internal and external calls efficientl\"'),
(14342, 'centrifuge', 1, '/ˈsen.trɪ.fjuːdʒ/', 'an apparatus that uses centrifugal force to separate particles from a suspension', '\"Lysed cells were centrifuged at 2500 g for 15 min and the pellet containing unbroken cells, nuclei, and kinetoplasts was discarded.\"'),
(14343, 'centrifuge', 2, '/ˈsen.trɪ.fjuːdʒ/', 'rotate at very high speed in order to separate the liquids from the solids', '\"The laboratory used a centrifuge to isolate the blood plasma from the cells.\"'),
(14344, 'cephalexin', 1, '/ˌsef.əˈlek.sɪn/', 'an oral cephalosporin (trade names Keflex and Keflin and Keftab) commonly prescribe for mild to moderately severe infections of the skin or ears or throat or lungs or urinary tract', '\"There was also what appeared to be his medicine: cephalexin [an antibiotic], acetaminophen and potassium drops.\"'),
(14345, 'cephalosporin', 1, '/ˌsef.ə.ləˈspɔː.rɪn/', 'one of several broad spectrum antibiotic substances obtained from fungi and related to penicillin (trade names Mefoxin); addition of side chains has produced semisynthetic antibiotics with greater antibacterial activity', '\"The doctor prescribed a cephalosporin to treat the bacterial infection.\"'),
(14346, 'ceramic', 1, '/səˈræm.ɪk/', 'an artifact made of hard brittle material produced from nonmetallic minerals by firing at high temperatures', '\"The robot is made of metal, ceramic, and other materials.\"'),
(14347, 'ceramic', 3, '/səˈræm.ɪk/', 'of or relating to or made from a ceramic', '\"A ceramic dish\"'),
(14348, 'cesspool', 1, '/ˈses.puːl/', 'a covered cistern; waste water and sewage flow into it', '\"He described government there as a cesspool of corruption.\"'),
(14349, 'chador', 1, '/ˈtʃɑː.də/', 'a cloth used as a head covering (and veil and shawl) by Muslim and Hindu women', '\"A female student was given a pair of metal cutters to break the chains locking the embassy\'s gates, and she hid them beneath her chador.\"'),
(14350, 'chaff', 1, '/tʃæf/', 'foil in thin strips; ejected into the air as a radar countermeasure', '\"The jet released chaff to evade the enemy\'s radar-guided missiles.\"'),
(14351, 'chaff', 1, '/tʃæf/', 'material consisting of seed coverings and small pieces of stem or leaves that have been separated from the seeds', '\"Farmers separate the grain from the chaff using a winnowing basket.\"'),
(14352, 'chain', 1, '/tʃeɪn/', 'a series of (usually metal) rings or links fitted into one another to make a flexible ligament', '\"As part of the centenary celebrations a chain of beacons was lit across the country.\"'),
(14353, 'chain', 1, '/tʃeɪn/', 'a necklace made by a stringing objects together; \"a strand of pearls\";', '\"a string of beads\"'),
(14354, 'chain', 1, '/tʃeɪn/', 'anything that acts as a restraint', '\" He broke free from the chain that held him to the wall.\"'),
(14355, 'chain', 1, '/tʃeɪn/', 'a linked or connected series of objects', '\"A chain of daisies\"'),
(14356, 'chain', 1, '/tʃeɪn/', '(business) a number of similar establishments (stores or restaurants or banks or hotels or theaters) under one ownership', '\"McDonald\'s is a global fast-food chain with thousands of restaurants.\"'),
(14357, 'chain', 1, '/tʃeɪn/', 'a series of things depending on each other as if linked together', '\"The chain of command\"; \"a complicated concatenation of circumstances\"'),
(14358, 'chain', 1, '/tʃeɪn/', '(chemistry) a series of linked atoms (generally in an organic molecule)', '\"The carbon atoms form a long chain in the compound.\"'),
(14359, 'chain', 1, '/tʃeɪn/', 'a unit of length', '\"The land was measured at ten chains in length.\"'),
(14360, 'chain', 2, '/tʃeɪn/', 'fasten or secure with chains', '\"Chain the chairs together\"'),
(14361, 'chain', 2, '/tʃeɪn/', 'connect or arrange into a chain by linking', '\"The prisoners were chained together by their ankles.\"'),
(14362, 'chair', 1, '/tʃeər/', 'a seat for one person, with a support for the back', '\"he put his coat over the back of the chair and sat down\"'),
(14363, 'chair', 1, '/tʃeər/', 'a particular seat in an orchestra', '\"he is second chair violin\"'),
(14364, 'chair', 2, '/tʃeər/', 'act or preside as chair, as of an academic department in a university', '\"She chaired the department for many years\"'),
(14365, 'chairlift', 1, '/ˈtʃeər.lɪft/', 'a ski lift on which riders (skiers or sightseers) are seated and carried up or down a mountainside; seats are hung from an endless overhead cable', '\"Tourists use the chairlifts in summer so that they can walk on the top of the mountain.\"'),
(14366, 'chaise', 1, '/ʃeɪz/', 'a carriage consisting of two wheels and a calash top; drawn by a single horse', '\"She stepped down from the chaise and looked around her.\"'),
(14367, 'chalet', 1, '/ˈʃæl.eɪ/', 'a Swiss house with a sloping roof and wide eaves or a house built in this style', '\"The chalet has a spa with saunas and a steam room.\"'),
(14368, 'chalice', 1, '/ˈtʃæl.ɪs/', 'a bowl-shaped drinking vessel; especially the Eucharistic cup', '\"A handsome priest in a cream linen suit was moving among the men, distributing Communion wafers from a wooden chalice.\"'),
(14369, 'chalk', 1, '/tʃɔːk/', 'a piece of calcite or a similar substance, usually in the shape of a crayon, that is used to write or draw on blackboards or other flat surfaces', '\"Her skin was chalk white and dry-looking.\"'),
(14370, 'chalk', 1, '/tʃɔːk/', 'a pure flat white with little reflectance', '\"She painted the wall with a chalk white color.\"'),
(14371, 'chalk', 1, '/tʃɔːk/', 'a soft whitish calcite', '\"The teacher wrote on the blackboard with a piece of chalk.\"'),
(14372, 'chalk', 2, '/tʃɔːk/', 'write, draw, or trace with chalk', '\"He chalked the message on the blackboard. \"'),
(14373, 'challis', 1, '/ˈʃælɪ/', 'a soft lightweight fabric (usually printed)', '\"She wore a challis dress with floral patterns.\"'),
(14374, 'chamber', 1, '/ˈtʃeɪm.bə/', 'a natural or artificial enclosed space', '\"The cave had a hidden chamber filled with crystals.\"'),
(14375, 'chamber', 1, '/ˈtʃeɪm.bə/', 'a room where a judge transacts business', '\"The lawyer met the judge privately in his chamber.\"'),
(14376, 'chamber', 1, '/ˈtʃeɪm.bə/', 'an enclosed volume in the body', '\"The chambers of his heart were healthy\"'),
(14377, 'chamber', 1, '/ˈtʃeɪm.bə/', 'a deliberative or legislative or administrative or judicial assembly', '\"The upper chamber is the senate\"'),
(14378, 'chamber', 2, '/ˈtʃeɪm.bə/', 'place in a chamber', '\"The upper chamber passed the bill with a majority vote.\"'),
(14379, 'chamberpot', 1, '/ˈtʃeɪmbəˌpɒt/', 'a receptacle for urination or defecation in the bedroom', '\"Beyond that, though, it\'s all so chic and wafty, and, despite the recurrent use of the chamberpot, so clean.\"'),
(14380, 'chambray', 1, '/ˈʃæmbreɪ/', 'a lightweight fabric woven with white threads across a colored warp', '\"Blue jeans and light blue denim or chambray work shirts became the norm, a tradition still followed in some state prison systems today.\"'),
(14381, 'chancel', 1, '/ˈtʃæn.səl/', 'area around the altar of a church for the clergy and choir; often enclosed by a lattice or railing', '\"These seats were usually close to the chancel, and sometimes within it.\"'),
(14382, 'chancellery', 1, '/ˈtʃæn.səl.ər.i/', 'a government building housing the office of a chancellor', '\"The chancellery very actively dealt with personnel questions and staffing for all state institutions with f unctionaries of different specialties and ranks.\"'),
(14383, 'chancery', 1, '/ˈtʃɑːn.sə.ri/', 'an office of archives for public or ecclesiastic records; a court of public records', '\"Historical land deeds were stored in the chancery.\"'),
(14384, 'chancery', 1, '/ˈtʃɑːn.sə.ri/', 'a court with jurisdiction in equity', '\"The dispute over the will was settled in the chancery court.\"'),
(14385, 'chandelier', 1, '/ˌʃæn.dəˈlɪər/', 'branched lighting fixture; often ornate; hangs from the ceiling', '\"A gorgeous crystal chandelier hung in the dining room.\"'),
(14386, 'chandlery', 1, '/ˈtʃɑːnd.lər.i/', 'a storeroom where candles are kept', '\"He opened the old chandlery and found dozens of wax candles.\"'),
(14387, 'chandlery', 1, '/ˈtʃɑːnd.lər.i/', 'candles and other commodities sold by a chandler', '\" The ship stopped to buy supplies at the chandlery.\"'),
(14388, 'channel', 1, '/ˈtʃæn.əl/', 'a passage for water (or other fluids) to flow through', '\"The fields were crossed with irrigation channels\"; \"gutters carried off the rainwater into a series of channels under the street\"'),
(14389, 'channel', 1, '/ˈtʃæn.əl/', 'a television station and its programs', '\"a satellite TV channel\"; \"surfing through the channels\"; \"they offer more than one hundred channels\"'),
(14390, 'channel', 1, '/ˈtʃæn.əl/', 'a path over which electrical signals can pass', '\"a channel is typically what you rent from a telephone company\"'),
(14391, 'channel', 1, '/ˈtʃæn.əl/', '(often plural) a means of communication or access', '\"It must go through official channels\"; \"lines of communication were set up between the two firms\"'),
(14392, 'channel', 1, '/ˈtʃæn.əl/', 'a deep and relatively narrow body of water (as in a river or a harbor or a strait linking two larger bodies) that allows the best passage for vessels', '\"The ship went aground in the channel\"'),
(14393, 'channel', 2, '/ˈtʃæn.əl/', 'direct the flow of', '\"Channel information towards a broad audience\"'),
(14394, 'chanter', 1, '/ˈtʃæn.tə/', 'reed pipe with finger holes on which the melody is played', '\"A piper marched beside him, the black bag of his pipes under his arm, the chanter blowing a reel.\"'),
(14395, 'chantry', 1, '/ˈtʃɑːntrɪ/', 'a chapel endowed for singing Masses for the soul of the donor', '\"He left money in his will to build a chantry in the cathedral.\"'),
(14396, 'chantry', 1, '/ˈtʃɑːntrɪ/', 'an endowment for the singing of Masses', '\"The chantry ensured that Masses would be sung in his memory for years.\"'),
(14397, 'chap', 1, '/tʃæp/', '(usually in the plural) leather leggings without a seat; joined by a belt; often have flared outer flaps; worn over trousers by cowboys to protect their legs', '\"The cowboy pulled on his chaps before heading into the brush.\"'),
(14398, 'chap', 1, '/tʃæp/', 'a crack in a lip caused usually by cold', '\"The cold wind left a painful chap on her lower lip.\"'),
(14399, 'chap', 1, '/tʃæp/', 'a boy or man', '\"That chap is your host\"; \"there\'s a fellow at the door\"; \"he\'s a likable cuss\"; \"he\'s a good bloke.\"'),
(14400, 'chap', 2, '/tʃæp/', 'crack due to dehydration', '\"My lips chap in this dry weather.\"'),
(14401, 'chapel', 1, '/ˈtʃæp.əl/', 'a place of worship that has its own altar', '\"They meet in an old house, whose basement has been converted into a chapel.\"'),
(14402, 'chapterhouse', 1, '/ˈtʃæptəˌhaʊs/', 'a house used as a residence by a chapter of a fraternity', '\"The fraternity held its weekly meeting at the chapterhouse.\"'),
(14403, 'chapterhouse', 1, '/ˈtʃæptəˌhaʊs/', 'a building attached to a monastery or cathedral; used as a meeting place for the chapter', '\"The monks gathered in the chapterhouse every morning for discussion.\"'),
(14404, 'charcoal', 1, '/ˈtʃɑː.kəʊl/', 'a stick of black carbon material used for drawing', '\"She sketched the landscape using a piece of charcoal.\"'),
(14405, 'charcoal', 1, '/ˈtʃɑː.kəʊl/', 'a drawing made with a stick of black carbon material', '\"His latest charcoal shows a mountain scene at sunset.\"'),
(14406, 'charcoal', 1, '/ˈtʃɑː.kəʊl/', 'a very dark grey color', '\" She chose a charcoal suit for the interview.\"'),
(14407, 'charcoal', 1, '/ˈtʃɑː.kəʊl/', 'a carbonaceous material obtained by heating wood or other organic matter in the absence of air', '\"I prefer sketching in charcoal to pencil.\"'),
(14408, 'charcoal', 2, '/ˈtʃɑː.kəʊl/', 'draw, trace, or represent with charcoal', '\"The artist carefully charcoaled the shadows for depth.\"'),
(14409, 'charcoal', 3, '/ˈtʃɑː.kəʊl/', 'of a very dark grey', '\"She wore a charcoal dress that matched her heels.\"'),
(14410, 'charcuterie', 1, '/ʃɑːrˈkuː.tə.ri/', 'a delicatessen that specializes in meats', '\"You might serve a plate of charcuterie to start.\"'),
(14411, 'chariot', 1, '/ˈtʃær.i.ət/', 'a light four-wheel horse-drawn ceremonial carriage', '\"NULL\"'),
(14412, 'chariot', 1, '/ˈtʃær.i.ət/', 'a two-wheeled horse-drawn battle vehicle; used in war and races in ancient Egypt and Greece and Rome', '\"NULL\"'),
(14413, 'chariot', 2, '/ˈtʃær.i.ət/', 'ride in a chariot', '\"NULL\"'),
(14414, 'chariot', 2, '/ˈtʃær.i.ət/', 'transport in a chariot', '\"NULL\"'),
(14415, 'charm', 1, '/tʃɑːm/', 'something believed to bring good luck', '\"NULL\"'),
(14416, 'charm', 1, '/tʃɑːm/', '(physics) one of the six flavors of quark', '\"NULL\"'),
(14417, 'charm', 2, '/tʃɑːm/', 'induce into action by using one\'s charm', '\"She charmed him into giving her all his money.\"'),
(14418, 'charm', 2, '/tʃɑːm/', 'protect through supernatural powers or charms', '\"NULL\"'),
(14419, 'charm', 2, '/tʃɑːm/', 'control by magic spells, as by practicing witchcraft', '\"NULL\"'),
(14420, 'chart', 1, '/tʃɑːt/', 'a map designed to assist navigation by air or sea', '\"NULL\"'),
(14421, 'chart', 1, '/tʃɑːt/', 'a visual display of information', '\"NULL\"'),
(14422, 'chart', 2, '/tʃɑːt/', 'plan in detail', '\"Bush is charting a course to destroy Saddam Hussein.\"'),
(14423, 'chart', 2, '/tʃɑːt/', 'make a chart of', '\"Chart the territory\"'),
(14424, 'charterhouse', 1, '/ˈtʃɑː.tər.haʊs/', 'a Carthusian monastery', '\"The ruins of the old charterhouse still attract historians and tourists alike.\"'),
(14425, 'chase', 1, '/tʃeɪs/', 'a rectangular metal frame used in letterpress printing to hold together the pages or columns of composed type that are printed at one time', '\"The typesetter carefully locked the letters into the chase before printing.\"'),
(14426, 'chase', 2, '/tʃeɪs/', 'cut a groove into', '\"Chase silver\"'),
(14427, 'chase', 2, '/tʃeɪs/', 'go after with the intent to catch', '\"The policeman chased the mugger down the alley\"; \"the dog chased the rabbit.\"'),
(14428, 'chase', 2, '/tʃeɪs/', 'pursue someone sexually or romantically', '\"She\'s always chasing after men.\"'),
(14429, 'chassis', 1, '/ˈʃæs.i/', 'the skeleton of a motor vehicle consisting of a steel frame supported on springs that holds the body and motor', '\"The car\'s lightweight chassis is made from aluminium sheets.\"'),
(14430, 'chassis', 1, '/ˈʃæs.i/', 'a metal mounting for the circuit components of an electronic device', '\"The technician replaced the damaged chassis of the amplifier.\"'),
(14431, 'chasuble', 1, '/ˈtʃæzjʊbəl/', 'a long sleeveless vestment worn by a priest when celebrating Mass', '\"Priests will generally be vested in an alb and stole and also, in many instances, a chasuble.\"'),
(14432, 'chateau', 1, '/ˈʃæt.əʊ/', 'an impressive country house (or castle) in France', '\"The battalion headquarters were in a ruined chateau.\"'),
(14433, 'chatelaine', 1, '/ˈʃæt.əl.eɪn/', 'a chain formerly worn at the waist by women; for carrying a purse or bunch of keys etc.', '\"The Victorian lady wore a silver chatelaine with keys and scissors attached.\"'),
(14434, 'chatelaine', 1, '/ˈʃæt.əl.eɪn/', 'the mistress of a chateau or large country house', '\"She was the mistress of a large country house, a chatelaine well accustomed to providing for unexpected guests.\"'),
(14435, 'checker', 1, '/ˈtʃek.ə/', 'one of the flat round pieces used in playing the game of checkers', '\"He moved the red checker across the board.\"'),
(14436, 'checker', 1, '/ˈtʃek.ə/', 'one who checks the correctness of something', '\"The quality checker found a flaw in the product.\"'),
(14437, 'checker', 1, '/ˈtʃek.ə/', 'an attendant who checks coats or baggage', '\"The coat checker gave me a numbered ticket.\"'),
(14438, 'checker', 2, '/ˈtʃek.ə/', 'variegate with different colors, shades, or patterns', '\"The artist checker the floor with bold colors.\"'),
(14439, 'checkerboard', 1, '/ˈtʃek.ər.bɔːd/', 'a board having 64 squares of two alternating colors', '\"They play on giant checkerboards made of large light and dark marble squares.\"'),
(14440, 'checkout', 1, '/ˈtʃek.aʊt/', 'a counter in a supermarket where you pay for your purchases', '\"Your fruit and vegetables will be weighed at the checkout.\"'),
