INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(22301, 'diligence', 1, '/ˈdɪl.ɪ.dʒəns/', 'persevering determination to perform a task', '\"His diligence won him quick promotions\"; \"Frugality and industry are still regarded as virtues\"'),
