(22303, 'nonchalance', 1, '/ˌnɒn.ʃəˈlɒns/', 'the trait of remaining calm and seeming not to care; a casual lack of concern', NULL),
(22304, 'recommendation', 1, '/ˌrek.ə.menˈdeɪ.ʃən/', 'any quality or characteristic that gains a person a favorable reception or acceptance or admission', '\"her pleasant personality is already a recommendation\"; \"his wealth was not a passport into the exclusive circles of society\"'),
(22305, 'recommendation', 1, '/ˌrek.ə.menˈdeɪ.ʃən/', 'something (as a course of action) that is recommended as advisable', NULL),
(22306, 'recommendation', 1, '/ˌrek.ə.menˈdeɪ.ʃən/', 'something that recommends (or expresses commendation of) a person or thing as worthy or desirable', NULL),
(22307, 'color', 1, '/ˈkʌlə/', 'the appearance of objects (or light sources) described in terms of a person\'s perception of their hue and lightness (or brightness) and saturation', NULL),
(22308, 'color', 1, '/ˈkʌlə/', 'a visual attribute of things that results from the light they emit or transmit or reflect', '\"a white color is made up of many different wavelengths of light\"'),
(22309, 'color', 1, '/ˈkʌlə/', 'the timbre of a musical sound', '\"The recording fails to capture the true color of the original music\"'),
(22310, 'color', 1, '/ˈkʌlə/', 'interest and variety and intensity', '\"the Puritan Period was lacking in color\"; \"The characters were delineated with exceptional vividness\"'),
(22311, 'color', 1, '/ˈkʌlə/', '(physics) the characteristic of quarks that determines their role in the strong interaction', '\"Each flavor of quarks comes in three colors\"'),
(22312, 'color', 1, '/ˈkʌlə/', 'a race with skin pigmentation different from the white race (especially Blacks)', NULL),
(22313, 'color', 2, '/ˈkʌlə/', 'add color to', '\"The child colored the drawings\"; \"Fall colored the trees\"; \"colorize black and white film\"'),
(22314, 'color', 2, '/ˈkʌlə/', 'give a deceptive explanation or excuse for', '\"Color a lie\"'),
(22315, 'color', 2, '/ˈkʌlə/', 'decorate with colors', '\"Color the walls with paint in warm tones\"'),
(22316, 'color', 2, '/ˈkʌlə/', 'modify or bias', '\"His political ideas color his lectures\"'),
(22317, 'color', 3, '/ˈkʌlə/', 'having or capable of producing colors', '\"color film\"; \"He rented a color television\"; \"Marvelous color illustrations\"'),
(22318, 'image', 1, '/ˈɪm.ɪdʒ/', 'the general impression that something (a person or organization or product) presents to the public', '\"although her popular image was contrived it served to inspire music and pageantry\"; \"the company tried to project an altruistic image\"'),
(22319, 'image', 1, '/ˈɪm.ɪdʒ/', 'an iconic mental representation', '\"her imagination forced images upon her too awful to contemplate\"'),
(22320, 'image', 1, '/ˈɪm.ɪdʒ/', '(mathematics) the set of values of the dependent variable for which a function is defined', '\"the image of f(x) = x^2 is the set of all non-negative real numbers if the domain of the function is the set of all real numbers\"'),
(22321, 'image', 2, '/ˈɪm.ɪdʒ/', 'render visible, as by means of MRI', NULL),
