(22666, 'ultimate', 3, '/ˈʌl.tɪ.mət/', 'furthest or highest in degree or order; utmost or extreme', '\"The ultimate achievement\"; \"The ultimate question\"; \"man\'s ultimate destiny\"; \"the ultimate insult\"; \"one\'s ultimate goal in life\"'),
(22667, 'expansiveness', 1, '/ɪkˈspæn.sɪv.nəs/', 'a quality characterized by magnificence of scale or the tendency to expand', '\"the expansiveness of their extravagant life style was soon curtailed\"'),
(22668, 'stateliness', 1, '/ˈsteɪt.li.nəs/', 'impressiveness in scale or proportion', NULL),
(22669, 'stateliness', 1, '/ˈsteɪt.li.nəs/', 'an elaborate manner of doing something', '\"she served coffee with great stateliness\"'),
(22670, 'ingenuity', 1, '/ˌɪn.dʒəˈnjuː.ə.ti/', 'the property of being ingenious', '\"a plot of great ingenuity\"; \"the cleverness of its design\"'),
(22671, 'inferiority', 1, '/ɪnˌfɪə.riˈɒr.ə.ti/', 'an inferior quality', NULL),
(22672, 'inferiority', 1, '/ɪnˌfɪə.riˈɒr.ə.ti/', 'the quality of being a competitive disadvantage', NULL),
(22673, 'inferiority', 1, '/ɪnˌfɪə.riˈɒr.ə.ti/', 'the state of being inferior', NULL),
(22674, 'poorness', 1, '/ˈpɔːnəs/', 'the quality of being poorly made or maintained', '\"she was unrecognizable because of the poorness of the photography\"'),
(22675, 'poorness', 1, '/ˈpɔːnəs/', 'less than adequate', '\"the relative poorness of New England farmland\"'),
(22676, 'wretchedness', 1, '/ˈretʃ.ɪd.nəs/', 'the quality of being poor and inferior and sorry', '\"he has compiled a record second to none in its wretchedness\"'),
(22677, 'wretchedness', 1, '/ˈretʃ.ɪd.nəs/', 'the character of being uncomfortable and unpleasant', '\"the wretchedness for which these prisons became known\"; \"the grey wretchedness of the rain\"'),
(22678, 'characteristic', 1, '/ˌkær.ək.təˈrɪs.tɪk/', 'a distinguishing quality', NULL),
(22679, 'characteristic', 1, '/ˌkær.ək.təˈrɪs.tɪk/', 'any measurable property of a device measured under closely specified conditions', NULL),
(22680, 'characteristic', 1, '/ˌkær.ək.təˈrɪs.tɪk/', 'the integer part (positive or negative) of the representation of a logarithm; in the expression log 643 = 2.808 the characteristic is 2', NULL);
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(22681, 'characteristic', 3, '/ˌkær.ək.təˈrɪs.tɪk/', 'typical or distinctive', '\"heard my friend\'s characteristic laugh\"; \"red and gold are the characteristic colors of autumn\"; \"stripes characteristic of the zebra\"'),
(22682, 'salability', 1, '/ˌseɪ.ləˈbɪl.ə.ti/', 'the quality of being salable or marketable', NULL),
(22683, 'hallmark', 1, '/ˈhɔːl.mɑːk/', 'a distinctive characteristic or attribute', NULL),
(22684, 'aspect', 1, '/ˈæs.pekt/', 'a characteristic to be considered', NULL),
(22685, 'aspect', 1, '/ˈæs.pekt/', 'a distinct feature or element in a problem', '\"he studied every facet of the question\"'),
(22686, 'aspect', 1, '/ˈæs.pekt/', 'the beginning or duration or completion or repetition of the action of a verb', NULL),
(22687, 'fluidity', 1, '/fluːˈɪd.ə.ti/', 'a changeable quality', '\"a charming Oriental fluidity of manner\"; \"a certain fluidness in his perception of time made him an unpredictable colleague\"; \"demographers try to predict social fluidity\"'),
(22688, 'fluidity', 1, '/fluːˈɪd.ə.ti/', 'the property of flowing easily', '\"adding lead makes the alloy easier to cast because the melting point is reduced and the fluidity is increased\"; \"they believe that fluidity increases as the water gets warmer\"'),
(22689, 'reversibility', 1, '/rɪˌvɜː.səˈbɪl.ə.ti/', 'the quality of being reversible in either direction', NULL),
(22690, 'shiftiness', 1, '/ˈʃɪf.ti.nəs/', 'the quality of being changeable in direction', '\"the shiftiness of the wind caused the boat to veer unpredictably\"'),
(22691, 'inconstancy', 1, '/ɪnˈkɒn.stən.si/', 'the quality of being changeable and variable', NULL),
(22692, 'capriciousness', 1, '/kəˈprɪʃ.əs.nəs/', 'the quality of being guided by sudden unpredictable impulses', NULL),
(22693, 'variability', 1, '/ˌveə.ri.əˈbɪl.ə.ti/', 'the quality of being subject to variation', NULL),
(22694, 'diversity', 1, '/daɪˈvɜː.sə.ti/', 'the condition or result of being changeable', NULL),
(22695, 'variegation', 1, '/ˌveə.ri.ɪˈɡeɪ.ʃən/', 'variability in coloration', NULL),
(22696, 'exchangeability', 1, '/ɪkˌs.tʃeɪn.dʒəˈbɪl.ə.ti/', 'the quality of being capable of exchange or interchange', NULL),
(22697, 'duality', 1, '/djuːˈæl.ə.ti/', '(geometry) the interchangeability of the roles of points and planes in the theorems of projective geometry', NULL),
(22698, 'duality', 1, '/djuːˈæl.ə.ti/', '(physics) the property of matter and electromagnetic radiation that is characterized by the fact that some properties can be explained best by wave theory and others by particle theory', NULL),
(22699, 'transferability', 1, '/trænsˈfɜː.rə.bɪl.ə.ti/', 'the quality of being transferable or exchangeable', '\"sterling transferability affords a means of multilateral settlement for....trade between nondollar countries\"'),
(22700, 'convertibility', 1, '/kənˌvɜː.təˈbɪl.ə.ti/', 'the quality of being exchangeable (especially the ability to convert a currency into gold or other currencies without restriction)', NULL),
(22701, 'liquidity', 1, '/lɪˈkwɪd.ə.ti/', 'being in cash or easily convertible to cash; debt paying ability', NULL),
(22702, 'progressiveness', 1, '/prəˈɡres.ɪv.nəs/', 'advancement toward better conditions or policies or methods', NULL),
(22703, 'absoluteness', 1, '/ˌæb.səˈluːt.nəs/', 'the quality of being absolute', '\"The absoluteness of the pope\'s decree could not be challenged\"'),
(22704, 'constancy', 1, '/ˈkɒn.stən.si/', 'the quality of being enduring and free from change or variation', '\"Early mariners relied on the constancy of the trade winds\"'),
(22705, 'constancy', 1, '/ˈkɒn.stən.si/', 'faithfulness and dependability in personal attachments (especially sexual fidelity)', NULL),
(22706, 'constancy', 1, '/ˈkɒn.stən.si/', '(psychology) the tendency for perceived objects to give rise to very similar perceptual experiences in spite of wide variations in the conditions of observation', NULL),
(22707, 'invariance', 1, '/ɪnˈveə.ri.əns/', 'the nature of a quantity or property or function that remains unchanged when a given transformation is applied to it', '\"The invariance of the configuration under translation\"'),
(22708, 'metastability', 1, '/ˌmet.əˈsteɪ.bɪl.ə.ti/', 'the quality of a physical system that persists in its existing equilibrium when undisturbed (or only slightly disturbed) but able to pass to a more stable equilibrium when sufficiently disturbed', NULL),
(22709, 'monotony', 1, '/məˈnɒt.ən.i/', 'constancy of tone or pitch or inflection', NULL),
(22710, 'monotony', 1, '/məˈnɒt.ən.i/', 'the quality of wearisome constancy, routine, and lack of variety', '\"He had never grown accustomed to the monotony of his work\"; \"he was sick of the humdrum of his fellow prisoners\"; \"he hated the sameness of the food the college served\"'),
(22711, 'innateness', 1, '/ɪˈneɪt.nəs/', 'the quality of being innate', NULL),
(22712, 'irreversibility', 1, '/ɪˌrev.ɜː.səˈbɪl.ə.ti/', 'the quality of being irreversible (once done it cannot be changed)', NULL),
(22713, 'fixedness', 1, '/ˈfɪkst.nəs/', 'the quality of being fixed and unchangeable', '\"The fixedness of his gaze upset her\"'),
(22714, 'mutability', 1, '/ˌmjuː.təˈbɪl.ə.ti/', 'the quality of being capable of mutation', NULL),
(22715, 'vicissitude', 1, '/vɪˈsɪs.ɪ.tjuːd/', 'mutability in life or nature (especially successive alternation from one condition to another)', NULL),
(22716, 'vicissitude', 1, '/vɪˈsɪs.ɪ.tjuːd/', 'a variation in circumstances or fortune at different times in your life or in the development of something', '\"The project was subject to the usual vicissitudes of exploratory research\"'),
(22717, 'immutability', 1, '/ɪˌmjuː.təˈbɪl.ə.ti/', 'the quality of being incapable of mutation', '\"Darwin challenged the fixity of species\"'),
(22718, 'agelessness', 1, '/ˈeɪdʒlᵻsnᵻs/', 'the quality of being timeless and eternal', NULL),
(22719, 'sameness', 1, '/ˈseɪm.nəs/', 'the quality of being alike', '\"Sameness of purpose kept them together\"'),
(22720, 'otherness', 1, '/ˈʌð.ə.nəs/', 'the quality of being not alike; being distinct or different from that otherwise experienced or known', NULL),
(22721, 'oneness', 1, '/ˈwʌn.nəs/', 'the quality of being united into one', NULL),
(22722, 'similarity', 1, '/ˌsɪm.ɪˈlær.ə.ti/', 'the quality of being similar', NULL),
(22723, 'similarity', 1, '/ˌsɪm.ɪˈlær.ə.ti/', 'a Gestalt principle of organization holding that (other things being equal) parts of a stimulus field that are similar to each other tend to be perceived as belonging together as a unit', NULL),
(22724, 'homology', 1, '/həˈmɒl.ə.dʒi/', 'the quality of being similar or corresponding in position or value or structure or function', NULL),
(22725, 'homomorphism', 1, '/ˌhəʊməʊˈmɔːfɪzəm/', 'similarity of form', NULL),
(22726, 'isomorphism', 1, '/ˌaɪsəʊˈmɔːfɪzəm/', '(biology) similarity or identity of form or shape or structure', NULL),
(22727, 'parallelism', 1, '/ˈpær.ə.lel.ɪ.zəm/', 'similarity by virtue of corresponding', NULL),
(22728, 'uniformity', 1, '/ˌjuː.nɪˈfɔː.mɪ.ti/', 'the quality of lacking diversity or variation (even to the point of boredom)', NULL),
(22729, 'uniformity', 1, '/ˌjuː.nɪˈfɔː.mɪ.ti/', 'a condition in which everything is regular and unvarying', NULL),
(22730, 'homogeneity', 1, '/ˌhɒm.ə.dʒɪˈniː.ə.ti/', 'the quality of being similar or comparable in kind or nature', '\"There is a remarkable homogeneity between the two companies\"'),
(22731, 'homogeneity', 1, '/ˌhɒm.ə.dʒɪˈniː.ə.ti/', 'the quality of being of uniform throughout in composition or structure', NULL),
(22732, 'consistency', 1, '/kənˈsɪs.tən.si/', 'a harmonious uniformity or agreement among things or parts', NULL),
(22733, 'consistency', 1, '/kənˈsɪs.tən.si/', '(logic) an attribute of a logical system that is so constituted that none of the propositions deducible from the axioms contradict one another', NULL),
(22734, 'consistency', 1, '/kənˈsɪs.tən.si/', 'the property of holding together and retaining its shape', '\"Wool has more body than rayon\"; \"When the dough has enough consistency it is ready to bake\"'),
(22735, 'consistency', 1, '/kənˈsɪs.tən.si/', 'logical coherence and accordance with the facts', '\"a rambling argument that lacked any consistency\"'),
(22736, 'sort', 1, '/sɔːt/', 'an approximate definition or example', '\"She wore a sort of magenta dress\"; \"she served a creamy sort of dessert thing\"'),
(22737, 'sort', 1, '/sɔːt/', 'a person of a particular character or nature', '\"What sort of person is he?\"; \"He\'s a good sort\"'),
(22738, 'sort', 1, '/sɔːt/', 'an operation that segregates items into groups according to a specified criterion', '\"The bottleneck in mail delivery is the process of sorting\"'),
(22739, 'analogue', 1, '/ˈæn.ə.lɒɡ/', 'something having the property of being analogous to something else', NULL),
(22740, 'analogue', 3, '/ˈæn.ə.lɒɡ/', 'of a circuit or device having an output that is proportional to the input', '\"Analogue device\"; \"Linear amplifier\"'),
(22741, 'naturalness', 1, '/ˈnætʃ.ər.əl.nəs/', 'the likeness of a representation to the thing represented', '\"engineers strove to increase the naturalness of recorded music\"'),
(22742, 'naturalness', 1, '/ˈnætʃ.ər.əl.nəs/', 'the quality of being natural or based on natural principles', '\"he accepted the naturalness of death\"; \"the spontaneous naturalness of his manner\"'),
(22743, 'resemblance', 1, '/rɪˈzem.bləns/', 'similarity in appearance or external or superficial details', NULL),
(22744, 'equality', 1, '/iˈkwɒl.ə.ti/', 'the quality of being the same in quantity or measure or value or status', NULL),
(22745, 'equality', 1, '/iˈkwɒl.ə.ti/', 'a state of being essentially equal or equivalent; equally balanced', '\"On a par with the best\"'),
(22746, 'equivalence', 1, '/ɪˈkwɪv.əl.əns/', 'essential equality and interchangeability', NULL),
(22747, 'parity', 1, '/ˈpær.ə.ti/', 'functional equality', NULL),
(22748, 'parity', 1, '/ˈpær.ə.ti/', '(physics) parity is conserved in a universe in which the laws of physics are the same in a right-handed system of coordinates as in a left-handed system', NULL),
(22749, 'parity', 1, '/ˈpær.ə.ti/', '(mathematics) a relation between a pair of integers: if both integers are odd or both are even they have the same parity; if one is odd and the other is even they have different parity', '\"parity is often used to check the integrity of transmitted data\"'),
(22750, 'parity', 1, '/ˈpær.ə.ti/', '(obstetrics) the number of liveborn children a woman has delivered', '\"the parity of the mother must be considered\"; \"a bipara is a woman who has given birth to two children\"'),
(22751, 'evenness', 1, '/ˈiːvn̩nəs/', 'the quality of being balanced', NULL),
(22752, 'evenness', 1, '/ˈiːvn̩nəs/', 'a quality of uniformity and lack of variation', NULL),
(22753, 'evenness', 1, '/ˈiːvn̩nəs/', 'the parity of even numbers (divisible by two)', NULL),
(22754, 'isometry', 1, '/aɪˈsɒmɪtrɪ/', 'equality of measure (e.g., equality of height above sea level or equality of loudness etc.)', NULL),
(22755, 'isometry', 1, '/aɪˈsɒmɪtrɪ/', 'equality of elevation above sea level', NULL),
(22756, 'isometry', 1, '/aɪˈsɒmɪtrɪ/', 'a one-to-one mapping of one metric space into another metric space that preserves the distances between each pair of points', '\"the isometries of the cube\"'),
(22757, 'isometry', 1, '/aɪˈsɒm.ə.tri/', 'the growth rates in different parts of a growing organism are the same', NULL),
(22758, 'difference', 1, '/ˈdɪf.ər.əns/', 'the quality of being unlike or dissimilar', '\"There are many differences between jazz and rock\"'),
(22759, 'difference', 1, '/ˈdɪf.ər.əns/', 'a significant change', '\"The difference in her is amazing\"; \"His support made a real difference\"'),
(22760, 'differential', 1, '/ˌdɪfəˈrɛnʃəl/', 'a quality that differentiates between similar things', NULL),
(22761, 'differential', 3, '/ˌdɪfəˈrɛnʃəl/', 'relating to or showing a difference', '\"Differential treatment\"'),
(22762, 'differential', 3, '/ˌdɪfəˈrɛnʃəl/', 'involving or containing one or more derivatives', '\"differential equation\"'),
(22763, 'differentia', 1, '/ˌdɪfəˈrɛnʃɪə/', 'distinguishing characteristics (especially in different species of a genus)', NULL),
(22764, 'distinction', 1, '/dɪˈstɪŋk.ʃən/', 'a distinguishing difference', '\"He learned the distinction between gold and lead\"'),
(22765, 'distinction', 1, '/dɪˈstɪŋk.ʃən/', 'a distinguishing quality', '\"It has the distinction of being the cheapest restaurant in town\"'),
(22766, 'discrepancy', 1, '/dɪˈskrep.ən.si/', 'a difference between conflicting facts or claims or opinions', '\"A growing divergence of opinion\"'),
(22767, 'discrepancy', 1, '/dɪˈskrep.ən.si/', 'an event that departs from expectations', NULL),
(22768, 'dissimilarity', 1, '/dɪˌsɪm.ɪˈlær.ə.ti/', 'the quality of being dissimilar', NULL),
(22769, 'heterogeneity', 1, '/ˌhet.ər.ə.dʒɪˈniː.ə.ti/', 'the quality of being diverse and not comparable in kind', NULL),
(22770, 'biodiversity', 1, '/ˌbaɪ.əʊ.daɪˈvɜː.sə.ti/', 'the diversity of plant and animal life in a particular habitat (or in the world as a whole)', '\"a high level of biodiversity is desirable\"'),
(22771, 'inconsistency', 1, '/ˌɪn.kənˈsɪs.tən.si/', 'the quality of being inconsistent and lacking a harmonious uniformity among things or parts', NULL),
(22772, 'variety', 1, '/vəˈraɪ.ə.ti/', 'a difference that is usually pleasant', '\"He goes to France for variety\"; \"It is a refreshing change to meet a woman mechanic\"'),
