(22774, 'inequality', 1, '/ˌɪn.ɪˈkwɒl.ə.ti/', 'lack of equality', '\"The growing inequality between rich and poor\"'),
(22775, 'disparity', 1, '/dɪˈspær.ə.ti/', 'inequality or difference in some respect', NULL),
(22776, 'gulf', 1, '/ɡʌlf/', 'an unbridgeable disparity (as from a failure of understanding)', '\"he felt a gulf between himself and his former friends\"; \"there is a vast disconnect between public opinion and federal policy\"'),
(22777, 'gulf', 1, '/ɡʌlf/', 'a deep wide chasm', NULL),
(22778, 'gulf', 1, '/ɡʌlf/', 'an arm of a sea or ocean partly enclosed by land; larger than a bay', NULL),
(22779, 'unevenness', 1, '/ʌnˈiː.vən.nəs/', 'the quality of being unbalanced', NULL),
(22780, 'unevenness', 1, '/ʌnˈiː.vən.nəs/', 'the quality of being uneven and lacking uniformity', NULL),
(22781, 'certainty', 1, '/ˈsɜː.tən.ti/', 'something that is certain', '\"His victory is a certainty\"'),
(22782, 'certainty', 1, '/ˈsɜː.tən.ti/', 'the state of being certain', '\"His certainty reassured the others\"'),
(22783, 'cert', 1, '/sɜːt/', 'an absolute certainty', '\"It\'s a dead cert\"'),
(22784, 'inevitability', 1, '/ɪnˌev.ɪ.təˈbɪl.ə.ti/', 'the quality of being unavoidable', NULL),
(22785, 'finality', 1, '/faɪˈnæl.ə.ti/', 'the quality of being final or definitely settled', '\"The finality of death\"'),
(22786, 'surety', 1, '/ˈʃʊə.ri.ti/', 'something clearly established', NULL),
(22787, 'givenness', 1, '/ˈɡɪvənˌnɪs/', 'the quality of being granted as a supposition; of being acknowledged or assumed', NULL),
(22788, 'predictability', 1, '/prɪˌdɪk.təˈbɪl.ə.ti/', 'the quality of being predictable', NULL),
(22789, 'probability', 1, '/ˌprɒb.əˈbɪl.ə.ti/', 'the quality of being probable; a probable event or the most probable event', '\"For a while mutiny seemed a probability\"; \"Going by past experience there was a high probability that the visitors were lost\"'),
(22790, 'probability', 1, '/ˌprɒb.əˈbɪl.ə.ti/', 'a measure of how likely it is that some event will occur; a number expressing the ratio of favorable cases to the whole number of cases possible', '\"The probability that an unbiased coin will fall with the head up is 0.5\"'),
(22791, 'odds', 1, '/ɒdz/', 'the likelihood of a thing occurring rather than not occurring', NULL),
(22792, 'odds', 1, '/ɒdz/', 'the ratio by which one better\'s wager is greater than that of another', '\"He offered odds of two to one\"'),
(22793, 'likelihood', 1, '/ˈlaɪ.kli.hʊd/', 'the probability of a specified outcome', NULL),
(22794, 'uncertainty', 1, '/ʌnˈsɜː.tən.ti/', 'being unsettled or in doubt or dependent on chance', '\"The uncertainty of the outcome\"; \"The precariousness of his income\"'),
(22795, 'doubt', 1, '/daʊt/', 'uncertainty about the truth or factuality or existence of something', '\"The dubiousness of his claim\"; \"There is no question about the validity of the enterprise\"'),
(22796, 'doubt', 1, '/daʊt/', 'the state of being unsure of something', NULL),
(22797, 'doubt', 2, '/daʊt/', 'consider unlikely or have doubts about', '\"I doubt that she will accept his proposal of marriage\"'),
(22798, 'doubt', 2, '/daʊt/', 'lack confidence in or have doubts about', '\"I doubt these reports\"; \"I suspect her true motives\"; \"she distrusts her stepmother\"'),
(22799, 'indefiniteness', 1, '/ɪnˈdef.ɪ.nət.nəs/', 'the quality of being vague and poorly defined', NULL),
(22800, 'unpredictability', 1, '/ʌn.prɪˌdɪk.təˈbɪl.ə.ti/', 'lacking predictability', NULL),
(22801, 'improbability', 1, '/ɪmˌprɒb.əˈbɪl.ə.ti/', 'the quality of being improbable', '\"impossibility should never be confused with improbability\"; \"the improbability of such rare coincidences\"'),
(22802, 'unlikelihood', 1, '/(ˌ)ʌnˈlʌɪklihʊd/', 'the improbability of a specified outcome', NULL),
(22803, 'factuality', 1, '/ˌfaktʃʊˈalᵻti/', 'the quality of being actual or based on fact', '\"The realm of factuality must be distinguished from the realm of imagination\"'),
(22804, 'concreteness', 1, '/ˈkɒŋkriːtnᵻs/', 'the quality of being concrete (not abstract)', NULL),
(22805, 'tangibility', 1, '/ˈtændʒəbəl/', 'the quality of being perceivable by touch', NULL),
(22806, 'intangibility', 1, '/ɪnˈtændʒɪbəl/', 'the quality of being intangible and not perceptible by touch', NULL),
(22807, 'literalness', 1, '/ˈlɪt(ə)r(ə)lnəs/', 'adhereing to the concrete construal of something', NULL),
(22808, 'materiality', 1, '/məˌtɪəriˈæləti/', 'the quality of being physical; consisting of matter', NULL),
(22809, 'materiality', 1, '/məˌtɪəriˈæləti/', 'relevance requiring careful consideration', NULL),
(22810, 'substantiality', 1, '/səbˌstanʃiˈalᵻti/', 'the quality of being substantial or having substance', NULL),
(22811, 'immateriality', 1, '/ɪˌmæ.tɪə.riˈæl.ə.ti/', 'the quality of not being physical; not consisting of matter', NULL),
(22812, 'immateriality', 1, '/ɪˌmæ.tɪə.riˈæl.ə.ti/', 'complete irrelevance requiring no further consideration', NULL),
(22813, 'abstractness', 1, '/əbˈstrak(t)nəs/', 'the quality of being considered apart from a specific instance or object', NULL),
(22814, 'reality', 1, '/riˈæl.ə.ti/', 'the quality possessed by something that is real', NULL),
(22815, 'reality', 1, '/riˈæl.ə.ti/', 'the state of being actual or real', '\"The reality of his situation slowly dawned on him\"'),
(22816, 'reality', 1, '/riˈæl.ə.ti/', 'the state of the world as it really is rather than as you might want it to be', '\"Businessmen have to face harsh realities\"'),
(22817, 'unreality', 1, '/ʌn.riˈæl.ə.ti/', 'the quality possessed by something that is unreal', NULL),
(22818, 'unreality', 1, '/ʌn.riˈæl.ə.ti/', 'the state of being insubstantial or imaginary; not existing objectively or in fact', NULL),
(22819, 'particularity', 1, '/pəˌtɪk.jʊˈlær.ə.ti/', 'the quality of being particular and pertaining to a specific case or instance', '\"the particularity of human situations\"'),
(22820, 'specificity', 1, '/ˌspes.ɪˈfɪs.ə.ti/', 'the quality of being specific rather than general', '\"Add a desirable note of specificity to the discussion\"; \"The specificity of the symptoms of the disease\"'),
