INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(24734, 'shadow', 1, '/ˈʃæd.əʊ/', 'an inseparable companion', '\"The poor child was his mother\'s shadow\"'),
