(26445, 'guess', 1, '/ɡes/', 'an estimate based on little or no information', NULL),
(26446, 'guess', 1, '/ɡes/', 'a message expressing an opinion based on incomplete evidence', NULL),
(26447, 'guess', 2, '/ɡes/', 'guess correctly; solve by guessing', '\"He guessed the right number of beans in the jar and won the prize\"'),
(26448, 'guess', 2, '/ɡes/', 'put forward, of a guess, in spite of possible refutation', '\"I am guessing that the price of real estate will rise again\"; \"I cannot pretend to say that you are wrong\"'),
