(26455, 'underestimate', 2, '/ˌʌn.dəˈres.tɪ.meɪt/', 'make too low an estimate of', '\"he underestimated the work that went into the renovation\"; \"Don\'t underestimate the danger of such a raft trip on this river\"'),
(26456, 'knowing', 1, '/ˈnəʊ.ɪŋ/', 'a clear and certain mental apprehension', NULL),
(26457, 'knowing', 3, '/ˈnəʊ.ɪŋ/', 'highly educated; having extensive information or understanding', '\"knowing instructors\"; \"a knowledgeable critic\"; \"a knowledgeable audience\"'),
(26458, 'knowing', 3, '/ˈnəʊ.ɪŋ/', 'evidencing the possession of inside information', NULL),
(26459, 'know', 1, '/nəʊ/', 'the fact of being aware of information that is known to few people', '\"he is always in the know\"'),
(26460, 'know', 2, '/nəʊ/', 'be familiar or acquainted with a person or an object', '\"She doesn\'t know this composer\"; \"Do you know my sister?\"; \"We know this movie\"; \"I know him under a different name\"; \"This flower is known as a Peruvian Lily\"'),
(26461, 'know', 2, '/nəʊ/', 'be cognizant or aware of a fact or a specific piece of information; possess knowledge or information about', '\"I know that the President lied to the people\"; \"I want to know who is winning the game!\"; \"I know it\'s time\"'),
(26462, 'know', 2, '/nəʊ/', 'be aware of the truth of something; have a belief or faith in something; regard as true beyond any doubt', '\"I know that I left the key on the table\"; \"Galileo knew that the earth moves around the sun\"'),
(26463, 'know', 2, '/nəʊ/', 'know how to do or perform something', '\"She knows how to knit\"; \"Does your husband know how to cook?\"'),
(26464, 'know', 2, '/nəʊ/', 'have fixed in the mind', '\"I know Latin\"; \"This student knows her irregular verbs\"; \"Do you know the poem well enough to recite it?\"'),
(26465, 'know', 2, '/nəʊ/', 'have firsthand knowledge of states, situations, emotions, or sensations', '\"I know the feeling!\"; \"have you ever known hunger?\"; \"I have lived a kind of hell when I was a drug addict\"; \"The holocaust survivors have lived a nightmare\"; \"I lived through two divorces\"'),
(26466, 'know', 2, '/nəʊ/', 'perceive as familiar', '\"I know this voice!\"'),
