(26973, 'original', 3, '/əˈrɪdʒ.ən.əl/', 'being or productive of something fresh and unusual; or being as first made or thought of', '\"a truly original approach\"; \"with original music\"; \"an original mind\"'),
(26974, 'original', 3, '/əˈrɪdʒ.ən.əl/', '(of e.g. information) not secondhand or by way of something intermediary', '\"his work is based on only original, not secondary, sources\"'),
(26975, 'pacesetter', 1, '/ˈpeɪsˌsetər/', 'a leading instance in its field', '\"the new policy will be a pacesetter in community relations\"'),
(26976, 'pattern', 1, '/ˈpæt.ən/', 'a model considered worthy of imitation', '\"the American constitution has provided a pattern for many republics\"'),
(26977, 'pattern', 2, '/ˈpæt.ən/', 'form a pattern', '\"These sentences pattern like the ones we studied before\"'),
(26978, 'template', 1, '/ˈtem.pleɪt/', 'a model or standard for making comparisons', NULL),
(26979, 'prodigy', 1, '/ˈprɒd.ɪ.dʒi/', 'an impressive or wonderful example of a particular quality', '\"the Marines are expected to perform prodigies of valor\"'),
(26980, 'prodigy', 1, '/ˈprɒd.ɪ.dʒi/', 'an unusually gifted or intelligent (young) person; someone whose talents excite wonder and admiration', '\"she is a chess prodigy\"'),
(26981, 'mirage', 1, '/mɪˈrɑːʒ/', 'something illusory and unattainable', NULL),
(26982, 'mirage', 1, '/mɪˈrɑːʒ/', 'an optical illusion in which atmospheric refraction by a layer of hot air distorts or inverts reflections of distant objects', NULL),
(26983, 'blur', 1, '/blɜːr/', 'a hazy or indistinct representation', '\"it happened so fast it was just a blur\"; \"he tried to clear his head of the whisky fuzz\"'),
(26984, 'blur', 2, '/blɜːr/', 'become vague or indistinct', '\"The distinction between the two theories blurred\"'),
(26985, 'blur', 2, '/blɜːr/', 'make dim or indistinct', '\"The fog blurs my vision\"'),
(26986, 'blur', 2, '/blɜːr/', 'to make less distinct or clear', '\"The haze blurs the hills\"'),
(26987, 'belief', 1, '/bɪˈliːf/', 'any cognitive content held as true', NULL),
(26988, 'doctrine', 1, '/ˈdɒk.trɪn/', 'a belief (or system of beliefs) accepted as authoritative by some group or school', NULL),
(26989, 'philosophy', 1, '/fɪˈlɒs.ə.fi/', 'any personal belief about how to live or how to deal with a situation', '\"self-indulgence was his only philosophy\"; \"my father\'s philosophy of child-rearing was to let mother do it\"'),
(26990, 'philosophy', 1, '/fɪˈlɒs.ə.fi/', 'the rational investigation of questions about existence and knowledge and ethics', NULL),
(26991, 'expectation', 1, '/ˌek.spekˈteɪ.ʃən/', 'belief about (or mental picture of) the future', NULL),
(26992, 'expectation', 1, '/ˌek.spekˈteɪ.ʃən/', 'the feeling that something is about to happen', NULL),
(26993, 'originalism', 1, '/əˈrɪdʒn̩l̩ɪz(ə)m/', 'the belief that the United States Constitution should be interpreted in the way the authors originally intended it', NULL),
(26994, 'pacifism', 1, '/ˈpæs.ɪ.fɪ.zəm/', 'the belief that all international disputes can be settled by arbitration', NULL),
(26995, 'pacifism', 1, '/ˈpæs.ɪ.fɪ.zəm/', 'the doctrine that all violence is unjustifiable', NULL),
(26996, 'religion', 1, '/rɪˈlɪdʒ.ən/', 'a strong belief in a supernatural power or powers that control human destiny', '\"he lost his faith but not his morality\"'),
(26997, 'religion', 1, '/rɪˈlɪdʒ.ən/', 'an institution to express belief in a divine power', '\"he was raised in the Baptist religion\"; \"a member of his own faith contradicted him\"'),
(26998, 'cult', 1, '/kʌlt/', 'a system of religious beliefs and rituals', '\"devoted to the cultus of the Blessed Virgin\"'),
(26999, 'cult', 1, '/kʌlt/', 'a religion or sect that is generally considered to be unorthodox, extremist, or false', '\"it was a satanic cult\"'),
(27000, 'cult', 1, '/kʌlt/', 'followers of an unorthodox, extremist, or false religion or sect who often live outside of conventional society under the direction of a charismatic leader', NULL),
(27001, 'cult', 1, '/kʌlt/', 'followers of an exclusive system of religious beliefs and practices', NULL),
(27002, 'quietism', 1, '/ˈkwaɪə.tɪ.zəm/', 'a form of religious mysticism requiring withdrawal from all human effort and passive contemplation of God', NULL),
(27003, 'eyes', 1, '/aɪz/', 'opinion or judgment', '\"in the eyes of the law\"; \"I was wrong in her eyes\"'),
(27004, 'preconception', 1, '/ˌpriː.kənˈsep.ʃən/', 'an opinion formed beforehand without adequate evidence', '\"he did not even try to confirm his preconceptions\"'),
(27005, 'promise', 1, '/ˈprɒm.ɪs/', 'grounds for feeling hopeful about the future', '\"there is little or no promise that he will recover\"'),
(27006, 'promise', 1, '/ˈprɒm.ɪs/', 'a verbal commitment by one person to another agreeing to do (or not to do) something in the future', NULL),
(27007, 'promise', 2, '/ˈprɒm.ɪs/', 'make a promise or commitment', NULL),
(27008, 'promise', 2, '/ˈprɒm.ɪs/', 'promise to undertake or give', '\"I promise you my best effort\"'),
(27009, 'promise', 2, '/ˈprɒm.ɪs/', 'give grounds for expectations', '\"The new results were promising\"; \"The results promised fame and glory\"'),
(27010, 'rainbow', 1, '/ˈreɪn.bəʊ/', 'an illusory hope', '\"chasing rainbows\"'),
(27011, 'rainbow', 1, '/ˈreɪn.bəʊ/', 'an arc of colored light in the sky caused by refraction of the sun\'s rays by rain', NULL),
(27012, 'foretaste', 1, '/ˈfɔː.teɪst/', 'an early limited awareness of something yet to occur', NULL),
(27013, 'anticipation', 1, '/ænˌtɪs.ɪˈpeɪ.ʃən/', 'something expected (as on the basis of a norm)', '\"each of them had their own anticipations\"; \"an indicator of expectancy in development\"'),
(27014, 'anticipation', 1, '/ænˌtɪs.ɪˈpeɪ.ʃən/', 'an expectation', NULL),
(27015, 'anticipation', 1, '/ænˌtɪs.ɪˈpeɪ.ʃən/', 'anticipating with confidence of fulfillment', NULL),
(27016, 'spiritualism', 1, '/ˈspɪr.ɪ.tʃu.əl.ɪ.zəm/', 'the belief that the spirits of dead people can communicate with people who are still alive (especially via a medium)', NULL),
(27017, 'spiritualism', 1, '/ˈspɪr.ɪ.tʃu.əl.ɪ.zəm/', '(theology) any doctrine that asserts the separate existence of God', NULL),
(27018, 'superstition', 1, '/ˌsuː.pəˈstɪʃ.ən/', 'an irrational belief arising from ignorance or fear', NULL),
(27019, 'supremacism', 1, '/suːˈprem.ə.sɪ.zəm/', 'the belief that some particular group or race is superior to all others', '\"white supremacism\"'),
(27020, 'theory', 1, '/ˈθɪə.ri/', 'a belief that can guide behavior', '\"the architect has a theory that more is less\"; \"they killed him on the theory that dead men tell no tales\"'),
(27021, 'theory', 1, '/ˈθɪə.ri/', 'a well-substantiated explanation of some aspect of the natural world; an organized system of accepted knowledge that applies in a variety of circumstances to explain a specific set of phenomena', '\"theories can incorporate facts and laws and tested hypotheses\"; \"true in fact and theory\"'),
(27022, 'theosophy', 1, '/θiˈɒs.ə.fi/', 'a system of belief based on mystical insight into the nature of God and the soul', NULL),
(27023, 'anthroposophy', 1, '/ˌanθrəˈpɒsəfi/', 'a system of beliefs and practices based on the philosophy of Rudolf Steiner; it claims to integrate the practical and psychological in child-centered education', NULL),
(27024, 'thought', 1, '/θɔːt/', 'the organized beliefs of a period or group or individual', '\"19th century thought\"; \"Darwinian thought\"'),
(27025, 'totemism', 1, '/ˈtəʊ.tə.mɪ.zəm/', 'belief in the kinship of a group of people with a common totem', NULL),
(27026, 'tribalism', 1, '/ˈtraɪ.bəl.ɪ.zəm/', 'the beliefs of a tribal society', NULL),
(27027, 'tribalism', 1, '/ˈtraɪ.bəl.ɪ.zəm/', 'the state of living together in tribes', NULL),
(27028, 'values', 1, '/ˈvæljuːz/', 'beliefs of a person or social group in which they have an emotional investment (either for or against something)', '\"he has very conservatives values\"'),
(27029, 'mainstream', 1, '/ˈmeɪn.striːm/', 'the prevailing current of thought', '\"his thinking was in the American mainstream\"'),
(27030, 'ethic', 1, '/ˈeθ.ɪk/', 'the principles of right and wrong that are accepted by an individual or a social group', '\"the Puritan ethic\"; \"a person with old-fashioned values\"'),
(27031, 'ethic', 1, '/ˈeθ.ɪk/', 'a system of principles governing morality and acceptable conduct', NULL),
(27032, 'scruple', 1, '/ˈskruː.pəl/', 'an ethical or moral principle that inhibits action', NULL),
(27033, 'scruple', 1, '/ˈskruː.pəl/', 'uneasiness about the fitness of an action', NULL),
(27034, 'scruple', 1, '/ˈskruː.pəl/', 'a unit of apothecary weight equal to 20 grains', NULL),
(27035, 'scruple', 2, '/ˈskruː.pəl/', 'have doubts about', NULL),
(27036, 'scruple', 2, '/ˈskruː.pəl/', 'raise scruples', '\"He lied and did not even scruple about it\"'),
(27037, 'scruple', 2, '/ˈskruː.pəl/', 'hesitate on moral grounds', '\"The man scrupled to perjure himself\"'),
(27038, 'abolitionism', 1, '/ˌabəˈlɪʃn̩ɪz(ə)m/', 'the doctrine that calls for the abolition of slavery', NULL),
(27039, 'absolutism', 1, '/ˈæb.sə.luː.tɪ.zəm/', 'the doctrine of an absolute being', NULL),
(27040, 'absolutism', 1, '/ˈæb.sə.luː.tɪ.zəm/', 'the principle of complete and unrestricted power in government', NULL),
(27041, 'absolutism', 1, '/ˈæb.sə.luː.tɪ.zəm/', 'dominance through threat of punishment and violence', NULL),
(27042, 'animism', 1, '/ˈæn.ɪ.mɪ.zəm/', 'the doctrine that all natural objects and the universe itself have souls', '\"animism is common among primitive peoples\"'),
(27043, 'contextualism', 1, '/kənˈtɛkstjuːəlɪz(ə)m/', 'any doctrine emphasizing the importance of the context in solving problems or establishing the meaning of terms', NULL),
(27044, 'creationism', 1, '/kriˈeɪ.ʃən.ɪ.zəm/', 'the literal belief in the account of Creation given in the Book of Genesis', '\"creationism denies the theory of evolution of species\"'),
(27045, 'creed', 1, '/kriːd/', 'any system of principles or beliefs', NULL),
(27046, 'dogma', 1, '/ˈdɒɡ.mə/', 'a doctrine or code of beliefs accepted as authoritative', '\"he believed all the Marxist dogma\"'),
(27047, 'dogma', 1, '/ˈdɒɡ.mə/', 'a religious doctrine that is proclaimed as true without proof', NULL),
(27048, 'dualism', 1, '/ˈdʒuː.ə.lɪ.zəm/', 'the doctrine that reality consists of two basic opposing elements, often taken to be mind and matter (or mind and body), or good and evil', NULL),
(27049, 'epicureanism', 1, '/ˌɛpᵻkjᵿˈriːənɪz(ə)m/', 'a doctrine of hedonism that was defended by several ancient Greek philosophers', NULL),
(27050, 'expansionism', 1, '/ɪkˈspæn.ʃən.ɪ.zəm/', 'the doctrine of expanding the territory or the economic influence of a country', NULL),
(27051, 'experimentalism', 1, '/ᵻkˌspɛrᵻˈmɛntl̩ɪz(ə)m/', 'an empirical doctrine that advocates experimental principles', NULL),
(27052, 'experimentalism', 1, '/ᵻkˌspɛrᵻˈmɛntl̩ɪz(ə)m/', 'an orientation that favors experimentation and innovation', '\"the children of psychologists are often raised in an atmosphere of experimentalism\"');
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(27053, 'functionalism', 1, '/ˈfʌŋk.ʃən.əl.ɪ.zəm/', 'any doctrine that stresses utility or purpose', NULL),
(27054, 'functionalism', 1, '/ˈfʌŋk.ʃən.əl.ɪ.zəm/', 'a psychology based on the assumption that all mental process are useful to an organism in adapting to the environment', NULL),
(27055, 'gospel', 1, '/ˈɡɒs.pəl/', 'a doctrine that is believed to be of great importance', '\"Newton\'s writings were gospel for those who followed\"'),
(27056, 'gospel', 1, '/ˈɡɒs.pəl/', 'an unquestionable truth', '\"his word was gospel\"'),
(27057, 'gospel', 1, '/ˈɡɒs.pəl/', 'folk music consisting of a genre of a cappella music originating with Black slaves in the United States and featuring call and response; influential on the development of other genres of popular music (especially soul)', NULL),
(27058, 'mimesis', 1, '/mɪˈmiː.sɪs/', 'the imitative representation of nature and human behavior in art and literature', NULL),
(27059, 'mimesis', 1, '/mɪˈmiː.sɪs/', 'the representation of another person\'s words in a speech', NULL),
(27060, 'mimesis', 1, '/mɪˈmiː.sɪs/', 'any disease that shows symptoms characteristic of another disease', NULL),
(27061, 'individualism', 1, '/ˌɪn.dɪˈvɪdʒ.u.ə.lɪ.zəm/', 'the doctrine that government should not interfere in commercial affairs', NULL),
