(27063, 'internationalism', 1, '/ˌɪn.təˈnæʃ.ən.əl.ɪ.zəm/', 'the doctrine that nations should cooperate because their common interests are more important than their differences', NULL),
(27064, 'unilateralism', 1, '/ˌjuː.nɪˈlæt.ər.əl.ɪ.zəm/', 'the doctrine that nations should conduct their foreign affairs individualistically without the advice or involvement of other nations', NULL),
(27065, 'irredentism', 1, '/ˌɪr.ɪˈden.tɪ.zəm/', 'the doctrine that irredenta should be controlled by the country to which they are ethnically or historically related', NULL),
(27066, 'literalism', 1, '/ˈlɪt(ə)rəlɪz(ə)m/', 'the doctrine of realistic (literal) portrayal in art or literature', NULL),
(27067, 'literalism', 1, '/ˈlɪt(ə)rəlɪz(ə)m/', 'a disposition to interpret statements in their literal sense', NULL),
(27068, 'monism', 1, '/ˈmɒnɪz(ə)m/', 'the doctrine that reality consists of a single basic substance or element', NULL),
(27069, 'multiculturalism', 1, '/ˌmʌl.tiˈkʌl.tʃər.əl.ɪ.zəm/', 'the doctrine that several different cultures (rather than one national culture) can coexist peacefully and equitably in a single country', NULL),
(27070, 'nationalism', 1, '/ˈnæʃ.ən.əl.ɪ.zəm/', 'the doctrine that your national culture and interests are superior to any other', NULL),
(27071, 'nationalism', 1, '/ˈnæʃ.ən.əl.ɪ.zəm/', 'the doctrine that nations should act independently (rather than collectively) to attain their goals', NULL),
(27072, 'nationalism', 1, '/ˈnæʃ.ən.əl.ɪ.zəm/', 'the aspiration for national independence felt by people under foreign domination', NULL),
(27073, 'nihilism', 1, '/ˈniː.ɪl.ɪ.zəm/', 'a revolutionary doctrine that advocates destruction of the social system for its own sake', NULL),
(27074, 'nihilism', 1, '/ˈniː.ɪl.ɪ.zəm/', 'complete denial of all established authority and institutions', NULL),
(27075, 'populism', 1, '/ˈpɒp.jə.lɪ.zəm/', 'the political doctrine that supports the rights and powers of the common people in their struggle with the privileged elite', NULL),
(27076, 'predestination', 1, '/ˌpriː.des.tɪˈneɪ.ʃən/', '(theology) being determined in advance; especially the doctrine (usually associated with Calvin) that God has foreordained every event throughout eternity (including the final salvation of mankind)', NULL),
(27077, 'predestination', 1, '/ˌpriː.des.tɪˈneɪ.ʃən/', 'previous determination as if by destiny or fate', NULL),
(27078, 'presentism', 1, '/ˈprɛzntɪz(ə)m/', 'the doctrine that the Scripture prophecies of the Apocalypse (as in the Book of Revelations) are presently in the course of being fulfilled', NULL),
(27079, 'rationalism', 1, '/ˈræʃ.ən.əl.ɪ.zəm/', 'the doctrine that reason is the right basis for regulating conduct', NULL),
(27080, 'rationalism', 1, '/ˈræʃ.ən.əl.ɪ.zəm/', '(philosophy) the doctrine that knowledge is acquired by reason without resort to experience', NULL),
(27081, 'rationalism', 1, '/ˈræʃ.ən.əl.ɪ.zəm/', 'the theological doctrine that human reason rather than divine revelation establishes religious truth', NULL),
(27082, 'reformism', 1, '/rᵻˈfɔːmɪz(ə)m/', 'a doctrine of reform', NULL),
(27083, 'humanism', 1, '/ˈhjuː.mə.nɪ.zəm/', 'the doctrine emphasizing a person\'s capacity for self-realization through reason; rejects religion and the supernatural', NULL),
