(27087, 'feminism', 1, '/ˈfem.ɪ.nɪ.zəm/', 'a doctrine that advocates equal rights for women', NULL),
(27088, 'magic', 1, '/ˈmædʒ.ɪk/', 'any art that invokes supernatural powers', NULL),
(27089, 'mojo', 1, '/ˈməʊ.dʒəʊ/', 'a magic power or magic spell', NULL),
(27090, 'occultism', 1, '/ˈɒk(ʌ)ltɪz(ə)m/', 'a belief in supernatural powers and the possibility of bringing them under human control', NULL),
(27091, 'occultism', 1, '/ˈɒk(ʌ)ltɪz(ə)m/', 'the study of the supernatural', NULL),
(27092, 'secessionism', 1, '/sɪˈsɛʃənɪz(ə)m/', 'a doctrine that maintains the right of secession', NULL),
(27093, 'secularism', 1, '/ˈsek.jə.lər.ɪ.zəm/', 'a doctrine that rejects religion and religious considerations', NULL),
(27094, 'aesthetic', 1, '/esˈθet.ɪk/', '(philosophy) a philosophical theory as to what is beautiful', '\"he despised the esthetic of minimalism\"'),
(27095, 'aesthetic', 3, '/esˈθet.ɪk/', 'concerning or characterized by an appreciation of beauty or good taste', '\"the aesthetic faculties\"; \"an aesthetic person\"; \"aesthetic feeling\"; \"the illustrations made the book an aesthetic success\"'),
(27096, 'aesthetic', 3, '/esˈθet.ɪk/', 'aesthetically pleasing', '\"an artistic flower arrangement\"'),
(27097, 'aesthetic', 3, '/esˈθet.ɪk/', 'relating to or dealing with the subject of aesthetics', '\"aesthetic values\"'),
(27098, 'conceptualism', 1, '/kənˈsɛptʃʊəlɪz(ə)m/', 'the doctrine that the application of a general term to various objects indicates the existence of a mental entity that mediates the application', NULL),
(27099, 'deconstruction', 1, '/ˌdiː.kənˈstrʌkʃ.ən/', 'a philosophical theory of criticism (usually of literature or film) that seeks to expose deep-seated contradictions in a work by delving below its surface meaning', NULL),
(27100, 'existentialism', 1, '/ˌeɡ.zɪˈsten.ʃəl.ɪ.zəm/', '(philosophy) a 20th-century philosophical movement chiefly in Europe; assumes that people are entirely free and thus responsible for what they make of themselves', NULL),
(27101, 'determinism', 1, '/dɪˈtɜː.mɪ.nɪ.zəm/', '(philosophy) a philosophical theory holding that all events are inevitable consequences of antecedent sufficient causes; often understood as denying the possibility of free will', NULL),
(27102, 'fatalism', 1, '/ˈfeɪ.təl.ɪ.zəm/', 'a philosophical doctrine holding that all events are predetermined in advance for all time and human beings are powerless to change them', NULL),
(27103, 'fatalism', 1, '/ˈfeɪ.təl.ɪ.zəm/', 'a submissive mental attitude resulting from acceptance of the doctrine that everything that happens is predetermined and inevitable', NULL),
(27104, 'intuitionism', 1, '/ɪntjuːˈɪʃənɪz(ə)m/', '(philosophy) the doctrine that knowledge is acquired primarily by intuition', NULL),
(27105, 'logicism', 1, '/ˈlɒdʒɪsɪz(ə)m/', '(philosophy) the philosophical theory that all of mathematics can be derived from formal logic', NULL),
(27106, 'materialism', 1, '/məˈtɪə.ri.ə.lɪ.zəm/', '(philosophy) the philosophical theory that matter is the only reality', NULL),
(27107, 'materialism', 1, '/məˈtɪə.ri.ə.lɪ.zəm/', 'a desire for wealth and material possessions with little interest in ethical or spiritual matters', NULL),
(27108, 'mentalism', 1, '/ˈmɛntl̩ɪz(ə)m/', '(philosophy) a doctrine that mind is the true reality and that objects exist only as aspects of the mind\'s awareness', NULL),
(27109, 'nativism', 1, '/ˈneɪ.tɪ.vɪ.zəm/', '(philosophy) the philosophical theory that some ideas are innate', NULL),
(27110, 'nativism', 1, '/ˈneɪ.tɪ.vɪ.zəm/', 'the policy of perpetuating native cultures (in opposition to acculturation)', NULL),
(27111, 'naturalism', 1, '/ˈnætʃ.ər.əl.ɪ.zəm/', '(philosophy) the doctrine that the world can be understood in scientific terms without recourse to spiritual or supernatural explanations', NULL),
(27112, 'naturalism', 1, '/ˈnætʃ.ər.əl.ɪ.zəm/', 'an artistic movement in 19th century France; artists and writers strove for detailed realistic and factual description', NULL),
(27113, 'nominalism', 1, '/ˈnɒmᵻnl̩ɪz(ə)m/', '(philosophy) the doctrine that the various objects labeled by the same term have nothing in common but their name', NULL),
(27114, 'pragmatism', 1, '/ˈpræɡ.mə.tɪ.zəm/', '(philosophy) the doctrine that practical consequences are the criteria of knowledge and meaning and value', NULL),
(27115, 'instrumentalism', 1, '/ˌɪn(t)strᵿˈmɛntl̩ɪz(ə)m/', 'a system of pragmatic philosophy that considers idea to be instruments that should guide our actions and their value is measured by their success', NULL),
(27116, 'probabilism', 1, '/ˈprɒbəbᵻlɪz(ə)m/', '(philosophy) the doctrine that (since certainty is unattainable) probability is a sufficient basis for belief and action', NULL),
(27117, 'probabilism', 1, '/ˈprɒbəbᵻlɪz(ə)m/', 'a Roman Catholic system of casuistry that when expert opinions differ an actor can follow any solidly probable opinion that he wishes even though some different opinion might be more probable', NULL),
(27118, 'relativism', 1, '/ˈrel.ə.tɪ.vɪ.zəm/', '(philosophy) the philosophical doctrine that all criteria of judgment are relative to the individuals and situations involved', NULL),
(27119, 'semiotics', 1, '/ˌsem.iˈɒt.ɪks/', '(philosophy) a philosophical theory of the functions of signs and symbols', NULL),
(27120, 'sensualism', 1, '/ˈsɛn(t)sjʊəlɪz(ə)m/', '(philosophy) the ethical doctrine that feeling is the only criterion for what is good', NULL),
(27121, 'solipsism', 1, '/ˈsɒl.ɪp.sɪ.zəm/', '(philosophy) the philosophical theory that the self is all that you know to exist', NULL),
(27122, 'teleology', 1, '/ˌtiː.liˈɒl.ə.dʒi/', '(philosophy) a doctrine explaining phenomena by their ends or purposes', NULL),
(27123, 'vitalism', 1, '/ˈvʌɪtəlɪz(ə)m/', '(philosophy) a doctrine that life is a vital principle distinct from physics and chemistry', NULL),
