(27755, 'page', 1, '/peɪdʒ/', 'one side of one leaf (of a book or magazine or newspaper or letter etc.) or the written or pictorial matter it contains', NULL),
(27756, 'page', 1, '/peɪdʒ/', 'in medieval times a youth acting as a knight\'s attendant as the first stage in training for knighthood', NULL),
(27757, 'page', 1, '/peɪdʒ/', 'a youthful attendant at official functions or ceremonies such as legislative functions and weddings', NULL),
(27758, 'page', 1, '/peɪdʒ/', 'a boy who is employed to run errands', NULL),
(27759, 'page', 2, '/peɪdʒ/', 'contact, as with a pager or by calling somebody\'s name over a P.A. system', NULL),
(27760, 'page', 2, '/peɪdʒ/', 'work as a page', '\"He is paging in Congress this summer\"'),
(27761, 'recto', 1, '/ˈrek.təʊ/', 'right-hand page', NULL),
(27762, 'verso', 1, '/ˈvɜː.səʊ/', 'left-hand page', NULL),
