(27764, 'foldout', 1, '/ˈfəʊldˌaʊt/', 'an oversize page that is folded in to a book or magazine', NULL),
(27765, 'pagination', 1, '/ˌpædʒ.ɪˈneɪ.ʃən/', 'the system of numbering pages', NULL),
(27766, 'stationery', 1, '/ˈsteɪ.ʃən.ər.i/', 'paper cut to an appropriate size for writing letters; usually with matching envelopes', NULL),
(27767, 'letterhead', 1, '/ˈlet.ə.hed/', 'a sheet of stationery with name and address of the organization printed at the top', NULL),
(27768, 'notepaper', 1, '/ˈnəʊtˌpeɪ.pər/', 'writing paper intended for writing short notes or letters', NULL),
(27769, 'foolscap', 1, '/ˈfuːl.skæp/', 'a size of paper used especially in Britain', NULL),
(27770, 'worksheet', 1, '/ˈwɜːk.ʃiːt/', 'a sheet of paper with multiple columns; used by an accountant to assemble figures for financial statements', NULL),
(27771, 'worksheet', 1, '/ˈwɜːk.ʃiːt/', 'a piece of paper recording work planned or done on a project', NULL),
(27772, 'liaison', 1, '/liˈeɪ.zɒn/', 'a channel for communication between groups', '\"he provided a liaison with the guerrillas\"');
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(27773, 'channels', 1, '/ˈtʃæn.əlz/', 'official routes of communication', '\"you have to go through channels\"'),
(27774, 'multimedia', 1, '/ˌmʌl.tiˈmiː.di.ə/', 'transmission that combine media of communication (text and graphics and sound etc.)', NULL),
(27775, 'hypermedia', 1, '/ˈhaɪpəˌmiːdiə/', 'a multimedia system in which related items of information are connected and can be presented together', NULL),
(27776, 'hypertext', 1, '/ˈhaɪ.pə.tekst/', 'machine-readable text that is not sequential but is organized so that related items of information are connected; \"Let me introduce the word hypertext to mean a body of written or pictorial material interconnected in such a complex way that it could not conveniently be presented or represented on paper\"--Ted Nelson', NULL),
(27777, 'airmail', 1, '/ˈeə.meɪl/', 'a system of conveying mail by aircraft', NULL),
(27778, 'airmail', 1, '/ˈeə.meɪl/', 'letters and packages that are transported by aircraft', NULL),
(27779, 'airmail', 2, '/ˈeə.meɪl/', 'send or transport by airmail', '\"Letters to Europe from the U.S. are best airmailed\"'),
(27780, 'photojournalism', 1, '/ˌfəʊ.təʊˈdʒɜː.nəl.ɪ.zəm/', 'journalism that presents a story primarily through the use of pictures', NULL),
