(27782, 'rotogravure', 1, '/ˌrəʊtə(ʊ)ɡrəˈvjʊə/', 'printing by transferring an image from a photogravure plate to a cylinder in a rotary press', NULL),
(27783, 'daily', 1, '/ˈdeɪ.li/', 'a newspaper that is published every day', NULL),
(27784, 'daily', 3, '/ˈdeɪ.li/', 'of or belonging to or occurring every day', '\"daily routine\"; \"a daily paper\"'),
(27785, 'daily', 4, '/ˈdeɪ.li/', 'every day; without missing a day', '\"he stops by daily\"'),
(27786, 'gazette', 1, '/ɡəˈzet/', 'a newspaper or official journal', NULL),
(27787, 'gazette', 2, '/ɡəˈzet/', 'publish in a gazette', NULL),
(27788, 'tabloid', 1, '/ˈtæb.lɔɪd/', 'newspaper with half-size pages', NULL),
(27789, 'morceau', 1, '/mɔːˈsəʊ/', 'a short literary or musical composition', NULL),
(27790, 'offprint', 1, '/ˈɒfprɪnt/', 'a separately printed article that originally appeared in a larger publication', NULL),
(27791, 'reissue', 1, '/ˌriːˈɪʃ.uː/', 'a publication (such as a book) that is reprinted without changes or editing and offered again for sale', NULL),
(27792, 'reissue', 2, '/ˌriːˈɪʃ.uː/', 'issue (a new version of)', '\"if you forget your password, it can be changed and reissued\"'),
(27793, 'personal', 1, '/ˈpɜː.sən.əl/', 'a short newspaper article about a particular person or group', NULL),
(27794, 'personal', 3, '/ˈpɜː.sən.əl/', 'particular to a given individual', NULL),
(27795, 'personal', 3, '/ˈpɜː.sən.əl/', 'concerning or affecting a particular person or his or her private life and personality', '\"a personal favor\"; \"for your personal use\"; \"personal papers\"; \"I have something personal to tell you\"; \"a personal God\"; \"he has his personal bank account and she has hers\"'),
(27796, 'personal', 3, '/ˈpɜː.sən.əl/', 'intimately concerning a person\'s body or physical being', '\"personal hygiene\"'),
(27797, 'personal', 3, '/ˈpɜː.sən.əl/', 'indicating grammatical person', '\"personal verb endings\"'),
(27798, 'personal', 3, '/ˈpɜː.sən.əl/', 'of or arising from personality', '\"personal magnetism\"'),
(27799, 'sidebar', 1, '/ˈsaɪd.bɑːr/', 'a short news story presenting sidelights on a major story', NULL),
(27800, 'sidebar', 1, '/ˈsaɪd.bɑːr/', '(law) a courtroom conference between the lawyers and the judge that is held out of the jury\'s hearing', NULL),
(27801, 'samizdat', 1, '/ˈsamɪzdat/', 'a system of clandestine printing and distribution of dissident or banned literature', NULL),
(27802, 'telegraphy', 1, '/təˈleɡ.rə.fi/', 'communicating at a distance by electric transmission over wire', NULL),
(27803, 'wireless', 1, '/ˈwaɪə.ləs/', 'transmission by radio waves', NULL),
(27804, 'wireless', 3, '/ˈwaɪə.ləs/', 'having no wires', '\"a wireless security system\"'),
(27805, 'broadcasting', 1, '/ˈbrɔːdˌkɑː.stɪŋ/', 'taking part in a radio or tv program', NULL),
(27806, 'video', 1, '/ˈvɪd.i.əʊ/', 'the visible part of a television transmission', '\"they could still receive the sound but the picture was gone\"'),
(27807, 'video', 1, '/ˈvɪd.i.əʊ/', '(computer science) the appearance of text and graphics on a video display', NULL),
(27808, 'emoticon', 1, '/ɪˈməʊ.tɪ.kɒn/', 'a representation of a facial expression (as a smile or frown) created by typing a sequence of characters in sending email', '\":-( and :-) are emoticons\"'),
(27809, 'smiley', 1, '/ˈsmaɪ.li/', 'an emoticon of a smiling face', NULL),
(27810, 'spam', 1, '/spæm/', 'unwanted e-mail (usually of a commercial nature sent out in bulk)', NULL),
(27811, 'spam', 2, '/spæm/', 'send unwanted or junk e-mail', NULL),
(27812, 'messaging', 1, '/ˈmes.ɪ.dʒɪŋ/', 'the sending and processing of e-mail by computer', NULL),
(27813, 'prompt', 1, '/prɒmpt/', '(computer science) a symbol that appears on the computer screen to indicate that the computer is ready to receive a command', NULL),
(27814, 'prompt', 1, '/prɒmpt/', 'a cue given to a performer (usually the beginning of the next line to be spoken)', '\"the audience could hear his prompting\"'),
(27815, 'prompt', 2, '/prɒmpt/', 'serve as the inciting cause of', '\"She prompted me to call my relatives\"'),
(27816, 'prompt', 2, '/prɒmpt/', 'assist (somebody acting or reciting) by suggesting the next words of something forgotten or imperfectly learned', NULL),
(27817, 'prompt', 3, '/prɒmpt/', 'according to schedule or without delay; on time', '\"the train is prompt\"'),
(27818, 'prompt', 3, '/prɒmpt/', 'ready and willing or quick to act; \"she is always prompt to help her friends\";', NULL),
(27819, 'demodulation', 1, '/ˌdiːmɒdjᵿˈleɪʃn/', '(electronics) the reception of a signal by extracting it from the carrier wave', NULL),
(27820, 'contagion', 1, '/kənˈteɪ.dʒən/', 'the communication of an attitude or emotional state among a number of people', '\"a contagion of mirth\"; \"the infection of his enthusiasm for poetry\"'),
(27821, 'usage', 1, '/ˈjuː.sɪdʒ/', 'the customary manner in which a language (or a form of a language) is spoken or written', '\"English usage\"; \"a usage borrowed from French\"'),
(27822, 'words', 1, '/wɜːdz/', 'language that is spoken or written', '\"he has a gift for words\"; \"she put her thoughts into words\"'),
(27823, 'words', 1, '/wɜːdz/', 'the words that are spoken', '\"I listened to his words very closely\"'),
(27824, 'discourse', 1, '/ˈdɪs.kɔːs/', 'extended verbal expression in speech or writing', NULL),
(27825, 'discourse', 2, '/ˈdɪs.kɔːs/', 'to consider or examine in speech or writing', '\"The author talks about the different aspects of this question\"; \"The class discussed Dante\'s `Inferno\'\"'),
(27826, 'context', 1, '/ˈkɒn.tekst/', 'discourse that surrounds a language unit and helps to determine its interpretation', NULL),
(27827, 'context', 1, '/ˈkɒn.tekst/', 'the set of facts or circumstances that surround a situation or event', '\"the historical context\"'),
(27828, 'sentence', 1, '/ˈsen.təns/', 'a string of words satisfying the grammatical rules of a language', '\"he always spoke in grammatical sentences\"'),
(27829, 'sentence', 2, '/ˈsen.təns/', 'pronounce a sentence on (somebody) in a court of law', '\"He was condemned to ten years in prison\"'),
(27830, 'word', 1, '/wɜːd/', 'a unit of language that native speakers can identify', '\"words are the blocks from which sentences are made\"; \"he hardly said ten words all morning\"'),
(27831, 'word', 1, '/wɜːd/', 'a brief statement', '\"he didn\'t say a word about it\"'),
(27832, 'word', 1, '/wɜːd/', 'a verbal command for action', '\"when I give the word, charge!\"'),
(27833, 'word', 1, '/wɜːd/', 'a word is a string of bits stored in computer memory', '\"large computers use words up to 64 bits long\"'),
(27834, 'anagram', 1, '/ˈæn.ə.ɡræm/', 'a word or phrase spelled by rearranging the letters of another word or phrase', NULL),
(27835, 'anagram', 2, '/ˈæn.ə.ɡræm/', 'read letters out of order to discover a hidden meaning', NULL),
(27836, 'antonym', 1, '/ˈæn.tə.nɪm/', 'a word that expresses a meaning opposed to the meaning of another word, in which case the two words are antonyms of each other', '\"to him the antonym of `gay\' was `depressed\'\"'),
(27837, 'charade', 1, '/ʃəˈrɑːd/', 'a word acted out in an episode of the game of charades', NULL),
(27838, 'cognate', 1, '/ˈkɒɡ.neɪt/', 'a word is cognate with another if both derive from the same word in an ancestral language', NULL),
(27839, 'cognate', 3, '/ˈkɒɡ.neɪt/', 'having the same ancestral language', '\"cognate languages\"'),
(27840, 'deictic', 1, '/ˈdaɪk.tɪk/', 'a word specifying identity or spatial or temporal location from the perspective of a speaker or hearer in the context in which the communication occurs; \"words that introduce particulars of the speaker\'s and hearer\'s shared cognitive field into the message\"- R.Rommetveit', NULL),
(27841, 'deictic', 3, '/ˈdaɪk.tɪk/', 'relating to or characteristic of a word whose reference depends on the circumstances of its use', '\"deictic pronouns\"'),
(27842, 'derivative', 1, '/dɪˈrɪv.ə.tɪv/', '(linguistics) a word that is derived from another word', '\"`electricity\' is a derivative of `electric\'\"'),
