(27844, 'derivative', 3, '/dɪˈrɪv.ə.tɪv/', 'resulting from or employing derivation', '\"a derivative process\"; \"a highly derivative prose style\"'),
(27845, 'diminutive', 1, '/dɪˈmɪn.jə.tɪv/', 'a word that is formed with a suffix (such as -let or -kin) to indicate smallness', NULL),
(27846, 'headword', 1, '/ˈhed.wɜːd/', 'a word placed at the beginning of a line or paragraph (as in a dictionary entry)', NULL),
(27847, 'headword', 1, '/ˈhed.wɜːd/', 'a content word that can be qualified by a modifier', NULL),
