(27849, 'loanword', 1, '/ˈləʊn.wɜːd/', 'a word borrowed from another language; e.g. `blitz\' is a German word borrowed into modern English', NULL),
(27850, 'metonym', 1, '/ˈmet.ə.nɪm/', 'a word that denotes one thing but refers to a related thing', '\"Washington is a metonym for the United States government\"; \"plastic is a metonym for credit card\"'),
