(27852, 'palindrome', 1, '/ˈpæl.ɪn.drəʊm/', 'a word or phrase that reads the same backward as forward', NULL),
(27853, 'primitive', 1, '/ˈprɪm.ɪ.tɪv/', 'a word serving as the basis for inflected or derived forms', '\"`pick\' is the primitive from which `picket\' is derived\"'),
(27854, 'primitive', 1, '/ˈprɪm.ɪ.tɪv/', 'a mathematical expression from which another expression is derived', NULL),
(27855, 'primitive', 1, '/ˈprɪm.ɪ.tɪv/', 'a person who belongs to an early stage of civilization', NULL),
(27856, 'primitive', 3, '/ˈprɪm.ɪ.tɪv/', 'used of preliterate or tribal or nonindustrial societies', '\"primitive societies\"'),
(27857, 'primitive', 3, '/ˈprɪm.ɪ.tɪv/', 'of or created by one without formal training; simple or naive in style', '\"primitive art such as that by Grandma Moses is often colorful and striking\"'),
(27858, 'plural', 1, '/ˈplʊə.rəl/', 'the form of a word that is used to denote more than one', NULL),
