(27860, 'plural', 3, '/ˈplʊə.rəl/', 'composed of more than one member, set, or kind', NULL),
(27861, 'singular', 1, '/ˈsɪŋ.ɡjə.lər/', 'the form of a word that is used to denote a singleton', NULL),
(27862, 'singular', 3, '/ˈsɪŋ.ɡjə.lər/', 'being a single and separate person or thing; \"every fact in the world might be singular...unlike any other fact and sole of its kind\"-William James', '\"can the singular person be understood apart from his culture?\"'),
(27863, 'singular', 3, '/ˈsɪŋ.ɡjə.lər/', 'grammatical number category referring to a single item or unit', NULL),
(27864, 'singular', 3, '/ˈsɪŋ.ɡjə.lər/', 'composed of one member, set, or kind', NULL),
