(27866, 'etymon', 1, '/ˈet.ɪ.mɒn/', 'a simple form inferred as the common basis from which related words in several languages can be derived by linguistic processes', NULL),
(27867, 'calque', 1, '/kælk/', 'an expression introduced into one language by translating it from another language', '\"`superman\' is a calque for the German `Ubermensch\'\"'),
(27868, 'partitive', 1, '/ˈpɑː.tə.tɪv/', 'word (such a `some\' or `less\') that is used to indicate a part as distinct from a whole', NULL),
(27869, 'partitive', 3, '/ˈpɑː.tə.tɪv/', 'serving to separate or divide into parts', '\"partitive tendencies in education\"; \"the uniting influence was stronger than the separative\"'),
(27870, 'partitive', 3, '/ˈpɑː.tə.tɪv/', 'indicating or characterized by or serving to create partition or division into parts', '\"partitive tendencies in education\"'),
(27871, 'partitive', 3, '/ˈpɑː.tə.tɪv/', '(Romance languages) relating to or denoting a part of a whole or a quantity that is less than the whole', '\"a partitive construction\"'),
(27872, 'quantifier', 1, '/ˈkwɒn.tɪ.faɪ.ər/', '(grammar) a word that expresses a quantity (as `fifteen\' or `many\')', NULL),
