(27874, 'substantive', 1, '/səbˈstæn.tɪv/', 'any word or group of words functioning as a noun', NULL),
(27875, 'substantive', 3, '/səbˈstæn.tɪv/', 'defining rights and duties as opposed to giving the rules by which rights and duties are established', '\"substantive law\"'),
(27876, 'synonym', 1, '/ˈsɪn.ə.nɪm/', 'two words that can be interchanged in a context are said to be synonymous relative to that context', NULL),
(27877, 'terminology', 1, '/ˌtɜː.mɪˈnɒl.ə.dʒi/', 'a system of words used to name things in a particular discipline', '\"legal terminology\"; \"biological nomenclature\"; \"the language of sociology\"'),
(27878, 'syllable', 1, '/ˈsɪl.ə.bəl/', 'a unit of spoken language larger than a phoneme', '\"the word `pocket\' has two syllables\"'),
(27879, 'ultima', 1, '/ˈʌltᵻmə/', 'the last syllable in a word', NULL),
(27880, 'penult', 1, '/pᵻˈnʌlt/', 'the next to last syllable in a word', NULL),
(27881, 'jawbreaker', 1, '/ˈdʒɔːˌbreɪ.kər/', 'a word that is hard to pronounce', NULL),
(27882, 'jawbreaker', 1, '/ˈdʒɔːˌbreɪ.kər/', 'a large round hard candy', NULL),
(27883, 'sesquipedalian', 1, '/ˌses.kwɪ.pɪˈdeɪ.li.ən/', 'a very long word (a foot and a half long)', NULL),
(27884, 'sesquipedalian', 3, '/ˌses.kwɪ.pɪˈdeɪ.li.ən/', 'given to the overuse of long words', '\"sesquipedalian orators\"; \"this sesquipedalian way of saying one has no money\"'),
(27885, 'lexeme', 1, '/ˈlek.siːm/', 'a minimal unit (as a word or stem) in the lexicon of a language; `go\' and `went\' and `gone\' and `going\' are all members of the English lexeme `go\'', NULL),
(27886, 'morpheme', 1, '/ˈmɔː.fiːm/', 'minimal meaningful language unit; it cannot be divided into smaller meaningful units', NULL),
(27887, 'formative', 1, '/ˈfɔː.mə.tɪv/', 'minimal language unit that has a syntactic (or morphological) function', NULL),
(27888, 'formative', 3, '/ˈfɔː.mə.tɪv/', 'forming or capable of forming or molding or fashioning', '\"a formative influence\"; \"a formative experience\"'),
(27889, 'formative', 3, '/ˈfɔː.mə.tɪv/', 'capable of forming new cells and tissues', '\"a formative zone in developing bone\"'),
(27890, 'allomorph', 1, '/ˈalə(ʊ)mɔːf/', 'a variant phonological representation of a morpheme', '\"the final sounds of `bets\' and `beds\' and `horses\' and `oxen\' are allomorphs of the English plural morpheme\"'),
(27891, 'allomorph', 1, '/ˈalə(ʊ)mɔːf/', 'any of several different crystalline forms of the same chemical compound', '\"calcium carbonate occurs in the allomorphs calcite and aragonite\"'),
(27892, 'affix', 1, '/ˈæf.ɪks/', 'a linguistic element added to a word to produce an inflected or derived form', NULL),
(27893, 'affix', 2, '/əˈfɪks/', 'attach or become attached to a stem word', '\"grammatical morphemes affix to the stem\"'),
(27894, 'affix', 2, '/əˈfɪks/', 'attach to', '\"affix the seal here\"'),
(27895, 'prefix', 1, '/ˈpriː.fɪks/', 'an affix that is added in front of the word', NULL),
(27896, 'prefix', 2, '/ˈpriː.fɪks/', 'attach a prefix to', '\"prefixed words\"'),
(27897, 'classifier', 1, '/ˈklasᵻfʌɪə/', 'a word or morpheme used in some languages in certain contexts (such as counting) to indicate the semantic class to which the counted item belongs', NULL),
(27898, 'classifier', 1, '/ˈklasᵻfʌɪə/', 'a person who creates classifications', NULL),
(27899, 'ending', 1, '/ˈen.dɪŋ/', 'the end of a word (a suffix or inflectional ending or final morpheme)', '\"I don\'t like words that have -ism as an ending\"'),
(27900, 'ending', 1, '/ˈen.dɪŋ/', 'event whose occurrence ends something', '\"his death marked the ending of an era\"; \"when these final episodes are broadcast it will be the finish of the show\"'),
(27901, 'suffix', 1, '/ˈsʌf.ɪks/', 'an affix that is added at the end of the word', NULL),
(27902, 'suffix', 2, '/ˈsʌf.ɪks/', 'attach a suffix to', '\"suffix words\"'),
(27903, 'infix', 1, '/ˈɪn.fɪks/', 'an affix that is inserted inside the word', NULL),
(27904, 'infix', 2, '/ˈɪn.fɪks/', 'attach a morpheme into a stem word', NULL),
(27905, 'nominative', 1, '/ˈnɒm.ɪ.nə.tɪv/', 'the category of nouns serving as the grammatical subject of a verb', NULL),
(27906, 'nominative', 3, '/ˈnɒm.ɪ.nə.tɪv/', 'named; bearing the name of a specific person', '\"nominative shares of stock\"'),
(27907, 'nominative', 3, '/ˈnɒm.ɪ.nə.tɪv/', 'serving as or indicating the subject of a verb and words identified with the subject of a copular verb', '\"nominative noun endings\"; \"predicate nominative\"'),
(27908, 'oblique', 1, '/əˈbliːk/', 'any grammatical case other than the nominative', NULL),
(27909, 'oblique', 3, '/əˈbliːk/', 'slanting or inclined in direction or course or position--neither parallel nor perpendicular nor right-angled', '\"the oblique rays of the winter sun\"; \"acute and obtuse angles are oblique angles\"; \"the axis of an oblique cone is not perpendicular to its base\"'),
(27910, 'accusative', 1, '/əˈkjuː.zə.tɪv/', 'the case of nouns serving as the direct object of a verb', NULL),
(27911, 'accusative', 3, '/əˈkjuː.zə.tɪv/', 'containing or expressing accusation; \"accusive shoes and telltale trousers\"- O.Henry', '\"an accusitive forefinger\"; \"black accusatory looks\"; \"his accusing glare\"'),
(27912, 'dative', 1, '/ˈdeɪ.tɪv/', 'the category of nouns serving as the indirect object of a verb', NULL),
(27913, 'genitive', 1, '/ˈdʒen.ɪ.tɪv/', 'the case expressing ownership', NULL),
(27914, 'vocative', 1, '/ˈvɒk.ə.tɪv/', 'the case (in some inflected languages) used when the referent of the noun is being addressed', NULL),
