INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(30216, 'inquisition', 1, '/ˌɪn.kwɪˈzɪʃ.ən/', 'a severe interrogation (often violating the rights or privacy of individuals)', NULL),
