INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(32838, 'dead', 3, '/ded/', 'devoid of physical sensation; numb', '\"his gums were dead from the novocain\"; \"she felt no discomfort as the dentist drilled her deadened tooth\"; \"a public desensitized by continuous television coverage of atrocities\"'),
