(38478, 'interrupt', 2, '/ˈɪn.tə.rʌpt/', 'interfere in someone else\'s activity', '\"Please don\'t interrupt me while I\'m on the phone\"'),
(38479, 'interrupt', 2, '/ˈɪn.tə.rʌpt/', 'make a break in', '\"We interrupt the program for the following messages\"'),
(38480, 'doldrums', 1, '/ˈdəʊl.drəmz/', 'a belt of calms and light winds between the northern and southern trade winds of the Atlantic and Pacific', NULL),
(38481, 'galvanism', 1, '/ˈɡæl.və.nɪ.zəm/', 'electricity produced by chemical action', NULL),
(38482, 'epiphenomenon', 1, '/ˌɛp.i.fɪˈnɒm.ɪ.nɒn/', 'a secondary phenomenon that is a by-product of another phenomenon', NULL),
