(38484, 'firelight', 1, '/ˈfaɪə.laɪt/', 'the light of a fire (especially in a fireplace)', NULL),
(38485, 'fluorescence', 1, '/ˌflɔːˈres.əns/', 'light emitted during absorption of radiation of some other (invisible) wavelength', NULL),
(38486, 'fog', 1, '/fɒɡ/', 'droplets of water vapor suspended in the air near the ground', NULL),
