(38488, 'gale', 1, '/ɡeɪl/', 'a strong wind moving 45-90 knots; force 7 to 10 on Beaufort scale', NULL),
(38489, 'northeaster', 1, '/ˌnɔːθˈiː.stər/', 'a storm blowing from the northeast', NULL),
(38490, 'gaslight', 1, '/ˈɡæs.laɪt/', 'light yielded by the combustion of illuminating gas', NULL),
(38491, 'serendipity', 1, '/ˌser.ənˈdɪp.ɪ.ti/', 'good luck in making unexpected and fortunate discoveries', NULL),
(38492, 'gust', 1, '/ɡʌst/', 'a strong current of air', '\"the tree was bent almost double by the gust\"'),
(38493, 'bluster', 1, '/ˈblʌs.tər/', 'a violent gusty wind', NULL),
(38494, 'bluster', 1, '/ˈblʌs.tər/', 'noisy confusion and turbulence', '\"he was awakened by the bluster of their preparations\"'),
(38495, 'bluster', 2, '/ˈblʌs.tər/', 'blow hard; be gusty, as of wind', '\"A southeaster blustered onshore\"; \"The flames blustered\"'),
(38496, 'sandblast', 1, '/ˈsænd.blɑːst/', 'a blast of wind laden with sand', NULL),
(38497, 'sandblast', 2, '/ˈsænd.blɑːst/', 'grind with a sandblast', '\"sandblast the facade of the building\"'),
(38498, 'hailstorm', 1, '/ˈheɪl.stɔːm/', 'a storm during which hail falls', NULL),
(38499, 'haze', 1, '/heɪz/', 'atmospheric moisture or dust or smoke that causes reduced visibility', NULL),
(38500, 'haze', 2, '/heɪz/', 'harass by imposing humiliating or painful tasks, as in military institutions', NULL),
(38501, 'haze', 2, '/heɪz/', 'become hazy, dull, or cloudy', NULL),
(38502, 'histocompatibility', 1, '/ˌhɪs.təʊ.kəmˌpæt.əˈbɪl.ə.ti/', 'condition in which the cells of one tissue can survive in the presence of cells of another tissue', '\"a successful graft or transplant requires a high degree of histocompatibility\"'),
(38503, 'hurricane', 1, '/ˈhʌr.ɪ.kən/', 'a severe tropical cyclone usually with heavy rains and winds moving a 73-136 knots (12 on the Beaufort scale)', NULL),
(38504, 'hydroelectricity', 1, '/ˌhaɪ.drəʊ.ɪˌlekˈtrɪs.ɪ.ti/', 'electricity produced by water power', NULL),
(38505, 'hysteresis', 1, '/ˌhɪs.təˈriː.sɪs/', 'the lagging of an effect behind its cause; especially the phenomenon in which the magnetic induction of a ferromagnetic material lags behind the changing magnetic field', NULL),
(38506, 'incidence', 1, '/ˈɪn.sɪ.dəns/', 'the striking of a light beam on a surface', '\"he measured the angle of incidence of the reflected light\"'),
(38507, 'incidence', 1, '/ˈɪn.sɪ.dəns/', 'the relative frequency of occurrence of something', NULL),
(38508, 'inertia', 1, '/ɪˈnɜː.ʃə/', '(physics) the tendency of a body to maintain its state of rest or uniform motion unless acted upon by an external force', NULL),
(38509, 'lamplight', 1, '/ˈlæmp.laɪt/', 'light from a lamp', NULL),
(38510, 'elves', 1, '/ɛlvz/', 'an acronym for emissions of light and very low frequency perturbations due to electromagnetic pulse sources; extremely bright extremely short (less than a msec) electrical flashes forming a huge ring (up to 400 km diameter) in the ionosphere', NULL),
(38511, 'sprites', 1, '/spraɪts/', 'atmospheric electricity (lasting 10 msec) appearing as globular flashes of red (pink to blood-red) light rising to heights of 60 miles (sometimes seen together with elves)', NULL),
(38512, 'bioluminescence', 1, '/ˌbaɪ.əʊ.luː.mɪˈnes.əns/', 'luminescence produced by physiological processes (as in the firefly)', NULL),
(38513, 'chemiluminescence', 1, '/ˌkɛm.i.luː.mɪˈnes.əns/', 'luminescence resulting from a chemical reaction as the oxidation of luciferin in fireflies', NULL),
(38514, 'magnetosphere', 1, '/mæɡˈniː.təʊ.sfɪər/', 'the magnetic field of a planet; the volume around the planet in which charged particles are subject more to the planet\'s magnetic field than to the solar magnetic field', NULL),
(38515, 'diamagnetism', 1, '/ˌdaɪ.əʊˈmæɡ.nə.tɪ.zəm/', 'phenomenon exhibited by materials like copper or bismuth that become magnetized in a magnetic field with a polarity opposite to the magnetic force; unlike iron they are slightly repelled by a magnet', NULL),
(38516, 'ferromagnetism', 1, '/ˌfɛr.əʊˈmæɡ.nə.tɪ.zəm/', 'phenomenon exhibited by materials like iron (nickel or cobalt) that become magnetized in a magnetic field and retain their magnetism when the field is removed', NULL),
(38517, 'paramagnetism', 1, '/ˌpær.əʊˈmæɡ.nə.tɪ.zəm/', 'materials like aluminum or platinum become magnetized in a magnetic field but it disappears when the field is removed', NULL),
(38518, 'ultrasound', 1, '/ˈʌl.trə.saʊnd/', 'very high frequency sound; used in ultrasonography', NULL),
(38519, 'trajectory', 1, '/trəˈdʒek.tər.i/', 'the path followed by an object moving through space', NULL),
(38520, 'mist', 1, '/mɪst/', 'a thin fog with condensation near the ground', NULL),
(38521, 'mist', 2, '/mɪst/', 'become covered with mist', '\"The windshield misted over\"'),
(38522, 'mist', 2, '/mɪst/', 'spray finely or cover with mist', NULL),
(38523, 'mistral', 1, '/ˈmɪstrəl/', 'a strong north wind that blows in France during the winter', NULL),
(38524, 'meteor', 1, '/ˈmiːtɪɔːr/', 'a streak of light in the sky at night that results when a meteoroid hits the earth\'s atmosphere and air friction causes the meteoroid to melt or vaporize or explode', NULL),
(38525, 'bolide', 1, '/ˈbəʊ.laɪd/', 'an especially luminous meteor (sometimes exploding)', NULL),
(38526, 'monsoon', 1, '/ˈmɒnˌsuːn/', 'a seasonal wind in southern Asia; blows from the southwest (bringing rain) in summer and from the northeast in winter', NULL),
(38527, 'monsoon', 1, '/ˈmɒnˌsuːn/', 'any wind that changes direction with the seasons', NULL),
(38528, 'monsoon', 1, '/ˈmɒnˌsuːn/', 'rainy season in southern Asia when the southwestern monsoon blows, bringing heavy rains', NULL),
(38529, 'moonbeam', 1, '/ˈmuːnˌbiːm/', 'a ray of moonlight', NULL),
(38530, 'moonlight', 1, '/ˈmuːnlaɪt/', 'the light of the Moon', '\"moonlight is the smuggler\'s enemy\"; \"the Moon was bright enough to read by\"'),
(38531, 'moonlight', 2, '/ˈmuːnlaɪt/', 'work a second job, usually after hours', '\"The law student is moonlighting as a taxi driver\"'),
(38532, 'starlight', 1, '/ˈstɑːlaɪt/', 'the light of the stars', NULL),
(38533, 'sunlight', 1, '/ˈsʌnlaɪt/', 'the rays of the sun', '\"the shingles were weathered by the sun and wind\"'),
(38534, 'sunbeam', 1, '/ˈsʌnbiːm/', 'a ray of sunlight', NULL),
(38535, 'apoptosis', 1, '/ˌæpəʊˈtəʊsɪs/', 'a type of cell death in which the cell uses specialized cellular machinery to kill itself; a cell suicide mechanism that enables metazoans to control cell number and eliminate cells that threaten the animal\'s survival', NULL),
(38536, 'necrosis', 1, '/nɪˈkrəʊsɪs/', 'the localized death of living cells (as from infection or the interruption of blood supply)', NULL),
(38537, 'halo', 1, '/ˈheɪləʊ/', 'a circle of light around the sun or moon', NULL),
(38538, 'phosphorescence', 1, '/ˌfɒsfəˈrɛsəns/', 'a fluorescence that persists after the bombarding radiation has ceased', NULL),
(38539, 'piezoelectricity', 1, '/ˌpiːəʊˌzəʊɪˈlɛktrɪsɪti/', 'electricity produced by mechanical pressure on certain crystals (notably quartz or Rochelle salt); alternatively, electrostatic stress produces a change in the linear dimensions of the crystal', NULL),
(38540, 'pleochroism', 1, '/ˌpliːəʊˈkrəʊɪzəm/', 'the phenomenon of different colors appearing when certain crystals are viewed from different directions', NULL),
(38541, 'pleomorphism', 1, '/ˌpliːəʊˈmɔːfɪzəm/', '(biology) the appearance of two or more distinctly different forms in the life cycle of some organisms', NULL),
(38542, 'polarization', 1, '/ˌpəʊlərəˈzeɪʃən/', 'the phenomenon in which waves of light or other radiation are restricted in direction of vibration', NULL),
(38543, 'polarization', 1, '/ˌpəʊlərəˈzeɪʃən/', 'the condition of having or giving polarity', NULL),
(38544, 'depolarization', 1, '/ˌdiːpəʊləraɪˈzeɪʃən/', 'a loss of polarity or polarization', NULL),
(38545, 'polymorphism', 1, '/ˌpɒlɪˈmɔːfɪzəm/', '(biology) the existence of two or more forms of individuals within the same animal species (independent of sex differences)', NULL),
(38546, 'polymorphism', 1, '/ˌpɒlɪˈmɔːfɪzəm/', '(chemistry) the existence of different kinds of crystal of the same chemical compound', NULL),
