(38561, 'scattering', 1, '/ˈskætərɪŋ/', 'a light shower that falls in some locations and not others nearby', NULL),
(38562, 'scattering', 1, '/ˈskætərɪŋ/', 'the physical process in which particles are deflected haphazardly as a result of collisions', NULL),
(38563, 'scattering', 1, '/ˈskætərɪŋ/', 'a small number (of something) dispersed haphazardly', '\"the first scatterings of green\"; \"a sprinkling of grey at his temples\"'),
