(38576, 'flurry', 1, '/ˈflʌri/', 'a light brief snowfall and gust of wind (or something resembling that)', '\"he had to close the window against the flurries\"; \"there was a flurry of chicken feathers\"'),
(38577, 'flurry', 2, '/ˈflʌri/', 'move in an agitated or confused manner', NULL),
(38578, 'whiteout', 1, '/ˈwaɪtˌaʊt/', 'an arctic atmospheric condition with clouds over snow produce a uniform whiteness and objects are difficult to see; occurs when the light reflected off the snow equals the light coming through the clouds', NULL),
