(38584, 'sunspot', 1, '/ˈsʌnˌspɒt/', 'a cooler darker spot appearing periodically on the sun\'s photosphere; associated with a strong magnetic field', NULL),
(38585, 'conduction', 1, '/kənˈdʌkʃən/', 'the transmission of heat or electricity or sound', NULL),
(38586, 'spillover', 1, '/ˈspɪləʊvə/', '(economics) any indirect effect of public expenditure', NULL),
(38587, 'squall', 1, '/skwɔːl/', 'sudden violent winds; often accompanied by precipitation', NULL),
(38588, 'squall', 2, '/skwɔːl/', 'make high-pitched, whiney noises', NULL),
(38589, 'squall', 2, '/skwɔːl/', 'blow in a squall', '\"When it squalls, a prudent sailor reefs his sails\"'),
(38590, 'thermoelectricity', 1, '/ˌθɜːməʊɪˈlɛktrɪsɪti/', 'electricity produced by heat (as in a thermocouple)', NULL),
(38591, 'overstrain', 1, '/ˈəʊvərˌstreɪn/', 'too much strain', NULL),
(38592, 'overstrain', 2, '/ˈəʊvərˌstreɪn/', 'strain excessively', '\"He overextended himself when he accepted the additional assignment\"'),
(38593, 'torchlight', 1, '/ˈtɔːtʃlaɪt/', 'light from a torch or torches', NULL),
(38594, 'twilight', 1, '/ˈtwaɪˌlaɪt/', 'the diffused light from the sky when the sun is below the horizon but its rays are refracted by the atmosphere of the earth', NULL),
(38595, 'twilight', 1, '/ˈtwaɪˌlaɪt/', 'a condition of decline following successes', '\"in the twilight of the empire\"'),
(38596, 'twilight', 1, '/ˈtwaɪˌlaɪt/', 'the time of day immediately following sunset', '\"he loved the twilight\"; \"they finished before the fall of night\"'),
(38597, 'suction', 1, '/ˈsʌkʃən/', 'a force over an area produced by a pressure difference', NULL),
(38598, 'suction', 2, '/ˈsʌkʃən/', 'empty or clean (a body cavity) by the force of suction', '\"suction the uterus in an abortion\"'),
(38599, 'suction', 2, '/ˈsʌkʃən/', 'remove or draw away by the force of suction', '\"the doctors had to suction the water from the patient\'s lungs\"'),
(38600, 'syzygy', 1, '/ˈsɪzɪdʒi/', 'the straight line configuration of 3 celestial bodies (as the sun and earth and moon) in a gravitational system', NULL),
(38601, 'tempest', 1, '/ˈtɛmpɪst/', '(literary) a violent wind', '\"a tempest swept over the island\"'),
(38602, 'thermal', 1, '/ˈθɜːməl/', 'rising current of warm air', NULL),
(38603, 'thermal', 3, '/ˈθɜːməl/', 'caused by or designed to retain heat', '\"a thermal burn\"; \"thermal underwear\"'),
(38604, 'thermal', 3, '/ˈθɜːməl/', 'of or relating to a hot spring', '\"thermal water\"'),
(38605, 'thermal', 3, '/ˈθɜːməl/', 'relating to or associated with heat', '\"thermal movements of molecules\"; \"thermal capacity\"; \"thermic energy\"; \"the caloric effect of sunlight\"'),
(38606, 'thunderbolt', 1, '/ˈθʌndəbəʊlt/', 'a discharge of lightning accompanied by thunder', NULL),
(38607, 'thunderstorm', 1, '/ˈθʌndəˌstɔːm/', 'a storm resulting from strong rising air currents; heavy rain or hail along with thunder and lightning', NULL),
(38608, 'tornado', 1, '/tɔːˈneɪdəʊ/', 'a localized and violently destructive windstorm occurring over land characterized by a funnel-shaped cloud extending toward the ground', NULL),
(38609, 'torsion', 1, '/ˈtɔːʃən/', 'a twisting force', NULL),
(38610, 'tossup', 1, '/ˈtɒsʌp/', 'an unpredictable phenomenon', '\"it\'s a toss-up whether he will win or lose\"'),
(38611, 'tramontane', 1, '/træˈmɒnˌteɪn/', 'a cold dry wind that blows south out of the mountains into Italy and the western Mediterranean', NULL),
(38612, 'tramontane', 3, '/træˈmɒnˌteɪn/', 'on or coming from the other side of the mountains (from the speaker)', '\"the transmontane section of the state\"; \"tramontane winds\"'),
(38613, 'tramontane', 3, '/træˈmɒnˌteɪn/', 'being or coming from another country', '\"tramontane influences\"'),
(38614, 'turbulence', 1, '/ˈtɜːbjʊləns/', 'unstable flow of a liquid or gas', NULL),
(38615, 'turbulence', 1, '/ˈtɜːbjʊləns/', 'a state of violent disturbance and disorder (as in politics or social conditions generally)', '\"the industrial revolution was a period of great turbulence\"'),
(38616, 'turbulence', 1, '/ˈtɜːbjʊləns/', 'instability in the atmosphere', NULL),
(38617, 'typhoon', 1, '/ˈtaɪfuːn/', 'a tropical cyclone occurring in the western Pacific or Indian oceans', NULL),
(38618, 'ultraviolet', 1, '/ˈʌltrəˌvaɪələt/', 'radiation lying in the ultraviolet range; wave lengths shorter than light but longer than X rays', NULL),
(38619, 'ultraviolet', 3, '/ˈʌltrəˌvaɪələt/', 'having or employing wavelengths shorter than light but longer than X-rays; lying outside the visible spectrum at its violet end', '\"ultraviolet radiation\"; \"an ultraviolet lamp\"'),
(38620, 'sunray', 1, '/ˈsʌnreɪ/', 'a ray of artificial ultraviolet light from a sunray lamp', NULL),
(38621, 'sunray', 1, '/ˈsʌnreɪ/', 'herb having a basal cluster of grey-green leaves and leafless stalks each with a solitary broad yellow flower head; desert areas Idaho to Arizona', NULL),
(38622, 'updraft', 1, '/ˈʌpdrɑːft/', 'a strong upward air current', NULL),
(38623, 'downdraft', 1, '/ˈdaʊndræft/', 'a strong downward air current', NULL),
(38624, 'voltage', 1, '/ˈvɒltɪdʒ/', 'the rate at which energy is drawn from a source that produces a flow of electricity in a circuit; expressed in volts', NULL),
(38625, 'volcanism', 1, '/vɒlˈkeɪnɪzəm/', 'the phenomena associated with volcanic activity', NULL),
(38626, 'waterpower', 1, '/ˈwɔːtərˌpaʊər/', 'the power to do work that is latent in a head of water', NULL);
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(38627, 'weather', 1, '/ˈwɛðər/', 'the atmospheric conditions that comprise the state of the atmosphere in terms of temperature and wind and clouds and precipitation', '\"they were hoping for good weather\"; \"every day we have weather conditions and yesterday was no exception\"; \"the conditions were too rainy for playing in the snow\"'),
(38628, 'weather', 2, '/ˈwɛðər/', 'change under the action or influence of the weather', '\"A weathered old hut\"'),
(38629, 'weather', 2, '/ˈwɛðər/', 'sail to the windward of', NULL),
(38630, 'weather', 2, '/ˈwɛðər/', 'cause to slope', NULL),
(38631, 'weather', 2, '/ˈwɛðər/', 'face and withstand with courage', '\"She braved the elements\"'),
(38632, 'elements', 1, '/ˈɛlɪmənts/', 'violent or severe weather (viewed as caused by the action of the four elements)', '\"they felt the full fury of the elements\"'),
(38633, 'whirlwind', 1, '/ˈwɜːlˌwɪnd/', 'a more or less vertical column of air whirling around itself as it moves over the surface of the Earth', NULL),
(38634, 'windstorm', 1, '/ˈwɪndstɔːm/', 'a storm consisting of violent winds', NULL),
(38635, 'parallax', 1, '/ˈpærəlæks/', 'the apparent displacement of an object as seen from two different points that are not on a line with the object', NULL),
(38636, 'microflora', 1, '/ˈmaɪkrəʊˌflɔːrə/', 'microscopic plants; bacteria are often considered to be microflora', NULL),
(38637, 'endemic', 1, '/ɪnˈdɛmɪk/', 'a plant that is native to a certain limited area', '\"it is an endemic found only this island\"'),
(38638, 'endemic', 1, '/ɪnˈdɛmɪk/', 'a disease that is constantly present to a greater or lesser degree in people of a certain class or in people living in a particular location', NULL),
(38639, 'endemic', 3, '/ɪnˈdɛmɪk/', 'native to or confined to a certain region', '\"the islands have a number of interesting endemic species\"'),
(38640, 'endemic', 3, '/ɪnˈdɛmɪk/', 'of or relating to a disease (or anything resembling a disease) constantly present to greater or lesser extent in a particular locality', '\"diseases endemic to the tropics\"; \"endemic malaria\"; \"food shortages and starvation are endemic in certain parts of the world\"'),
(38641, 'thallus', 1, '/ˈθæləs/', 'a plant body without true stems or roots or leaves or vascular system; characteristic of the thallophytes', NULL),
(38642, 'calyptra', 1, '/kəˈlɪptrə/', 'the hood or cap covering the calyx of certain plants: e.g., the California poppy', NULL),
