(41018, 'situation', 1, '/ˈsɪtjʊˌeɪʃən/', 'a condition or position in which you find yourself', '\"the unpleasant situation (or position) of having to choose between two evils\"; \"found herself in a very fortunate situation\"'),
(41019, 'situation', 1, '/ˈsɪtjʊˌeɪʃən/', 'the general state of things; the combination of circumstances at a given time; \"eternal truths will be neither true nor eternal unless they have fresh meaning for every new social situation\"- Franklin D.Roosevelt', '\"the present international situation is dangerous\"; \"wondered how such a state of affairs had come about\"'),
(41020, 'situation', 1, '/ˈsɪtjʊˌeɪʃən/', 'a complex or critical or unusual difficulty', '\"the dangerous situation developed suddenly\"; \"that\'s quite a situation\"; \"no human situation is simple\"'),
(41021, 'nationhood', 1, '/ˈneɪʃənhʊd/', 'the state of being a nation', NULL),
(41022, 'absurd', 1, '/əbˈsɜːd/', 'a situation in which life seems irrational and meaningless; \"The absurd is the essential concept and the first truth\"--Albert Camus', NULL),
(41023, 'absurd', 3, '/əbˈsɜːd/', 'inconsistent with reason or logic or common sense; \"the absurd predicament of seeming to argue that virtue is highly desirable but intensely unpleasant\"- Walter Lippman', NULL),
(41024, 'absurd', 3, '/əbˈsɜːd/', 'incongruous;inviting ridicule', '\"the absurd excuse that the dog ate his homework\"; \"that\'s a cockeyed idea\"; \"ask a nonsensical question and get a nonsensical answer\"; \"a contribution so small as to be laughable\"; \"it is ludicrous to call a cottage a mansion\"; \"a preposterous attempt to turn back the pages of history\"; \"her conceited assumption of universal interest in her rather dull children was ridiculous\"'),
(41025, 'freemasonry', 1, '/ˈfriːˌmeɪsənri/', 'a natural or instinctive fellowship between people of similar interests', '\"he enjoyed the freemasonry of the Press\"'),
