(41703, 'amenorrhea', 1, '/ˌæmɪnəʊˈrɪə/', 'absence or suppression of normal menstrual flow', NULL),
(41704, 'clubbing', 1, '/ˈklʌbɪŋ/', 'a condition in which the ends of toes and fingers become wide and thick; a symptom of heart or lung disease', NULL),
(41705, 'cyanosis', 1, '/ˈsaɪəˌnəʊsɪs/', 'a bluish discoloration of the skin and mucous membranes; a sign that oxygen in the blood is dangerously diminished (as in carbon monoxide poisoning)', NULL),
(41706, 'diuresis', 1, '/djuːˈɹiːsɪs/', 'increased secretion of urine; if not due to increased liquid intake or to the action of a diuretic drug it can be a symptom of diabetes mellitus', NULL),
(41707, 'prodrome', 1, '/ˈprəʊdrəʊm/', 'an early symptom that a disease is developing or that an attack is about to occur', NULL),
(41708, 'narcolepsy', 1, '/ˈnɑːkəʊˌlɛpsi/', 'a sleep disorder characterized by sudden and uncontrollable episodes of deep sleep', '\"he believes that narcolepsy is attributable to an inability to suppress REM sleep during waking\"'),
(41709, 'tetany', 1, '/ˈtɛtəni/', 'clinical neurological syndrome characterized by muscular twitching and cramps and (when severe) seizures; associated with calcium deficiency (hypoparathyroidism) or vitamin D deficiency or alkalosis', NULL),
(41710, 'bummer', 1, '/ˈbʌmə/', 'a bad reaction to a hallucinogenic drug', NULL),
(41711, 'bummer', 1, '/ˈbʌmə/', 'an experience that is irritating or frustrating or disappointing', '\"having to stand in line so long was a real bummer\"'),
