(41713, 'exophthalmos', 1, '/ˌɛksəʊfˈθælməs/', 'protrusion of the eyeball from the socket', NULL),
(41714, 'furring', 1, '/ˈfɜːrɪŋ/', 'a furlike coating of matter as on the tongue', NULL),
(41715, 'gangrene', 1, '/ˈɡæŋɡriːn/', 'necrotic tissue; a mortified or gangrenous part or mass', NULL),
(41716, 'hematuria', 1, '/ˌhiːmæˈtjʊəɹɪə/', 'the presence of blood in the urine; often a symptom of urinary tract disease', NULL),
(41717, 'hemoglobinuria', 1, '/ˌhɛməʊˈɡləʊbɪnˈjʊəɹɪə/', 'presence of hemoglobin in the urine', NULL),
(41718, 'sneeze', 1, '/sniːz/', 'a symptom consisting of the involuntary expulsion of air from the nose', NULL),
(41719, 'sneeze', 2, '/sniːz/', 'exhale spasmodically, as when an irritant entered one\'s nose', '\"Pepper makes me sneeze\"'),
(41720, 'swelling', 1, '/ˈswɛlɪŋ/', 'an abnormal protuberance or localized enlargement', NULL),
(41721, 'bloat', 1, '/bləʊt/', 'swelling of the rumen or intestinal tract of domestic animals caused by excessive gas', NULL),
(41722, 'bloat', 2, '/bləʊt/', 'become bloated or swollen or puff up', '\"The dead man\'s stomach was bloated\"'),
(41723, 'bloat', 2, '/bləʊt/', 'make bloated or swollen', '\"Hunger bloated the child\'s belly\"'),
(41724, 'bubo', 1, '/ˈbjuːbəʊ/', 'a lymph node that is inflamed and swollen because of plague or gonorrhea or tuberculosis', NULL),
(41725, 'papilledema', 1, '/ˌpæpɪlɪˈdiːmə/', 'swelling of the optic disc (where the optic nerve enters the eyeball); usually associated with an increase in intraocular pressure', NULL),
