(41728, 'palsy', 2, '/ˈpɑːlzi/', 'affect with palsy', NULL),
(41729, 'edema', 1, '/ɪˈdiːmə/', 'swelling from excessive accumulation of watery fluid in cells, tissues, or serous cavities', NULL),
(41730, 'tumescence', 1, '/tjuːˈmɛsəns/', 'tumidity resulting from the presence of blood or other fluid in the tissues', NULL),
(41731, 'hematoma', 1, '/ˌhiːmæˈtəʊmə/', 'a localized swelling filled with blood', NULL),
(41732, 'hyperbilirubinemia', 1, '/ˌhaɪpərˌbɪlɪˈrʌbɪnɪə/', 'abnormally high amounts of bile pigment (bilirubin) in the blood', NULL),
(41733, 'hyperglycemia', 1, '/ˌhaɪpərˌɡlaɪsɪˈmiːə/', 'abnormally high blood sugar usually associated with diabetes', NULL),
(41734, 'hypoglycemia', 1, '/ˌhaɪpəʊˈɡlaɪsɪˈmiːə/', 'abnormally low blood sugar usually resulting from excessive insulin or a poor diet', NULL),
(41735, 'jaundice', 1, '/ˈdʒɔːndɪs/', 'yellowing of the skin and the whites of the eyes caused by an accumulation of bile pigment (bilirubin) in the blood; can be a symptom of gallstones or liver infection or anemia', NULL),
(41736, 'jaundice', 2, '/ˈdʒɔːndɪs/', 'affect with, or as if with, jaundice', NULL),
(41737, 'jaundice', 2, '/ˈdʒɔːndɪs/', 'distort adversely', '\"Jealousy had jaundiced his judgment\"'),
(41738, 'kernicterus', 1, '/ˌkɜːnɪkˈtɛrəs/', 'an abnormal accumulation of bile pigment in the brain and other nerve tissue; causes yellow staining and tissue damage', NULL),
(41739, 'hemothorax', 1, '/ˈhiːməʊˌθɔːræks/', 'accumulation of blood in the pleural cavity (the space between the lungs and the walls of the chest)', NULL),
(41740, 'hyperemia', 1, '/ˌhaɪpəˈriːmɪə/', 'increased blood in an organ or other body part', NULL),
(41741, 'numbness', 1, '/ˈnʌmnəs/', 'partial or total lack of sensation in a part of the body; a symptom of nerve damage or dysfunction', NULL),
(41742, 'ache', 1, '/eɪk/', 'a dull persistent (usually moderately intense) pain', NULL),
(41743, 'ache', 2, '/eɪk/', 'have a desire for something or someone who is not present', '\"She ached for a cigarette\"; \"I am pining for my lover\"'),
(41744, 'ache', 2, '/eɪk/', 'be the source of pain', NULL),
(41745, 'toothache', 1, '/ˈtuːθeɪk/', 'an ache localized in or around a tooth', NULL),
(41746, 'arthralgia', 1, '/ɑːθˈrældʒɪə/', 'pain in a joint or joints', NULL),
(41747, 'throe', 1, '/θrəʊ/', 'severe spasm of pain', '\"the throes of dying\"; \"the throes of childbirth\"'),
(41748, 'throe', 1, '/θrəʊ/', 'hard or painful trouble or struggle', '\"a country in the throes of economic collapse\"');
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(41749, 'paresthesia', 1, '/ˌpærɛsˈθɪə/', 'abnormal skin sensations (as tingling or tickling or itching or burning) usually associated with peripheral nerve damage', NULL),
