(41757, 'migraine', 1, '/ˈmaɪɡreɪn/', 'a severe recurring vascular headache; occurs more frequently in women than men', NULL),
(41758, 'lumbago', 1, '/ˈlʌmˌbeɪɡəʊ/', 'backache affecting the lumbar region or lower back; can be caused by muscle strain or arthritis or vascular insufficiency or a ruptured intervertebral disc', NULL),
