(41761, 'sciatica', 1, '/saɪˈætɪkə/', 'neuralgia along the sciatic nerve', NULL),
(41762, 'smart', 1, '/smɑːt/', 'a kind of pain such as that caused by a wound or a burn or a sore', NULL),
(41763, 'smart', 3, '/smɑːt/', 'capable of independent and apparently intelligent action', '\"smart weapons\"'),
(41764, 'smart', 3, '/smɑːt/', 'showing mental alertness and calculation and resourcefulness', NULL),
(41765, 'smart', 3, '/smɑːt/', 'quick and brisk', '\"I gave him a smart salute\"; \"we walked at a smart pace\"'),
(41766, 'smart', 3, '/smɑːt/', 'painfully severe', '\"he gave the dog a smart blow\"'),
(41767, 'chafe', 1, '/ʧeɪf/', 'soreness and warmth caused by friction', '\"he had a nasty chafe on his knee\"'),
(41768, 'chafe', 2, '/ʧeɪf/', 'warm by rubbing, as with the hands', NULL),
(41769, 'chafe', 2, '/ʧeɪf/', 'tear or wear off the skin or make sore by abrading', '\"This leash chafes the dog\'s neck\"'),
(41770, 'chafe', 2, '/ʧeɪf/', 'feel extreme irritation or anger', '\"He was chafing at her suggestion that he stay at home while she went on a vacation\"'),
(41771, 'chafe', 2, '/ʧeɪf/', 'become or make sore by or as if by rubbing', NULL),
(41772, 'papule', 1, '/ˈpæpjuːl/', 'a small inflamed elevation of skin that is nonsuppurative (as in chicken pox)', NULL),
