(42383, 'americium', 1, '/əˈmɛrɪsɪəm/', 'a radioactive transuranic metallic element; discovered by bombarding uranium with helium atoms', NULL),
(42384, 'antimony', 1, '/ˈæntɪməni/', 'a metallic element having four allotropic forms; used in a wide variety of alloys; found in stibnite', NULL),
(42385, 'argon', 1, '/ˈɑːɡən/', 'a colorless and odorless inert gas; one of the six inert gases; comprises approximately 1% of the earth\'s atmosphere', NULL),
(42386, 'arsenic', 1, '/ˈɑːsɛnɪk/', 'a very poisonous metallic element that has three allotropic forms; arsenic and arsenic compounds are used as herbicides and insecticides and various alloys; found in arsenopyrite and orpiment and realgar', NULL),
(42387, 'arsenic', 1, '/ˈɑːsɛnɪk/', 'a white powdered poisonous trioxide of arsenic; used in manufacturing glass and as a pesticide (rat poison) and weed killer', NULL),
(42388, 'astatine', 1, '/ˈæstətiːn/', 'a highly unstable radioactive element (the heaviest of the halogen series); a decay product of uranium and thorium', NULL),
(42389, 'atrazine', 1, '/ˈætræziːn/', 'a synthetic compound derived from triazine that is widely used as an agricultural herbicide', '\"atrazine is thought to cause cancer and is banned in some European countries\"'),
(42390, 'barium', 1, '/ˈbɛəɹiəm/', 'a soft silvery metallic element of the alkali earth group; found in barite', NULL),
(42391, 'berkelium', 1, '/ˈbɜːrkɛlɪəm/', 'a radioactive transuranic element; discovered by bombarding americium with helium', NULL),
(42392, 'beryllium', 1, '/bəˈrɪlɪəm/', 'a light strong brittle grey toxic bivalent metallic element', NULL),
(42393, 'bismuth', 1, '/ˈbɪzməθ/', 'a heavy brittle diamagnetic trivalent metallic element (resembles arsenic and antimony chemically); usually recovered as a by-product from ores of other metals', NULL),
(42394, 'boron', 1, '/ˈbɔːrɒn/', 'a trivalent metalloid element; occurs both in a hard black crystal and in the form of a yellow or brown powder', NULL),
(42395, 'bromine', 1, '/ˈbrəʊmiːn/', 'a nonmetallic heavy volatile corrosive dark brown liquid element belonging to the halogens; found in sea water', NULL),
(42396, 'cadmium', 1, '/ˈkædmɪəm/', 'a soft bluish-white ductile malleable toxic bivalent metallic element; occurs in association with zinc ores', NULL),
(42397, 'calcium', 1, '/ˈkælsiəm/', 'a white metallic element that burns with a brilliant light; the fifth most abundant element in the earth\'s crust; an important component of most plants and animals', NULL),
(42398, 'californium', 1, '/ˌkælɪˈfɔːnɪəm/', 'a radioactive transuranic element; discovered by bombarding curium with alpha particles', NULL),
(42399, 'radiocarbon', 1, '/ˈreɪdɪəʊˌkɑːrbən/', 'a radioactive isotope of carbon', NULL),
(42400, 'cerium', 1, '/ˈsɪərɪəm/', 'a ductile grey metallic element of the lanthanide series; used in lighter flints; the most abundant of the rare-earth group', NULL),
(42401, 'cesium', 1, '/ˈsɪziəm/', 'a soft silver-white ductile metallic element (liquid at normal temperatures); the most electropositive and alkaline metal', NULL),
(42402, 'chlorine', 1, '/ˈklɔːriːn/', 'a common nonmetallic element belonging to the halogens; best known as a heavy yellow irritating toxic gas; used to purify water and as a bleaching agent and disinfectant; occurs naturally only as a salt (as in sea water)', NULL),
(42403, 'chromium', 1, '/ˈkrəʊmiəm/', 'a hard brittle multivalent metallic element; resistant to corrosion and tarnishing', NULL),
(42404, 'cobalt', 1, '/ˈkəʊbɔːlt/', 'a hard ferromagnetic silver-white bivalent or trivalent metallic element; a trace element in plant and animal nutrition', NULL),
(42405, 'curium', 1, '/ˈkjʊərɪəm/', 'a radioactive transuranic metallic element; produced by bombarding plutonium with helium nuclei', NULL),
(42406, 'dysprosium', 1, '/dɪsˈprəʊzɪəm/', 'a trivalent metallic element of the rare earth group; forms compounds that are highly magnetic', NULL),
(42407, 'einsteinium', 1, '/ˈaɪnstaɪniəm/', 'a radioactive transuranic element produced by bombarding plutonium with neutrons', NULL),
(42408, 'erbium', 1, '/ˈɜːbɪəm/', 'a trivalent metallic element of the rare earth group; occurs with yttrium', NULL),
(42409, 'europium', 1, '/ˈjʊəroʊpiəm/', 'a bivalent and trivalent metallic element of the rare earth group', NULL),
(42410, 'fermium', 1, '/ˈfɜːmɪəm/', 'a radioactive transuranic metallic element produced by bombarding plutonium with neutrons', NULL),
(42411, 'fluorine', 1, '/ˈflʊəɹɪn/', 'a nonmetallic univalent element belonging to the halogens; usually a yellow irritating toxic flammable gas; a powerful oxidizing agent; recovered from fluorite or cryolite or fluorapatite', NULL),
(42412, 'francium', 1, '/ˈfrænsɪəm/', 'a radioactive element of the alkali-metal group discovered as a disintegration product of actinium', NULL),
(42413, 'gadolinium', 1, '/ˈɡædəˌlɪnɪəm/', 'a ductile silvery-white ductile ferromagnetic trivalent metallic element of the rare earth group', NULL),
(42414, 'gallium', 1, '/ˈɡæliəm/', 'a rare silvery (usually trivalent) metallic element; brittle at low temperatures but liquid above room temperature; occurs in trace amounts in bauxite and zinc ores', NULL),
(42415, 'germanium', 1, '/ˈdʒɜːmənɪəm/', 'a brittle grey crystalline element that is a semiconducting metalloid (resembling silicon) used in transistors; occurs in germanite and argyrodite', NULL),
(42416, 'hafnium', 1, '/ˈhæfniəm/', 'a grey tetravalent metallic element that resembles zirconium chemically and is found in zirconium minerals; used in filaments for its ready emission of electrons', NULL),
(42417, 'helium', 1, '/ˈhiːliəm/', 'a very light colorless element that is one of the six inert gasses; the most difficult gas to liquefy; occurs in economically extractable amounts in certain natural gases (as those found in Texas and Kansas)', NULL),
(42418, 'holmium', 1, '/ˈhoʊlmɪəm/', 'a trivalent metallic element of the rare earth group; occurs together with yttrium; forms highly magnetic compounds', NULL),
(42419, 'hydrogen', 1, '/ˈhaɪdrədʒən/', 'a nonmetallic univalent element that is normally a colorless and odorless highly flammable diatomic gas; the simplest and lightest and most abundant element in the universe', NULL),
(42420, 'deuterium', 1, '/dɪˈjʊːtəɹɪəm/', 'an isotope of hydrogen which has one neutron (as opposed to zero neutrons in hydrogen)', NULL),
(42421, 'indium', 1, '/ˈɪndɪəm/', 'a rare soft silvery metallic element; occurs in small quantities in sphalerite', NULL),
(42422, 'iodine', 1, '/ˈaɪ.ə.diːn/', 'a nonmetallic element belonging to the halogens; used especially in medicine and photography and in dyes; occurs naturally only in combination in small quantities (as in sea water or rocks)', NULL),
(42423, 'iridium', 1, '/ɪˈrɪd.i.əm/', 'a heavy brittle metallic element of the platinum group; used in alloys; occurs in natural alloys with platinum or osmium', NULL),
(42424, 'krypton', 1, '/ˈkrɪp.tɒn/', 'a colorless element that is one of the six inert gasses; occurs in trace amounts in air', NULL),
(42425, 'lanthanum', 1, '/ˈlanθənəm/', 'a white soft metallic element that tarnishes readily; occurs in rare earth minerals and is usually classified as a rare earth', NULL),
(42426, 'lawrencium', 1, '/ləˈrɛn(t)siəm/', 'a radioactive transuranic element synthesized from californium', NULL),
(42427, 'lithium', 1, '/ˈlɪθ.i.əm/', 'a soft silver-white univalent element of the alkali metal group; the lightest metal known; occurs in several minerals', NULL),
(42428, 'lutetium', 1, '/luːˈtiːʃiəm/', 'a trivalent metallic element of the rare earth group; usually occurs in association with yttrium', NULL),
(42429, 'magnesium', 1, '/mæɡˈniː.zi.əm/', 'a light silver-white ductile bivalent metallic element; in pure form it burns with brilliant white flame; occurs naturally only in combination (as in magnesite and dolomite and carnallite and spinel and olivine)', NULL),
(42430, 'manganese', 1, '/ˈmæŋ.ɡə.niːz/', 'a hard brittle grey polyvalent metallic element that resembles iron but is not magnetic; used in making steel; occurs in many minerals', NULL),
(42431, 'mendelevium', 1, '/ˌmɛndəˈliːviəm/', 'a radioactive transuranic element synthesized by bombarding einsteinium with alpha particles (Md is the current symbol for mendelevium but Mv was formerly the symbol)', NULL),
(42432, 'molybdenum', 1, '/mɒlˈɪb.də.nəm/', 'a polyvalent metallic element that resembles chromium and tungsten in its properties; used to strengthen and harden steel', NULL),
(42433, 'neodymium', 1, '/ˌniːə(ʊ)ˈdɪmiəm/', 'a yellow trivalent metallic element of the rare earth group; occurs in monazite and bastnasite in association with cerium and lanthanum and praseodymium', NULL),
(42434, 'neon', 1, '/ˈniː.ɒn/', 'a colorless odorless gaseous element that give a red glow in a vacuum tube; one of the six inert gasses; occurs in the air in small amounts', NULL),
(42435, 'neptunium', 1, '/nɛpˈtjuːniəm/', 'a radioactive transuranic metallic element; found in trace amounts in uranium ores; a by-product of the production of plutonium', NULL),
(42436, 'niobium', 1, '/nʌɪˈəʊbiəm/', 'a soft grey ductile metallic element used in alloys; occurs in niobite; formerly called columbium', NULL),
(42437, 'nitrogen', 1, '/ˈnaɪ.trə.dʒən/', 'a common nonmetallic element that is normally a colorless odorless tasteless inert diatomic gas; constitutes 78 percent of the atmosphere by volume; a constituent of all living tissues', NULL),
(42438, 'azote', 1, '/aˈzəʊt/', 'an obsolete name for nitrogen', NULL),
(42439, 'osmium', 1, '/ˈɒzmiəm/', 'a hard brittle blue-grey or blue-black metallic element that is one of the platinum metals; the heaviest metal known', NULL),
(42440, 'oxygen', 1, '/ˈɒk.sɪ.dʒən/', 'a nonmetallic bivalent element that is normally a colorless odorless tasteless nonflammable diatomic gas; constitutes 21 percent of the atmosphere by volume; the most abundant element in the earth\'s crust', NULL),
(42441, 'palladium', 1, '/pəˈleɪdiəm/', 'a silver-white metallic element of the platinum group that resembles platinum; occurs in some copper and nickel ores; does not tarnish at ordinary temperatures and is used (alloyed with gold) in jewelry', NULL),
(42442, 'phosphor', 1, '/ˈfɒsfə/', 'a synthetic substance that is fluorescent or phosphorescent; used to coat the screens of cathode ray tubes', NULL),
(42443, 'phosphorus', 1, '/ˈfɒs.fər.əs/', 'a multivalent nonmetallic element of the nitrogen family that occurs commonly in inorganic phosphate rocks and as organic phosphates in all living cells; is highly reactive and occurs in several allotropic forms', NULL),
(42444, 'platinum', 1, '/ˈplæt.ɪ.nəm/', 'a heavy precious metallic element; grey-white and resistant to corroding; occurs in some nickel and copper ores and is also found native in some deposits', NULL),
(42445, 'plutonium', 1, '/pluːˈtəʊ.ni.əm/', 'a solid silvery grey radioactive transuranic element whose atoms can be split when bombarded with neutrons; found in minute quantities in uranium ores but is usually synthesized in nuclear reactors; 13 isotopes are known with the most important being plutonium 239', NULL),
(42446, 'polonium', 1, '/pəˈləʊ.ni.əm/', 'a radioactive metallic element that is similar to tellurium and bismuth; occurs in uranium ores but can be produced by bombarding bismuth with neutrons in a nuclear reactor', NULL),
(42447, 'potassium', 1, '/pəˈtæs.i.əm/', 'a light soft silver-white metallic element of the alkali metal group; oxidizes rapidly in air and reacts violently with water; is abundant in nature in combined forms occurring in sea water and in carnallite and kainite and sylvite', NULL),
(42448, 'praseodymium', 1, '/ˌpreɪziə(ʊ)ˈdɪmiəm/', 'a soft yellowish-white trivalent metallic element of the rare earth group; can be recovered from bastnasite or monazite by an ion-exchange process', NULL),
(42449, 'promethium', 1, '/prəˈmiːθiəm/', 'a soft silvery metallic element of the rare earth group having no stable isotope; was discovered in radioactive form as a fission product of uranium', NULL),
(42450, 'protactinium', 1, '/ˌprəʊtakˈtɪniəm/', 'a short-lived radioactive metallic element formed from uranium and disintegrating into actinium and then into lead', NULL),
(42451, 'radium', 1, '/ˈreɪ.di.əm/', 'an intensely radioactive metallic element that occurs in minute amounts in uranium ores', NULL),
(42452, 'radon', 1, '/ˈreɪ.dɒn/', 'a radioactive gaseous element formed by the disintegration of radium; the heaviest of the inert gasses; occurs naturally (especially in areas over granite) and is considered a hazard to health', NULL),
(42453, 'rhenium', 1, '/ˈriːniəm/', 'a rare heavy polyvalent metallic element that resembles manganese chemically and is used in some alloys; is obtained as a by-product in refining molybdenum', NULL),
(42454, 'rhodium', 1, '/ˈrəʊdiəm/', 'a white hard metallic element that is one of the platinum group and is found in platinum ores; used in alloys with platinum', NULL),
(42455, 'rubidium', 1, '/ruːˈbɪdiəm/', 'a soft silvery metallic element of the alkali metal group; burns in air and reacts violently in water; occurs in carnallite and lepidolite and pollucite', NULL),
(42456, 'ruthenium', 1, '/rʊˈθiːniəm/', 'a rare polyvalent metallic element of the platinum group; it is found associated with platinum', NULL),
(42457, 'samarium', 1, '/səˈmɛːriəm/', 'a grey lustrous metallic element of the rare earth group; is used in special alloys; occurs in monazite and bastnasite', NULL),
(42458, 'scandium', 1, '/ˈskandiəm/', 'a white trivalent metallic element; sometimes classified in the rare earth group; occurs in the Scandinavian mineral thortveitite', NULL),
(42459, 'seaborgium', 1, '/siːˈbɔːɡiəm/', 'a transuranic element', NULL),
(42460, 'selenium', 1, '/səˈliː.ni.əm/', 'a toxic nonmetallic element related to sulfur and tellurium; occurs in several allotropic forms; a stable grey metallike allotrope conducts electricity better in the light than in the dark and is used in photocells; occurs in sulfide ores (as pyrite)', NULL),
(42461, 'silicon', 1, '/ˈsɪl.ɪ.kən/', 'a tetravalent nonmetallic element; next to oxygen it is the most abundant element in the earth\'s crust; occurs in clay and feldspar and granite and quartz and sand; used as a semiconductor in transistors', NULL),
(42462, 'sodium', 1, '/ˈsəʊ.di.əm/', 'a silvery soft waxy metallic element of the alkali metal group; occurs abundantly in natural compounds (especially in salt water); burns with a yellow flame and reacts violently in water; occurs in sea water and in the mineral halite (rock salt)', NULL),
(42463, 'strontium', 1, '/ˈstrɒn.ti.əm/', 'a soft silver-white or yellowish metallic element of the alkali metal group; turns yellow in air; occurs in celestite and strontianite', NULL),
(42464, 'sulfur', 1, '/ˈsʌl.fər/', 'an abundant tasteless odorless multivalent nonmetallic element; best known in yellow crystals; occurs in many sulphide and sulphate minerals and even in native form (especially in volcanic regions)', NULL),
(42465, 'tantalum', 1, '/ˈtantələm/', 'a hard grey lustrous metallic element that is highly resistant to corrosion; occurs in niobite and fergusonite and tantalite', NULL),
(42466, 'taurine', 1, '/ˈtɔː.riːn/', 'a colorless crystalline substance obtained from the bile of mammals', NULL),
(42467, 'taurine', 3, '/ˈtɔː.raɪn/', 'of or relating to or resembling a bull', NULL),
(42468, 'technetium', 1, '/tɛkˈniːʃ(i)əm/', 'a crystalline metallic element not found in nature; occurs as one of the fission products of uranium', NULL),
(42469, 'tellurium', 1, '/tɛˈl(j)ʊəriəm/', 'a brittle silver-white metalloid element that is related to selenium and sulfur; it is used in alloys and as a semiconductor; occurs mainly as tellurides in ores of copper and nickel and silver and gold', NULL),
(42470, 'terbium', 1, '/ˈtəːbiəm/', 'a metallic element of the rare earth group; used in lasers; occurs in apatite and monazite and xenotime and ytterbite', NULL),
(42471, 'thallium', 1, '/ˈθæl.i.əm/', 'a soft grey malleable metallic element that resembles tin but discolors on exposure to air; it is highly toxic and is used in rodent and insect poisons; occurs in zinc blende and some iron ores', NULL),
(42472, 'thorium', 1, '/ˈθɔːriəm/', 'a soft silvery-white tetravalent radioactive metallic element; isotope 232 is used as a power source in nuclear reactors; occurs in thorite and in monazite sands', NULL),
(42473, 'thulium', 1, '/ˈθjuːliəm/', 'a soft silvery metallic element of the rare earth group; isotope 170 emits X-rays and is used in small portable X-ray machines; it occurs in monazite and apatite and xenotime', NULL),
(42474, 'titanium', 1, '/tɪˈteɪ.ni.əm/', 'a light strong grey lustrous corrosion-resistant metallic element used in strong lightweight alloys (as for airplane parts); the main sources are rutile and ilmenite', NULL),
(42475, 'tungsten', 1, '/ˈtʌŋ.stən/', 'a heavy grey-white metallic element; the pure form is used mainly in electrical applications; it is found in several ores including wolframite and scheelite', NULL),
(42476, 'uranium', 1, '/jʊəˈreɪ.ni.əm/', 'a heavy toxic silvery-white radioactive metallic element; occurs in many isotopes; used for nuclear fuels and nuclear weapons', NULL),
(42477, 'vanadium', 1, '/vəˈneɪ.di.əm/', 'a soft silvery white toxic metallic element used in steel alloys; it occurs in several complex minerals including carnotite and vanadinite', NULL),
(42478, 'xenon', 1, '/ˈzen.ɒn/', 'a colorless odorless inert gaseous element occurring in the earth\'s atmosphere in trace amounts', NULL),
(42479, 'ytterbium', 1, '/ɪˈtɜːbɪəm/', 'a soft silvery metallic element; a rare earth of the lanthanide series; it occurs in gadolinite and monazite and xenotime', NULL),
(42480, 'yttrium', 1, '/ˈɪtriəm/', 'a silvery metallic element that is common in rare-earth minerals; used in magnesium and aluminum alloys', NULL),
(42481, 'zinc', 1, '/zɪŋk/', 'a bluish-white lustrous metallic element; brittle at ordinary temperatures but malleable when heated; used in a wide variety of alloys and in galvanizing iron; it occurs naturally as zinc sulphide in zinc blende', NULL),
(42482, 'zinc', 2, '/zɪŋk/', 'coat or cover with zinc', NULL),
(42483, 'zirconium', 1, '/zɜːˈkəʊ.ni.əm/', 'a lustrous grey strong metallic element resembling titanium; it is used in nuclear reactors as a neutron absorber; it occurs in baddeleyite but is obtained chiefly from zircon', NULL),
(42484, 'mineral', 1, '/ˈmɪn.ər.əl/', 'solid homogeneous inorganic substances occurring in nature having a definite chemical composition', NULL),
(42485, 'mineral', 3, '/ˈmɪn.ər.əl/', 'composed of matter other than plant or animal', '\"the inorganic mineral world\"'),
(42486, 'mineral', 3, '/ˈmɪn.ər.əl/', 'relating to minerals', '\"mineral elements\"; \"mineral deposits\"'),
(42487, 'amphibole', 1, '/ˈæmfɪbəʊl/', 'a mineral or mineral variety belonging to the amphibole group', NULL),
(42488, 'amphibolite', 1, '/æmˈfɪbəlaɪt/', 'a metamorphic rock composed chiefly of amphibole and plagioclase', NULL),
(42489, 'apatite', 1, '/ˈapətʌɪt/', 'a common complex mineral consisting of calcium fluoride phosphate or calcium chloride phosphate; a source of phosphorus', NULL),
(42490, 'aragonite', 1, '/ˈarəɡənʌɪt/', 'a mineral form of crystalline calcium carbonate; dimorphic with calcite', NULL),
(42491, 'argillite', 1, '/ˈɑːdʒɪlʌɪt/', 'a sedimentary rock differing from shale in being bound by silica and from slate in having no slate cleavages', NULL),
(42492, 'arsenopyrite', 1, '/ˌɑːsənə(ʊ)ˈpʌɪrʌɪt/', 'a silver-white or grey ore of arsenic', NULL),
(42493, 'asphalt', 1, '/ˈæs.fɔːlt/', 'a dark bituminous substance found in natural beds and as residue from petroleum distillation; consists mainly of hydrocarbons', NULL),
(42494, 'asphalt', 1, '/ˈæs.fɔːlt/', 'mixed asphalt and crushed gravel or sand; used especially for paving but also for roofing', NULL),
(42495, 'asphalt', 2, '/ˈæs.fɔːlt/', 'cover with tar or asphalt', '\"asphalt the driveway\"'),
(42496, 'augite', 1, '/ˈɔːdʒʌɪt/', 'dark-green to black glassy mineral of the pyroxene group containing large amounts of aluminum and iron and magnesium', NULL),
(42497, 'azurite', 1, '/ˈazjʊərʌɪt/', 'blue carbonate of copper; blue malachite', NULL),
(42498, 'bauxite', 1, '/ˈbɔːk.saɪt/', 'a clay-like mineral; the chief ore of aluminum; composed of aluminum oxides and aluminum hydroxides; used as an abrasive and catalyst', NULL),
(42499, 'beryl', 1, '/ˈbɛrɪl/', 'the chief source of beryllium; colored transparent varieties are valued as gems', NULL),
(42500, 'biotite', 1, '/ˈbʌɪətʌɪt/', 'dark brown to black mica found in igneous and metamorphic rock', NULL),
(42501, 'borax', 1, '/ˈbɔː.ræks/', 'an ore of boron consisting of hydrated sodium borate; used as a flux or cleansing agent', NULL),
(42502, 'bornite', 1, '/ˈbɔːnʌɪt/', 'a mineral consisting of sulfides of copper and iron that is found in copper deposits', NULL),
(42503, 'carnallite', 1, '/ˈkɑːnəlʌɪt/', 'a white or reddish mineral consisting of hydrous chlorides of potassium and magnesium; used as a fertilizer and as a source of potassium and magnesium', NULL),
(42504, 'caspase', 1, '/ˈkæspeɪz/', 'any of a group of proteases that mediate apoptosis', NULL),
(42505, 'cassiterite', 1, '/kəˈsɪtərʌɪt/', 'a hard heavy dark mineral that is the chief source of tin', NULL),
(42506, 'celestite', 1, '/ˈsɛləstʌɪt/', 'a mineral consisting of strontium sulphate', NULL),
(42507, 'cerussite', 1, '/ˈsɪərəsʌɪt/', 'a mineral consisting of lead carbonate that is an important source of lead', NULL),
(42508, 'chalcocite', 1, '/ˈkalkəsʌɪt/', 'a heavy grey mineral that is an ore of copper', NULL),
(42509, 'chalcopyrite', 1, '/ˌkalkəʊˈpʌɪrʌɪt/', 'a yellow copper ore (CuFeS2) made up of copper and iron sulfide', NULL),
(42510, 'chlorite', 1, '/ˈklɔːrʌɪt/', 'a generally green or black mineral; it occurs as a constituent of many rocks typically in the form of a flat crystal', NULL),
(42511, 'chromite', 1, '/ˈkrəʊmʌɪt/', 'a brownish-black mineral; the major source of chromium', NULL),
(42512, 'chrysoberyl', 1, '/ˈkrɪsəʊˌbɛrɪl/', 'a rare hard yellow green mineral consisting of beryllium aluminate in crystal form; used as a gemstone', NULL),
(42513, 'halite', 1, '/ˈhalʌɪt/', 'naturally occurring crystalline sodium chloride', NULL),
(42514, 'cordierite', 1, '/ˈkɔːdɪərʌɪt/', 'a blue mineral of magnesium and iron and aluminum and silicon and oxygen; often used as a gemstone', NULL);
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(42515, 'cristobalite', 1, '/krɪˈstəʊbəlʌɪt/', 'a white mineral consisting of silica; found in volcanic rocks', NULL),
(42516, 'cryolite', 1, '/ˈkraɪ.əʊ.laɪt/', 'a white mineral consisting of fluorides of aluminum and sodium; a source of fluorine', NULL),
(42517, 'dolomite', 1, '/ˈdɒləmʌɪt/', 'a light colored mineral consisting of calcium magnesium carbonate; a source of magnesium; used as a ceramic and as fertilizer', NULL),
(42518, 'dolomite', 1, '/ˈdɒləmʌɪt/', 'a kind of sedimentary rock resembling marble or limestone but rich in magnesium carbonate', NULL),
(42519, 'emery', 1, '/ˈem.ər.i/', 'a hard grey-black mineral consisting of corundum and either hematite or magnetite; used as an abrasive (especially as a coating on paper)', NULL),
(42520, 'emulsifier', 1, '/ɪˈmʌl.sɪ.faɪ.ər/', 'a surface-active agent that promotes the formation of an emulsion', NULL),
(42521, 'fluorapatite', 1, '/flʊəˈrapətʌɪt/', 'a form of apatite in which fluorine predominates over chlorine', NULL),
(42522, 'fluorite', 1, '/ˈflʊərʌɪt/', 'a soft mineral (calcium fluoride) that is fluorescent in ultraviolet light; chief source of fluorine', NULL),
(42523, 'galena', 1, '/ɡəˈliːnə/', 'soft blue-grey mineral; lead sulfide; a major source of lead', NULL),
