(45288, 'simplify', 2, '/ˈsɪmplɪfaɪ/', 'make simpler or easier or reduce in complexity or extent', '\"We had to simplify the instructions\"; \"this move will simplify our lives\"'),
(45289, 'oversimplify', 2, '/ˌoʊvərˈsɪmplɪfaɪ/', 'make too simple', '\"Don\'t oversimplify the instructions\"'),
(45290, 'oversimplify', 2, '/ˌoʊvərˈsɪmplɪfaɪ/', 'simplify to an excessive degree', '\"Don\'t oversimplify the problem\"'),
(45291, 'complicate', 2, '/ˈkɑːmplɪˌkeɪt/', 'make more complex, intricate, or richer', '\"refine a design or pattern\"'),
(45292, 'complicate', 2, '/ˈkɑːmplɪˌkeɪt/', 'make more complicated', '\"There was a new development that complicated the matter\"'),
(45293, 'involve', 2, '/ɪnˈvɒlv/', 'make complex or intricate or complicated', '\"The situation was rather involved\"'),
(45294, 'involve', 2, '/ɪnˈvɒlv/', 'occupy or engage the interest of', '\"His story completely involved me during the entire afternoon\"'),
(45295, 'involve', 2, '/ɪnˈvɒlv/', 'contain as a part', '\"Dinner at Joe\'s always involves at least six courses\"'),
(45296, 'involve', 2, '/ɪnˈvɒlv/', 'connect closely and often incriminatingly', '\"This new ruling affects your business\"'),
(45297, 'involve', 2, '/ɪnˈvɒlv/', 'engage as a participant', '\"Don\'t involve me in your family affairs!\"'),
(45298, 'refine', 2, '/rɪˈfaɪn/', 'make more precise or increase the discriminatory powers of', '\"refine a method of analysis\"; \"refine the constant in the equation\"'),
(45299, 'refine', 2, '/rɪˈfaɪn/', 'attenuate or reduce in vigor, strength, or validity by polishing or purifying', '\"many valuable nutrients are refined out of the foods in our modern diet\"'),
(45300, 'refine', 2, '/rɪˈfaɪn/', 'reduce to a fine, unmixed, or pure state; separate from extraneous matter or cleanse from impurities', '\"refine sugar\"'),
(45301, 'refine', 2, '/rɪˈfaɪn/', 'treat or prepare so as to put in a usable condition', '\"refine paper stock\"; \"refine pig iron\"; \"refine oil\"'),
(45302, 'pressurize', 2, '/ˈprɛʃəraɪz/', 'increase the pressure in or of', '\"The captain will pressurize the cabin for the passengers\' comfort\"'),
(45303, 'pressurize', 2, '/ˈprɛʃəraɪz/', 'maintain a certain pressure', '\"the airplane cabin is pressurized\"; \"pressurize a space suit\"'),
(45304, 'supercharge', 2, '/ˈsuːpəˌtʃɑːdʒ/', 'increase the pressure on a gas or liquid', NULL),
(45305, 'depressurize', 2, '/dɪˈprɛʃəraɪz/', 'decrease the pressure of', '\"depressurize the cabin in the air plane\"'),
(45306, 'restructure', 2, '/riˈstrʌktʃər/', 'construct or form anew or provide with a new structure', '\"After his accident, he had to restructure his life\"; \"The governing board was reconstituted\"'),
(45307, 'organize', 2, '/ˈɔːɡənaɪz/', 'bring order and organization to', '\"Can you help me organize my files?\"'),
(45308, 'organize', 2, '/ˈɔːɡənaɪz/', 'arrange by systematic planning and united effort', '\"machinate a plot\"; \"organize a strike\"; \"devise a plan to take over the director\'s office\"'),
(45309, 'organize', 2, '/ˈɔːɡənaɪz/', 'cause to be structured or ordered or operating according to some principle or idea', NULL),
(45310, 'centralize', 2, '/ˈsɛntrəˌlaɪz/', 'make central', '\"The Russian government centralized the distribution of food\"'),
(45311, 'decentralize', 2, '/ˈdiːˌsɛntrəˌlaɪz/', 'make less central', '\"After the revolution, food distribution was decentralized\"'),
(45312, 'socialize', 2, '/ˈsəʊʃəˌlaɪz/', 'make conform to socialist ideas and philosophies', '\"Health care should be socialized!\"'),
(45313, 'socialize', 2, '/ˈsəʊʃəˌlaɪz/', 'prepare for social life', '\"Children have to be socialized in school\"'),
(45314, 'socialize', 2, '/ˈsəʊʃəˌlaɪz/', 'train for a social environment', '\"The children must be properly socialized\"'),
(45315, 'socialize', 2, '/ˈsəʊʃəˌlaɪz/', 'take part in social activities; interact with others', '\"He never socializes with his colleagues\"; \"The old man hates to socialize\"'),
(45316, 'provide', 2, '/prəˈvaɪd/', 'take measures in preparation for', '\"provide for the proper care of the passengers on the cruise ship\"'),
(45317, 'provide', 2, '/prəˈvaɪd/', 'determine (what is to happen in certain contingencies), especially by including a proviso condition or stipulation', '\"The will provides that each child should receive half of the money\"; \"The Constitution provides for the right to free speech\"'),
(45318, 'provide', 2, '/prəˈvaɪd/', 'give what is desired or needed, especially support, food or sustenance', '\"The hostess provided lunch for all the guests\"'),
(45319, 'provide', 2, '/prəˈvaɪd/', 'supply means of subsistence; earn a living', '\"He provides for his large family by working three jobs\"; \"Women nowadays not only take care of the household but also bring home the bacon\"'),
(45320, 'cram', 2, '/kræm/', 'prepare (students) hastily for an impending exam', NULL),
(45321, 'cram', 2, '/kræm/', 'study intensively, as before an exam', '\"I had to bone up on my Latin verbs before the final exam\"'),
(45322, 'cram', 2, '/kræm/', 'put something somewhere so that the space is completely filled', '\"cram books into the suitcase\"'),
(45323, 'winterize', 2, '/ˈwɪntəˌraɪz/', 'prepare for winter', '\"winterize cars\"; \"winterize your houses\"'),
(45324, 'internationalize', 2, '/ˌɪntəˈnæʃənəlaɪz/', 'make international in character', '\"We internationalized the committee\"'),
(45325, 'internationalize', 2, '/ˌɪntəˈnæʃənəlaɪz/', 'put under international control', '\"internationalize trade of certain drugs\"'),
(45326, 'modernize', 2, '/ˈmɒdərnaɪz/', 'become technologically advanced', '\"Many countries in Asia are now developing at a very fast pace\"; \"Viet Nam is modernizing rapidly\"'),
(45327, 'civilize', 2, '/ˈsɪvɪlaɪz/', 'raise from a barbaric to a civilized state', '\"The wild child found wandering in the forest was gradually civilized\"'),
(45328, 'nationalize', 2, '/ˈnæʃənəlaɪz/', 'put under state control or ownership', '\"Mitterand nationalized the banks\"'),
(45329, 'nationalize', 2, '/ˈnæʃənəlaɪz/', 'make national in character or scope', '\"His heroic deeds were nationalized by the press\"'),
(45330, 'privatize', 2, '/ˈpraɪvətaɪz/', 'change from governmental to private control or ownership', '\"The oil industry was privatized\"'),
(45331, 'naturalize', 2, '/ˈnætʃərəlaɪz/', 'make into a citizen', '\"The French family was naturalized last year\"'),
(45332, 'naturalize', 2, '/ˈnætʃərəlaɪz/', 'make more natural or lifelike', NULL),
(45333, 'naturalize', 2, '/ˈnætʃərəlaɪz/', 'adopt to another place', '\"The stories had become naturalized into an American setting\"'),
(45334, 'naturalize', 2, '/ˈnætʃərəlaɪz/', 'explain with reference to nature', NULL),
(45335, 'adopt', 2, '/əˈdɒpt/', 'take into one\'s family', '\"They adopted two children from Nicaragua\"'),
(45336, 'adopt', 2, '/əˈdɒpt/', 'take up and practice as one\'s own', NULL),
(45337, 'adopt', 2, '/əˈdɒpt/', 'choose and follow; as of theories, ideas, policies, strategies or plans', '\"She followed the feminist movement\"; \"The candidate espouses Republican ideals\"'),
(45338, 'immigrate', 2, '/ˈɪmɪɡreɪt/', 'come into a new country and change residency', '\"Many people immigrated at the beginning of the 20th century\"'),
(45339, 'immigrate', 2, '/ˈɪmɪɡreɪt/', 'introduce or send as immigrants', '\"Britain immigrated many colonists to America\"'),
(45340, 'immigrate', 2, '/ˈɪmɪɡreɪt/', 'migrate to a new environment', '\"only few plants can immigrate to the island\"'),
(45341, 'colonize', 2, '/ˈkɒlənaɪz/', 'settle as colonists or establish a colony (in)', '\"The British colonized the East Coast\"'),
(45342, 'colonize', 2, '/ˈkɒlənaɪz/', 'settle as a colony; of countries in the developing world', '\"Europeans colonized Africa in the 17th century\"'),
(45343, 'relocate', 2, '/ˈriːləkeɪt/', 'move or establish in a new location', '\"We had to relocate the office because the rent was too high\"'),
(45344, 'relocate', 2, '/ˈriːləkeɪt/', 'become established in a new location', '\"Our company relocated to the Midwest\"');
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(45345, 'dislocate', 2, '/ˈdɪsləkeɪt/', 'put out of its usual place, position, or relationship', '\"The colonists displaced the natives\"'),
(45346, 'dislocate', 2, '/ˈdɪsləkeɪt/', 'move out of position', '\"dislocate joints\"; \"the artificial hip joint luxated and had to be put back surgically\"'),
(45347, 'resettle', 2, '/ˈrɛsɛtəl/', 'settle in a new place', '\"The immigrants had to resettle\"'),
(45348, 'emigrate', 2, '/ˈɛmɪɡreɪt/', 'leave one\'s country of residence for a new one', '\"Many people had to emigrate during the Nazi period\"'),
(45349, 'expatriate', 2, '/ɛksˈpætrɪət/', 'move away from one\'s native country and adopt a new residence abroad', NULL),
(45350, 'expatriate', 2, '/ɛksˈpætrɪət/', 'expel from a country', '\"The poet was exiled because he signed a letter protesting the government\'s actions\"'),
(45351, 'steady', 2, '/ˈstɛdi/', 'make steady', '\"steady yourself\"'),
(45352, 'steady', 3, '/ˈstɛdi/', 'not easily excited or upset', '\"steady nerves\"'),
(45353, 'steady', 3, '/ˈstɛdi/', 'securely in position; not shaky', '\"held the ladder steady\"'),
(45354, 'steady', 3, '/ˈstɛdi/', 'not subject to change or variation especially in behavior', '\"a steady beat\"; \"a steady job\"; \"a steady breeze\"; \"a steady increase\"; \"a good steady ballplayer\"'),
(45355, 'even', 2, '/ˈiːvən/', 'make even or more even', NULL),
(45356, 'even', 2, '/ˈiːvən/', 'become even or more even', '\"even out the surface\"'),
(45357, 'even', 3, '/ˈiːvən/', 'equal in degree or extent or amount; or equally matched or balanced', '\"even amounts of butter and sugar\"; \"on even terms\"; \"it was a fifty-fifty (or even) split\"; \"had a fifty-fifty (or even) chance\"; \"an even fight\"'),
(45358, 'even', 3, '/ˈiːvən/', 'being level or straight or regular and without variation as e.g. in shape or texture; or being in the same plane or at the same height as something else (i.e. even with)', '\"an even application of varnish\"; \"an even floor\"; \"the road was not very even\"; \"the picture is even with the window\"'),
(45359, 'even', 3, '/ˈiːvən/', 'divisible by two', NULL),
(45360, 'even', 3, '/ˈiːvən/', 'occurring at fixed intervals', '\"a regular beat\"; \"the even rhythm of his breathing\"'),
(45361, 'even', 3, '/ˈiːvən/', 'symmetrically arranged', '\"even features\"; \"regular features\"; \"a regular polygon\"'),
(45362, 'even', 4, '/ˈiːvən/', 'used as an intensive especially to indicate something unexpected', '\"even an idiot knows that\"; \"declined even to consider the idea\"; \"I don\'t have even a dollar!\"'),
(45363, 'even', 4, '/ˈiːvən/', 'to a greater degree or extent; used with comparisons', '\"looked sick and felt even worse\"; \"an even (or still) more interesting problem\"; \"still another problem must be solved\"; \"a yet sadder tale\"'),
(45364, 'even', 4, '/ˈiːvən/', 'in spite of; notwithstanding', '\"even when he is sick, he works\"; \"even with his head start she caught up with him\"'),
(45365, 'even', 4, '/ˈiːvən/', 'to the full extent', '\"loyal even unto death\"'),
(45366, 'equal', 2, '/ˈiːkwəl/', 'make equal, uniform, corresponding, or matching', '\"let\'s equalize the duties among all employees in this office\"; \"The company matched the discount policy of its competitors\"'),
(45367, 'equal', 2, '/ˈiːkwəl/', 'be identical or equivalent to', '\"One dollar equals 1,000 rubles these days!\"'),
(45368, 'equal', 2, '/ˈiːkwəl/', 'be equal to in quality or ability', '\"Nothing can rival cotton for durability\"; \"Your performance doesn\'t even touch that of your colleagues\"; \"Her persistence and ambition only matches that of her parents\"'),
(45369, 'equal', 3, '/ˈiːkwəl/', 'having the same quantity, value, or measure as another', '\"on equal terms\"; \"all men are equal before the law\"'),
(45370, 'stiffen', 2, '/ˈstɪfən/', 'make stiff or stiffer', '\"Stiffen the cream by adding gelatine\"'),
(45371, 'stiffen', 2, '/ˈstɪfən/', 'become stiff or stiffer', '\"He stiffened when he saw his boss enter the room\"'),
(45372, 'stiffen', 2, '/ˈstɪfən/', 'restrict', '\"Tighten the rules\"; \"stiffen the regulations\"'),
(45373, 'loosen', 2, '/ˈluːsən/', 'become loose or looser or less tight', '\"The noose loosened\"; \"the rope relaxed\"'),
(45374, 'loosen', 2, '/ˈluːsən/', 'make loose or looser', '\"loosen the tension on a rope\"'),
(45375, 'loosen', 2, '/ˈluːsən/', 'make less dense', '\"loosen the soil\"'),
(45376, 'tighten', 2, '/ˈtaɪtən/', 'become tight or tighter', '\"The rope tightened\"'),
(45377, 'tighten', 2, '/ˈtaɪtən/', 'make tight or tighter', '\"Tighten the wire\"'),
(45378, 'frap', 2, '/fræp/', 'take up the slack of', '\"frap a rope\"'),
(45379, 'frap', 2, '/fræp/', 'make secure by lashing', '\"frap a sail\"'),
(45380, 'slacken', 2, '/ˈslækən/', 'make slack as by lessening tension or firmness', NULL),
(45381, 'slacken', 2, '/ˈslækən/', 'become looser or slack', '\"the rope slackened\"'),
(45382, 'douse', 2, '/daʊs/', 'slacken', '\"douse a rope\"'),
(45383, 'douse', 2, '/daʊs/', 'lower quickly', '\"douse a sail\"'),
(45384, 'douse', 2, '/daʊs/', 'wet thoroughly', NULL),
(45385, 'douse', 2, '/daʊs/', 'put out, as of a candle or a light', '\"Douse the lights\"'),
(45386, 'absent', 2, '/ˈæbsənt/', 'go away or leave', '\"He absented himself\"'),
(45387, 'absent', 3, '/ˈæbsənt/', 'lost in thought; showing preoccupation', '\"an absent stare\"; \"an absentminded professor\"; \"the scatty glancing quality of a hyperactive but unfocused intelligence\"'),
(45388, 'absent', 3, '/ˈæbsənt/', 'not being in a specified place', NULL),
(45389, 'evanesce', 2, '/ɪˈvænɛs/', 'disappear gradually', '\"The pain eventually passed off\"'),
(45390, 'appear', 2, '/əˈpɪə/', 'come into sight or view', '\"He suddenly appeared at the wedding\"; \"A new star appeared on the horizon\"'),
(45391, 'appear', 2, '/əˈpɪə/', 'come into being or existence, or appear on the scene', '\"Then the computer came along and changed our lives\"; \"Homo sapiens appeared millions of years ago\"'),
(45392, 'appear', 2, '/əˈpɪə/', 'be issued or published', '\"Did your latest book appear yet?\"; \"The new Woody Allen film hasn\'t come out yet\"'),
(45393, 'appear', 2, '/əˈpɪə/', 'appear as a character on stage or appear in a play, etc.', '\"Gielgud appears briefly in this movie\"; \"She appeared in `Hamlet\' on the London stage\"'),
(45394, 'appear', 2, '/əˈpɪə/', 'seem to be true, probable, or apparent', '\"It seems that he is very gifted\"; \"It appears that the weather in California is very bad\"'),
(45395, 'appear', 2, '/əˈpɪə/', 'present oneself formally, as before a (judicial) authority', '\"He had to appear in court last month\"; \"She appeared on several charges of theft\"'),
(45396, 'peep', 2, '/piːp/', 'appear as though from hiding', '\"the new moon peeped through the tree tops\"'),
(45397, 'peep', 2, '/piːp/', 'speak in a hesitant and high-pitched tone of voice', NULL),
(45398, 'peep', 2, '/piːp/', 'make high-pitched sounds', '\"the birds were chirping in the bushes\"'),
(45399, 'peep', 2, '/piːp/', 'cause to appear', '\"he peeped his head through the window\"'),
(45400, 'peep', 2, '/piːp/', 'look furtively', '\"He peeped at the woman through the window\"'),
(45401, 'emerge', 2, '/ɪˈmɜːdʒ/', 'come out into view, as from concealment', '\"Suddenly, the proprietor emerged from his office\"'),
(45402, 'emerge', 2, '/ɪˈmɜːdʒ/', 'become known or apparent', '\"Some nice results emerged from the study\"'),
(45403, 'emerge', 2, '/ɪˈmɜːdʒ/', 'come up to the surface of or rise', '\"He felt new emotions emerge\"'),
(45404, 'resurface', 2, '/ˌriːˈsɜːfɪs/', 'appear again', '\"The missing man suddenly resurfaced in New York\"'),
(45405, 'resurface', 2, '/ˌriːˈsɜːfɪs/', 'cover with a new surface', NULL),
(45406, 'resurface', 2, '/ˌriːˈsɜːfɪs/', 'reappear on the surface', NULL),
(45407, 'reappear', 2, '/ˌriːˈæpɪə/', 'appear again', '\"The sores reappeared on her body\"; \"Her husband reappeared after having left her years ago\"'),
(45408, 'disappear', 2, '/ˌdɪsəˈpɪə/', 'get lost, as without warning or explanation', '\"He disappeared without a trace\"'),
(45409, 'minimize', 2, '/ˈmɪnɪˌmaɪz/', 'make small or insignificant', '\"Let\'s minimize the risk\"'),
(45410, 'minimize', 2, '/ˈmɪnɪˌmaɪz/', 'cause to seem less serious; play down', '\"Don\'t belittle his influence\"'),
(45411, 'maximize', 2, '/ˈmæksɪˌmaɪz/', 'make as big or large as possible', '\"Maximize your profits!\"'),
(45412, 'maximize', 2, '/ˈmæksɪˌmaɪz/', 'make the most of', '\"He maximized his role\"'),
(45413, 'retrench', 2, '/rɪˈtrɛntʃ/', 'make a reduction, as in one\'s workforce', '\"The company had to retrench\"'),
(45414, 'retrench', 2, '/rɪˈtrɛntʃ/', 'tighten one\'s belt; use resources carefully', NULL),
(45415, 'thin', 2, '/θɪn/', 'make thin or thinner', '\"Thin the solution\"'),
(45416, 'thin', 2, '/θɪn/', 'lose thickness; become thin or thinner', NULL),
(45417, 'thin', 3, '/θɪn/', 'lacking excess flesh; \"Yon Cassius has a lean and hungry look\"-Shakespeare', '\"you can\'t be too rich or too thin\"'),
(45418, 'thin', 3, '/θɪn/', '(of sound) lacking resonance or volume', '\"a thin feeble cry\"'),
(45419, 'thin', 3, '/θɪn/', 'lacking spirit or sincere effort', '\"a thin smile\"'),
(45420, 'thin', 3, '/θɪn/', 'of relatively small extent from one surface to the opposite or in cross section', '\"thin wire\"; \"a thin chiffon blouse\"; \"a thin book\"; \"a thin layer of paint\"'),
(45421, 'thin', 3, '/θɪn/', 'relatively thin in consistency or low in density; not viscous', '\"air is thin at high altitudes\"; \"a thin soup\"; \"skimmed milk is much thinner than whole milk\"; \"thin oil\"'),
(45422, 'thicken', 2, '/ˈθɪkən/', 'become thick or thicker', '\"The sauce thickened\"; \"The egg yolk will inspissate\"'),
(45423, 'thicken', 2, '/ˈθɪkən/', 'make thick or thicker', '\"Thicken the sauce\"; \"inspissate the tar so that it becomes pitch\"'),
(45424, 'thicken', 2, '/ˈθɪkən/', 'make viscous or dense', '\"thicken the sauce by adding flour\"'),
(45425, 'heighten', 2, '/ˈhaɪtən/', 'make more extreme; raise in quantity, degree, or intensity', '\"heightened interest\"'),
(45426, 'heighten', 2, '/ˈhaɪtən/', 'become more extreme', '\"The tension heightened\"'),
(45427, 'heighten', 2, '/ˈhaɪtən/', 'increase the height of', '\"The athletes kept jumping over the steadily heightened bars\"'),
(45428, 'full', 2, '/fʊl/', 'make (a garment) fuller by pleating or gathering', NULL),
(45429, 'full', 2, '/fʊl/', 'beat for the purpose of cleaning and thickening', '\"full the cloth\"'),
(45430, 'full', 3, '/fʊl/', 'having the normally expected amount', '\"gives full measure\"; \"gives good measure\"; \"a good mile from here\"'),
(45431, 'full', 3, '/fʊl/', 'complete in extent or degree and in every particular', '\"a full game\"; \"a total eclipse\"; \"a total disaster\"'),
(45432, 'full', 3, '/fʊl/', 'containing as much or as many as is possible or normal', '\"a full glass\"; \"a sky full of stars\"; \"a full life\"; \"the auditorium was full to overflowing\"'),
(45433, 'full', 3, '/fʊl/', '(of sound) having marked deepness and body', '\"full tones\"; \"a full voice\"'),
(45434, 'full', 3, '/fʊl/', 'filled to satisfaction with food or drink', '\"a full stomach\"'),
(45435, 'wane', 2, '/weɪn/', 'decrease in phase', '\"the moon is waning\"'),
(45436, 'wane', 2, '/weɪn/', 'become smaller', '\"Interest in his novels waned\"'),
(45437, 'magnify', 2, '/ˈmæɡnɪˌfaɪ/', 'increase in size, volume or significance', '\"Her terror was magnified in her mind\"'),
(45438, 'unfurl', 2, '/ʌnˈfɜːl/', 'unroll, unfold, or spread out or be unrolled, unfolded, or spread out from a furled state', '\"unfurl a banner\"'),
(45439, 'diversify', 2, '/daɪˈvɜːsɪfaɪ/', 'vary in order to spread risk or to expand', '\"The company diversified\"'),
(45440, 'diversify', 2, '/daɪˈvɜːsɪfaɪ/', 'spread into new habitats and produce variety or variegate', '\"The plants on this island diversified\"'),
(45441, 'diversify', 2, '/daɪˈvɜːsɪfaɪ/', 'make (more) diverse', '\"diversify a course of study\"'),
(45442, 'vary', 2, '/ˈveəɹɪ/', 'make something more diverse and varied', '\"Vary the menu\"'),
(45443, 'vary', 2, '/ˈveəɹɪ/', 'be subject to change in accordance with a variable', '\"Prices vary\"; \"His moods vary depending on the weather\"'),
(45444, 'specialize', 2, '/ˈspɛʃəlaɪz/', 'become more focus on an area of activity or field of study', '\"She specializes in Near Eastern history\"'),
(45445, 'specialize', 2, '/ˈspɛʃəlaɪz/', 'suit to a special purpose', '\"specialize one\'s research\"; \"this kind of beak has become specialized in certain Galapagos finches\"'),
(45446, 'specialize', 2, '/ˈspɛʃəlaɪz/', 'devote oneself to a special area of work', '\"She specializes in honey bees\"; \"This baker specializes in French bread\"'),
(45447, 'accelerate', 2, '/əkˈsɛləreɪt/', 'move faster', '\"The car accelerated\"'),
(45448, 'accelerate', 2, '/əkˈsɛləreɪt/', 'cause to move faster', '\"He accelerated the car\"'),
(45449, 'decelerate', 2, '/dɪˈsɛləreɪt/', 'reduce the speed of', '\"He slowed down the car\"'),
(45450, 'decelerate', 2, '/dɪˈsɛləreɪt/', 'lose velocity; move more slowly', '\"The car decelerated\"'),
(45453, 'fishtail', 2, '/ˈfɪʃteɪl/', 'slow down by moving the tail sideways', '\"The airplane fishtailed on the runway\"'),
(45454, 'slow', 2, '/sləʊ/', 'become slow or slower', '\"Production slowed\"'),
(45455, 'slow', 2, '/sləʊ/', 'cause to proceed more slowly', '\"The illness slowed him down\"'),
