INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(47848, 'prepare', 2, '/prɪˈpeə/', 'to prepare verbally, either for written or spoken delivery', '\"prepare a report\"; \"prepare a speech\"'),
