(47850, 'prepare', 2, '/prɪˈpeə/', 'educate for a future role or function', '\"He is grooming his son to become his successor\"; \"The prince was prepared to become King one day\"; \"They trained him to be a warrior\"'),
(47851, 'busk', 2, '/bʌsk/', 'play music in a public place and solicit money for it', '\"three young men were busking in the plaza\"'),
(47852, 'arouse', 2, '/əˈraʊz/', 'call forth (emotions, feelings, and responses)', '\"arouse pity\"; \"raise a smile\"; \"evoke sympathy\"'),
