(48285, 'attend', 2, '/əˈtɛnd/', 'give heed (to)', '\"The children in the audience attended the recital quietly\"; \"She hung on his every word\"; \"They attended to everything he said\"'),
(48286, 'attend', 2, '/əˈtɛnd/', 'take charge of or deal with', '\"Could you see about lunch?\"; \"I must attend to this matter\"; \"She took care of this business\"'),
(48287, 'attend', 2, '/əˈtɛnd/', 'be present at (meetings, church services, university), etc.', '\"She attends class regularly\"; \"I rarely attend services at my church\"; \"did you go to the meeting?\"');
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
