(48630, 'victimize', 2, '/ˈvɪktəˌmaɪz/', 'punish unjustly', NULL),
(48631, 'victimize', 2, '/ˈvɪktəˌmaɪz/', 'deprive of by deceit', '\"He swindled me out of my inheritance\"; \"She defrauded the customers who trusted her\"; \"the cashier gypped me when he gave me too little change\"'),
