(48648, 'skimp', 2, '/skɪmp/', 'work hastily or carelessly; deal with inadequately and superficially', NULL),
(48649, 'mistreat', 2, '/ˈmɪsˌtrit/', 'treat badly', '\"This boss abuses his workers\"; \"She is always stepping on others to get ahead\"'),
(48650, 'misbehave', 2, '/ˈmɪsˌbɪheɪv/', 'behave badly', '\"The children misbehaved all morning\"'),
(48651, 'condescend', 2, '/ˌkɒndɪˈsɛnd/', 'debase oneself morally, act in an undignified, unworthy, or dishonorable way', '\"I won\'t stoop to reading other people\'s mail\"'),
(48652, 'condescend', 2, '/ˌkɒndɪˈsɛnd/', 'do something that one considers to be below one\'s dignity', NULL),
(48653, 'condescend', 2, '/ˌkɒndɪˈsɛnd/', 'behave in a patronizing and condescending manner', NULL),
(48654, 'behave', 2, '/bɪˈheɪv/', 'behave in a certain manner', '\"She carried herself well\"; \"he bore himself with dignity\"; \"They conducted themselves well during these difficult times\"'),
(48655, 'behave', 2, '/bɪˈheɪv/', 'behave well or properly', '\"The children must learn to behave\"'),
