INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(48692, 'exempt', 3, '/ɪɡˈzɛmpt/', '(of persons) freed from or not subject to an obligation or liability (as e.g. taxes) to which others or other things are subject', '\"a beauty somehow exempt from the aging process\"; \"exempt from jury duty\"; \"only the very poorest citizens should be exempt from income taxes\"'),
(48695, 'overdo', 2, '/əʊvərˈduː/', 'do something to an excessive degree', '\"He overdid it last night when he did 100 pushups\"'),
(48697, 'impinge', 2, '/ɪmˈpɪndʒ/', 'impinge or infringe upon', '\"This impinges on my rights as an individual\"; \"This matter entrenches on other domains\"'),
(48698, 'pamper', 2, '/ˈpæmpə/', 'treat with excessive indulgence', '\"grandparents often pamper the children\"; \"Let\'s not mollycoddle our students!\"'),
(48699, 'burglarize', 2, '/ˈbɜːɡləraɪz/', 'commit a burglary; enter and rob a dwelling', NULL),
