(48716, 'pal', 2, '/pæl/', 'become friends; act friendly towards', NULL),
(48717, 'decolonize', 2, '/ˌdiːˈkɒlənaɪz/', 'grant independence to (a former colony)', '\"West Africa was decolonized in the early 1960\'s\"'),
