(48719, 'emcee', 2, '/ˈɛmˌsiː/', 'act as a master of ceremonies', NULL),
(48721, 'mingle', 2, '/ˈmɪŋɡəl/', 'get involved or mixed-up with', '\"He was about to mingle in an unpleasant affair\"'),
