(48723, 'exist', 2, '/ɪɡˈzɪst/', 'support oneself', '\"he could barely exist on such a low wage\"; \"Can you live on $2000 a month in New York City?\"; \"Many people in the world have to subsist on $1 a day\"'),
(48724, 'coexist', 2, '/ˌkəʊɪɡˈzɪst/', 'exist together', NULL),
