(48732, 'live', 3, '/lɪv/', 'abounding with life and energy', '\"the club members are a really live bunch\"'),
(48733, 'live', 3, '/lɪv/', 'actually being performed at the time of hearing or viewing', '\"a live television program\"; \"brought to you live from Lincoln Center\"; \"live entertainment involves performers actually in the physical presence of a live audience\"'),
(48734, 'live', 3, '/lɪv/', 'charged with an explosive', '\"live ammunition\"; \"a live bomb\"'),
