(48737, 'buccaneer', 2, '/ˈbʌkəˌnɪə/', 'live like a buccaneer', NULL),
(48738, 'survive', 2, '/səˈvaɪv/', 'continue to live through hardship or adversity', '\"We went without water and food for 3 days\"; \"These superstitions survive in the backwaters of America\"; \"The race car driver lived through several very serious accidents\"; \"how long can a person last without food and water?\"'),
