(48742, 'succumb', 2, '/səˈkʌm/', 'be fatally overwhelmed', NULL),
(48743, 'constitute', 2, '/ˈkɒnˌstɪtjuːt/', 'form or compose', '\"This money is my only income\"; \"The stone wall was the backdrop for the performance\"; \"These constitute my entire belonging\"; \"The children made up the chorus\"; \"This sum represents my entire income for a year\"; \"These few men comprise his entire army\"'),
(48744, 'resurge', 2, '/rɪˈsɜːdʒ/', 'rise again', '\"His need for a meal resurged\"; \"The candidate resurged after leaving politics for several years\"'),
