(48747, 'nucleate', 2, '/ˈnjuːklɪeɪt/', 'form into a nucleus', '\"Some cells had nucleated\"'),
(48748, 'necessitate', 2, '/nɪˈsɛsɪteɪt/', 'require as useful, just, or proper', '\"It takes nerve to do what she did\"; \"success usually requires hard work\"; \"This job asks a lot of patience and skill\"; \"This position demands a lot of personal sacrifice\"; \"This dinner calls for a spectacular dessert\"; \"This intervention does not postulate a patient\'s consent\"'),
(48749, 'necessitate', 2, '/nɪˈsɛsɪteɪt/', 'cause to be a concomitant', NULL),
(48750, 'obviate', 2, '/ˈɒbviˌeɪt/', 'do away with', NULL),
(48751, 'preclude', 2, '/prɪˈkluːd/', 'make impossible, especially beforehand', NULL),
(48752, 'possess', 2, '/pəˈzɛs/', 'have as an attribute, knowledge, or skill', '\"he possesses great knowledge about the Middle East\"'),
(48753, 'possess', 2, '/pəˈzɛs/', 'enter into and control, as of emotions or ideas', '\"What possessed you to buy this house?\"; \"A terrible rage possessed her\"'),
(48754, 'consist', 2, '/kənˈsɪst/', 'be composed of', '\"The land he conquered comprised several provinces\"; \"What does this dish consist of?\"'),
(48755, 'consist', 2, '/kənˈsɪst/', 'be consistent in form, tenor, or character; be congruous', '\"Desires are to be satisfied only so far as consists with an approved end\"'),
(48756, 'consist', 2, '/kənˈsɪst/', 'have its essential character; be comprised or contained in; be embodied in', '\"The payment consists in food\"; \"What does love consist in?\"'),
(48757, 'equate', 2, '/ɪˈkweɪt/', 'be equivalent or parallel, in mathematics', NULL),
(48758, 'incriminate', 2, '/ɪnˈkrɪmɪneɪt/', 'suggest that someone is guilty', NULL),
(48759, 'bide', 2, '/baɪd/', 'dwell', '\"You can stay with me while you are in town\"; \"stay a bit longer--the day is still young\"'),
(48760, 'overstay', 2, '/əʊvəˈsteɪ/', 'stay too long', '\"overstay or outstay one\'s welcome\"'),
(48761, 'remain', 2, '/rɪˈmeɪn/', 'be left; of persons, questions, problems, results, evidence, etc.', '\"There remains the question of who pulled the trigger\"; \"Carter remains the only President in recent history under whose Presidency the U.S. did not fight a war\"'),
(48762, 'loiter', 2, '/ˈlɔɪtə/', 'be about', '\"The high school students like to loiter in the Central Square\"; \"Who is this man that is hanging around the department?\"'),
(48763, 'bum', 2, '/bʌm/', 'be lazy or idle', '\"Her son is just bumming around all day\"'),
