(48765, 'lurk', 2, '/lɜːk/', 'lie in wait, lie in ambush, behave in a sneaky and secretive manner', NULL),
(48766, 'hesitate', 2, '/ˈhɛzɪteɪt/', 'pause or hold back in uncertainty or unwillingness', '\"Authorities hesitate to quote exact figures\"'),
