(48784, 'wrangle', 2, '/ˈræŋɡəl/', 'herd and care for', '\"wrangle horses\"'),
(48785, 'dwell', 2, '/dwɛl/', 'originate (in)', '\"The problems dwell in the social injustices in this country\"'),
(48786, 'dwell', 2, '/dwɛl/', 'exist or be situated within', '\"Strange notions inhabited her mind\"'),
(48787, 'inhere', 2, '/ɪnˈhɪə/', 'be inherent in something', NULL),
