INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(49060, 'avaricious', 3, '/ˌævəˈrɪʃəs/', 'immoderately desirous of acquiring e.g. wealth', '\"they are avaricious and will do anything for money\"; \"casting covetous eyes on his neighbor\'s fields\"; \"a grasping old miser\"; \"grasping commercialism\"; \"greedy for money and power\"; \"grew richer and greedier\"; \"prehensile employers stingy with raises for their employees\"'),
