(50398, 'conducive', 3, '/kənˈdʒuː.sɪv/', 'tending to bring about; being partly responsible for', '\"working conditions are not conducive to productivity\"; \"the seaport was a contributing factor in the growth of the city\"; \"a contributory factor\"'),
(50399, 'inductive', 3, '/ɪnˈdʌk.tɪv/', 'inducing or influencing; leading on; \"inductive to the sin of Eve\"- John Milton', NULL),
(50400, 'inductive', 3, '/ɪnˈdʌk.tɪv/', 'of reasoning; proceeding from particular facts to a general conclusion', '\"inductive reasoning\"'),
