(50429, 'nuclear', 3, '/ˈnjuː.klɪər/', 'constituting or like a nucleus', '\"annexation of the suburban fringe by the nuclear metropolis\"; \"the nuclear core of the congregation\"'),
(50430, 'nuclear', 3, '/ˈnjuː.klɪər/', '(weapons) deriving destructive energy from the release of atomic energy', '\"nuclear war\"; \"nuclear weapons\"; \"atomic bombs\"'),
(50431, 'nuclear', 3, '/ˈnjuː.klɪər/', 'of or relating to or constituting the nucleus of an atom', '\"nuclear physics\"; \"nuclear fission\"; \"nuclear forces\"'),
