(50444, 'definite', 3, '/ˈdef.ɪ.nət/', 'known for certain', '\"it is definite that they have won\"'),
(50445, 'definite', 3, '/ˈdef.ɪ.nət/', 'precise; explicit and clearly defined', '\"I want a definite answer\"; \"a definite statement of the terms of the will\"; \"a definite amount\"; \"definite restrictions on the sale of alcohol\"; \"the wedding date is now definite\"; \"a definite drop in attendance\"'),
(50446, 'indisputable', 3, '/ɪnˈdɪs.pjʊ.tə.bəl/', 'impossible to doubt or dispute', '\"indisputable (or sure) proof\"'),
(50447, 'indefinite', 3, '/ɪnˈdef.ɪ.nət/', 'not decided or not known', '\"were indefinite about their plans\"; \"plans are indefinite\"'),
(50448, 'indefinite', 3, '/ɪnˈdef.ɪ.nət/', 'vague or not clearly defined or stated', '\"must you be so indefinite?\"; \"amorphous blots of color having vague and indefinite edges\"; \"he would not answer so indefinite a proposal\"'),
(50449, 'ambivalent', 3, '/æmˈbɪv.ə.lənt/', 'uncertain or unable to decide about what course to follow', '\"was ambivalent about having children\"'),
(50450, 'doubtful', 3, '/ˈdaʊt.fəl/', 'fraught with uncertainty or doubt', '\"they were doubtful that the cord would hold\"; \"it was doubtful whether she would be admitted\"; \"dubious about agreeing to go\"'),
(50451, 'doubtful', 3, '/ˈdaʊt.fəl/', 'open to doubt or suspicion; \"it was more than dubitable whether the friend was as influential as she thought\"- Karen Horney', '\"the candidate\'s doubtful past\"; \"he has a dubious record indeed\"; \"what one found uncertain the other found dubious or downright false\"'),
(50452, 'doubtful', 3, '/ˈdaʊt.fəl/', 'unsettled in mind or opinion', '\"drew a few tentative conclusions\"'),
