(50463, 'foreordained', 3, '/ˌfɔː.rɔːˈdeɪnd/', 'established or prearranged unalterably', '\"his place in history was foreordained\"; \"a sense of predestinate inevitability about it\"; \"it seemed predestined since the beginning of the world\"'),
(50464, 'chancy', 3, '/ˈtʃɑːn.si/', 'subject to accident or chance or change', '\"a chancy appeal at best\"; \"getting that job was definitely fluky\"; \"a fluky wind\"; \"an iffy proposition\"'),
