(50479, 'unpreventable', 3, '/ˌʌn.prɪˈven.tə.bəl/', 'not preventable', '\"unpreventable hysteria\"'),
(50480, 'changeable', 3, '/ˈtʃeɪn.dʒə.bəl/', 'such that alteration is possible; having a marked tendency to change', '\"changeable behavior\"; \"changeable moods\"; \"changeable prices\"'),
(50481, 'changeable', 3, '/ˈtʃeɪn.dʒə.bəl/', 'varying in color when seen in different lights or from different angles', '\"changeable taffeta\"; \"chatoyant (or shot) silk\"; \"a dragonfly hovered, vibrating and iridescent\"'),
