(50484, 'adjustable', 3, '/əˈdʒʌs.tə.bəl/', 'capable of being changed so as to match or fit', '\"adjustable seat belts\"'),
(50485, 'astatic', 3, '/eɪˈstæt.ɪk/', 'not static or stable', NULL),
(50486, 'checkered', 3, '/ˈtʃek.əd/', 'marked by changeable fortune', '\"a checkered business career\"'),
(50487, 'erratic', 3, '/ɪˈræt.ɪk/', 'liable to sudden unpredictable change', '\"erratic behavior\"; \"fickle weather\"; \"mercurial twists of temperament\"; \"a quicksilver character, cool and willful at one moment, utterly fragile the next\"'),
(50488, 'erratic', 3, '/ɪˈræt.ɪk/', 'likely to perform unpredictably; \"a temperamental motor; sometimes it would start and sometimes it wouldn\'t\"; \"that beautiful but temperamental instrument the flute\"- Osbert Lancaster', '\"erratic winds are the bane of a sailor\"'),
(50489, 'erratic', 3, '/ɪˈræt.ɪk/', 'having no fixed course', '\"an erratic comet\"; \"his life followed a wandering course\"; \"a planetary vagabond\"'),
(50490, 'jittering', 3, '/ˈdʒɪt.ər.ɪŋ/', 'undergoing small rapid variations', NULL),
(50491, 'kaleidoscopic', 3, '/kəˌlaɪ.dəˈskɒp.ɪk/', 'continually shifting or rapidly changing', NULL),
(50492, 'unchangeable', 3, '/ʌnˈtʃeɪn.dʒə.bəl/', 'not changeable or subject to change; \"a fixed and unchangeable part of the germ plasm\"-Ashley Montagu', '\"the unchangeable seasons\"; \"one of the unchangeable facts of life\"'),
(50493, 'changeless', 3, '/ˈtʃeɪndʒ.ləs/', 'remaining the same for indefinitely long times', NULL),
(50494, 'changeless', 3, '/ˈtʃeɪndʒ.ləs/', 'unvarying in nature', '\"maintained a constant temperature\"; \"principles of unvarying validity\"'),
(50495, 'confirmed', 3, '/kənˈfɜːmd/', 'of persons; not subject to change', '\"a confirmed bachelor\"; \"a confirmed invalid\"'),
