(51410, 'alternative', 3, '/ɔːlˈtɜː.nə.tɪv/', 'necessitating a choice between mutually exclusive possibilities', '\"alternative possibilities were neutrality or war\"'),
(51411, 'alternative', 3, '/ɔːlˈtɜː.nə.tɪv/', 'pertaining to unconventional choices', '\"an alternative life style\"'),
(51412, 'contrastive', 3, '/kənˈtræs.tɪv/', 'syntactically establishing a relation of contrast between sentences or elements of a sentence', '\"disjunctive conjunctions like `but\', `or\', or `though\' serve a contrastive function\"'),
(51413, 'contrastive', 3, '/kənˈtræs.tɪv/', 'of words so related that one contrasts with the other', '\"`rich\' and `hard-up\' are contrastive terms\"'),
(51414, 'conjunct', 3, '/kənˈdʒʌŋkt/', 'progressing melodically by intervals of a second', '\"conjunct motion of an ascending scale\"'),
(51415, 'conjunct', 3, '/kənˈdʒʌŋkt/', 'bound in close association', '\"conjunct influences\"; \"conjunct ideas\"'),
(51416, 'disjunct', 3, '/dɪsˈdʒʌŋkt/', 'progressing melodically by intervals larger than a major second', NULL),
(51417, 'disjunct', 3, '/dɪsˈdʒʌŋkt/', 'used of distributions, as of statistical or natural populations', '\"disjunct distribution of king crabs\"'),
(51418, 'disjunct', 3, '/dɪsˈdʒʌŋkt/', 'marked by separation of or from usually contiguous elements; \"little isolated worlds, as abruptly disjunct and unexpected as a palm-shaded well in the Sahara\"- Scientific Monthly', NULL),
(51419, 'disjunct', 3, '/dɪsˈdʒʌŋkt/', 'having deep constrictions separating head, thorax, and abdomen, as in insects', NULL),
(51420, 'connected', 3, '/kəˈnek.tɪd/', 'joined or linked together', NULL),
