(51439, 'conscious', 3, '/ˈkɒn.ʃəs/', 'knowing and perceiving; having awareness of surroundings and sensations and thoughts', '\"remained conscious during the operation\"; \"conscious of his faults\"; \"became conscious that he was being followed\"'),
(51440, 'conscious', 3, '/ˈkɒn.ʃəs/', 'intentionally conceived', '\"a conscious effort to speak more slowly\"; \"a conscious policy\"'),
