(51449, 'consecrated', 3, '/ˈkɒn.sɪ.kreɪ.tɪd/', 'solemnly dedicated to or set apart for a high purpose', '\"a life consecrated to science\"; \"the consecrated chapel\"; \"a chapel dedicated to the dead of World War II\"'),
(51450, 'consecrated', 3, '/ˈkɒn.sɪ.kreɪ.tɪd/', 'made or declared or believed to be holy; devoted to a deity or some religious ceremony or use', '\"a consecrated church\"; \"the sacred mosque\"; \"sacred elephants\"; \"sacred bread and wine\"; \"sanctified wine\"'),
(51451, 'ordained', 3, '/ɔːˈdeɪnd/', 'invested with ministerial or priestly functions', '\"an ordained priest\"'),
