(51474, 'big', 3, '/bɪɡ/', 'conspicuous in position or importance', '\"a big figure in the movement\"; \"big man on campus\"; \"he\'s very large in financial circles\"; \"a prominent citizen\"'),
(51475, 'big', 3, '/bɪɡ/', 'given or giving freely', '\"was a big tipper\"; \"the bounteous goodness of God\"; \"bountiful compliments\"; \"a freehanded host\"; \"a handsome allowance\"; \"Saturday\'s child is loving and giving\"; \"a liberal backer of the arts\"; \"a munificent gift\"; \"her fond and openhanded grandfather\"'),
