(51489, 'outstanding', 3, '/aʊtˈstæn.dɪŋ/', 'distinguished from others in excellence', '\"did outstanding work in human relations\"; \"an outstanding war record\"'),
(51490, 'inconspicuous', 3, '/ˌɪn.kənˈspɪk.ju.əs/', 'not prominent or readily noticeable', '\"he pushed the string through an inconspicuous hole\"; \"the invisible man\"'),
(51491, 'discernible', 3, '/dɪˈsɜː.nə.bəl/', 'perceptible by the senses or intellect', '\"things happen in the earth and sky with no discernible cause\"; \"the newspaper reports no discernible progress in the negotiations\"; \"the skyline is easily discernible even at a distance of several miles\"'),
(51492, 'discernible', 3, '/dɪˈsɜː.nə.bəl/', 'capable of being seen or noticed', '\"a discernible change in attitude\"; \"a clearly evident erasure in the manuscript\"; \"an observable change in behavior\"'),
