(51527, 'crushing', 3, '/ˈkrʌʃ.ɪŋ/', 'physically or spiritually devastating; often used in combination', '\"a crushing blow\"; \"a crushing rejection\"; \"bone-crushing\"'),
(51528, 'damaging', 3, '/ˈdæm.ɪ.dʒɪŋ/', 'designed or tending to discredit, especially without positive or helpful suggestions', '\"negative criticism\"'),
(51529, 'damaging', 3, '/ˈdæm.ɪ.dʒɪŋ/', '(sometimes followed by `to\') causing harm or injury', '\"damaging to career and reputation\"; \"the reporter\'s coverage resulted in prejudicial publicity for the defendant\"'),
(51530, 'erosive', 3, '/ɪˈrəʊ.sɪv/', 'wearing away by friction', '\"the erosive effects of waves on the shoreline\"'),
