(51868, 'rectilinear', 3, '/ˌrek.tɪˈlɪn.i.ər/', 'characterized by a straight line or lines', '\"rectilinear patterns in wallpaper\"; \"the rectilinear propagation of light\"'),
(51869, 'planar', 3, '/ˈpleɪ.nər/', 'involving two dimensions', NULL),
(51870, 'coplanar', 3, '/ˌkəʊˈpleɪ.nər/', 'lying in the same plane', NULL),
(51871, 'placoid', 3, '/ˈplæk.ɔɪd/', 'as the hard flattened scales of e.g. sharks', NULL),
(51872, 'tabular', 3, '/ˈtæb.jə.lər/', 'flat; like a table in form', NULL),
(51873, 'tabular', 3, '/ˈtæb.jə.lər/', 'of or pertaining to or arranged in table form', NULL),
(51874, 'unidimensional', 3, '/ˌjuː.nɪ.dɪˈmen.ʃən.əl/', 'relating to a single dimension or aspect; having no depth or scope; \"a prose statement of fact is unidimensional, its value being measured wholly in terms of its truth\"- Mary Sheehan', '\"a novel with one-dimensional characters\"'),
(51875, 'multidimensional', 3, '/ˌmʌl.ti.daɪˈmen.ʃən.əl/', 'having or involving or marked by several dimensions or aspects', '\"multidimensional problems\"; \"a multidimensional proposition\"; \"a multidimensional personality\"'),
(51876, 'dimensional', 3, '/daɪˈmen.ʃən.əl/', 'having dimension--the quality or character or stature proper to a person; \"never matures as a dimensional character; he is pasty, bland, faceless\"- Norman Cousins', NULL),
(51877, 'dimensional', 3, '/daɪˈmen.ʃən.əl/', 'of or relating to dimensions', NULL),
(51878, 'chopped', 3, '/tʃɒpt/', 'prepared by cutting', '\"sliced tomatoes\"; \"sliced ham\"; \"chopped clams\"; \"chopped meat\"; \"shredded cabbage\"'),
(51879, 'incised', 3, '/ɪnˈsaɪzd/', 'cut into with a sharp instrument', NULL),
(51880, 'incised', 3, '/ɪnˈsaɪzd/', 'sharply and deeply indented', NULL),
(51881, 'perforated', 3, '/ˈpɜː.fər.eɪ.tɪd/', 'having a number or series of holes', '\"a perforated steel plate\"; \"perforated cancellation\"; \"perforated stamp\"'),
(51882, 'pierced', 3, '/pɪəst/', 'having a hole cut through', '\"pierced ears\"; \"a perforated eardrum\"; \"a punctured balloon\"'),
(51883, 'severed', 3, '/ˈsev.əd/', 'detached by cutting', '\"cut flowers\"; \"a severed head\"; \"an old tale of Anne Bolyn walking the castle walls with her poor cut-off head under her arm\"'),
(51884, 'uncut', 3, '/ʌnˈkʌt/', 'not cut', NULL),
(51885, 'uncut', 3, '/ʌnˈkʌt/', '(of pages of a book) having adjacent leaves still joined at the fore edge', '\"a book with its leaves still uncut\"'),
(51886, 'uncut', 3, '/ʌnˈkʌt/', 'not shaped by cutting or trimming', '\"an uncut diamond\"; \"rough gemstones\"'),
(51887, 'uncut', 3, '/ʌnˈkʌt/', 'not cut; \"glad to get out of the house with my throat uncut\"- Tobias Smollett', NULL),
(51888, 'imperforate', 3, '/ɪmˈpɜː.fər.ət/', 'not perforated; having no opening', NULL),
(51889, 'hewn', 3, '/hjuːn/', 'cut or shaped with hard blows of a heavy cutting instrument like an ax or chisel', '\"a house built of hewn logs\"; \"rough-hewn stone\"; \"a path hewn through the underbrush\"'),
(51890, 'sheared', 3, '/ʃɪəd/', '(used especially of fur or wool) shaped or finished by cutting or trimming to a uniform length', '\"a coat of sheared lamb\"'),
(51891, 'sheared', 3, '/ʃɪəd/', 'having the hair or wool cut or clipped off as if with shears or clippers', '\"picked up the baby\'s shorn curls from the floor\"; \"naked as a sheared sheep\"'),
(51892, 'slashed', 3, '/slæʃt/', 'having long and narrow ornamental cuts showing an underlying fabric', '\"a slashed doublet\"; \"slashed cuffs showing the scarlet lining\"'),
(51893, 'slashed', 3, '/slæʃt/', 'patterned by having color applied with sweeping strokes; \"brown iris...slashed with yellow\"- Willa Cather', NULL),
(51894, 'curious', 3, '/ˈkjʊə.ri.əs/', 'eager to investigate and learn or learn more (sometimes about others\' concerns)', '\"a curious child is a teacher\'s delight\"; \"a trap door that made me curious\"; \"curious investigators\"; \"traffic was slowed by curious rubberneckers\"; \"curious about the neighbor\'s doings\"'),
(51895, 'curious', 3, '/ˈkjʊə.ri.əs/', 'beyond or deviating from the usual or expected', '\"a curious hybrid accent\"; \"her speech has a funny twang\"; \"they have some funny ideas about war\"; \"had an odd name\"; \"the peculiar aromatic odor of cloves\"; \"something definitely queer about this town\"; \"what a rum fellow\"; \"singular behavior\"'),
(51896, 'curious', 3, '/ˈkjʊə.ri.əs/', 'having curiosity aroused; eagerly interested in learning more', '\"a trap door that made me curious\"');
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(51897, 'inquisitive', 3, '/ɪnˈkwɪz.ɪ.tɪv/', 'showing curiosity', '\"if someone saw a man climbing a light post they might get inquisitive\"; \"raised a speculative eyebrow\"'),
(51898, 'inquisitive', 3, '/ɪnˈkwɪz.ɪ.tɪv/', 'inquiring or appearing to inquire', '\"an inquiring look\"; \"the police are proverbially inquisitive\"'),
(51899, 'nosy', 3, '/ˈnəʊ.zi/', 'offensively curious or inquisitive', '\"curious about the neighbor\'s doings\"; \"he flipped through my letters in his nosy way\"; \"prying eyes\"; \"the snoopy neighbor watched us all day\"'),
(51900, 'incurious', 3, '/ɪnˈkjʊə.ri.əs/', 'showing absence of intellectual inquisitiveness or natural curiosity', '\"strangely incurious about the cause of the political upheaval surrounding them\"'),
