(51909, 'disused', 3, '/dɪsˈjuːzd/', 'no longer in use', '\"obsolete words\"'),
(51910, 'outdated', 3, '/aʊtˈdeɪ.tɪd/', 'old; no longer valid or fashionable', '\"obsolete words\"; \"an obsolete locomotive\"; \"outdated equipment\"; \"superannuated laws\"; \"out-of-date ideas\"'),
(51911, 'obsolescent', 3, '/ˌɒb.səˈles.ənt/', 'becoming obsolete', NULL),
(51912, 'cursed', 3, '/kɜːst/', 'deserving a curse; sometimes used as an intensifier', '\"villagers shun the area believing it to be cursed\"; \"cursed with four daughter\"; \"not a cursed drop\"; \"his cursed stupidity\"; \"I\'ll be cursed if I can see your reasoning\"'),
(51913, 'cursed', 3, '/kɜːst/', 'in danger of the eternal punishment of Hell', '\"poor damned souls\"'),
