(51915, 'blasted', 3, '/ˈblɑː.stɪd/', 'expletives used informally as intensifiers', '\"he\'s a blasted idiot\"; \"it\'s a blamed shame\"; \"a blame cold winter\"; \"not a blessed dime\"; \"I\'ll be damned (or blessed or darned or goddamned) if I\'ll do any such thing\"; \"he\'s a damn (or goddam or goddamned) fool\"; \"a deuced idiot\"; \"an infernal nuisance\"'),
(51916, 'damnable', 3, '/ˈdæm.nə.bəl/', 'deserving a curse', '\"her damnable pride\"'),
(51917, 'blessed', 3, '/ˈbles.ɪd/', 'highly favored or fortunate (as e.g. by divine grace)', '\"our blessed land\"; \"the blessed assurance of a steady income\"'),
