(52188, 'determinable', 3, '/dɪˈtɜː.mɪ.nə.bəl/', 'capable of being determined or limited or fixed', '\"determinable velocities\"; \"matters determinable by law\"'),
(52189, 'ascertainable', 3, '/ˌæs.əˈteɪ.nə.bəl/', 'capable of being ascertained or found out', '\"ascertainable facts\"'),
(52190, 'definable', 3, '/dɪˈfaɪ.nə.bəl/', 'capable of being defined, limited, or explained', '\"definable terms\"; \"definable rules\"'),
