(52200, 'formulated', 3, '/ˈfɔː.mjʊ.leɪ.tɪd/', 'devised; developed according to an orderly plan', '\"he had well formulated opinions on schooling\"'),
(52201, 'undeveloped', 3, '/ˌʌn.dɪˈvel.əpt/', 'not developed', '\"courses in interior design were rare and undeveloped\"; \"undeveloped social awareness\"'),
(52202, 'vestigial', 3, '/vesˈtɪdʒ.i.əl/', 'not fully developed in mature animals', '\"rudimentary wings\"'),
(52203, 'dextral', 3, '/ˈdek.strəl/', 'of or on the right', '\"a dextral gastropod shell with the apex upward has its opening on the right when facing the observer\"; \"a dextral flatfish lies with the right eye uppermost\"'),
(52204, 'dextral', 3, '/ˈdek.strəl/', 'preferring to use right foot or hand or eye', '\"dextral individuals exhibit dominance of the right hand and eye\"'),
