(52206, 'sinistral', 3, '/ˈsɪn.ɪ.strəl/', 'of or on the left', '\"a sinistral gastropod shell with the apex upward has its opening on the left when facing the observer\"; \"a sinistral flatfish lies with the left eye uppermost\"'),
(52207, 'sinistral', 3, '/ˈsɪn.ɪ.strəl/', 'preferring to use left foot or hand or eye', '\"sinistral individuals exhibit dominance of the left hand and eye\"'),
(52208, 'sinister', 3, '/ˈsɪn.ɪ.stər/', 'on or starting from the wearer\'s left', '\"bar sinister\"'),
(52209, 'diabatic', 3, '/ˌdaɪ.əˈbæt.ɪk/', 'involving a transfer of heat', '\"a diabatic process\"'),
(52210, 'adiabatic', 3, '/ˌeɪ.daɪ.əˈbæt.ɪk/', 'occurring without loss or gain of heat', '\"adiabatic expansion\"'),
(52211, 'differentiated', 3, '/ˌdɪf.əˈren.ʃi.eɪ.tɪd/', 'made different (especially in the course of development) or shown to be different', '\"the differentiated markings of butterflies\"; \"the regionally differentiated results\"'),
(52212, 'differentiated', 3, '/ˌdɪf.əˈren.ʃi.eɪ.tɪd/', 'exhibiting biological specialization; adapted during development to a specific function or environment', NULL),
(52213, 'undifferentiated', 3, '/ˌʌn.dɪf.əˈren.ʃi.eɪ.tɪd/', 'not differentiated', NULL),
(52214, 'difficult', 3, '/ˈdɪf.ɪ.kəlt/', 'not easy; requiring great physical or mental effort to accomplish or comprehend or endure', '\"a difficult task\"; \"nesting places on the cliffs are difficult of access\"; \"difficult times\"; \"why is it so hard for you to keep a secret?\"'),
(52215, 'arduous', 3, '/ˈɑː.dʒu.əs/', 'difficult to accomplish; demanding considerable mental effort and skill', '\"the arduous work of preparing a dictionary\"'),
(52216, 'arduous', 3, '/ˈɑː.dʒu.əs/', 'characterized by effort to the point of exhaustion; especially physical effort', '\"worked their arduous way up the mining valley\"; \"a grueling campaign\"; \"hard labor\"; \"heavy work\"; \"heavy going\"; \"spent many laborious hours on the project\"; \"set a punishing pace\"'),
(52217, 'arduous', 3, '/ˈɑː.dʒu.əs/', 'taxing to the utmost; testing powers of endurance; \"your willingness after these six arduous days to remain here\"- F.D.Roosevelt', '\"his final, straining burst of speed\"; \"a strenuous task\"'),
(52218, 'baffling', 3, '/ˈbæf.lɪŋ/', 'making great mental demands; hard to comprehend or solve or believe', '\"a baffling problem\"; \"I faced the knotty problem of what to have for breakfast\"; \"a problematic situation at home\"'),
(52219, 'catchy', 3, '/ˈkætʃ.i/', 'having concealed difficulty', '\"a catchy question\"; \"a tricky recipe to follow\"'),
(52220, 'fractious', 3, '/ˈfræk.ʃəs/', 'unpredictably difficult in operation; likely to be troublesome', '\"rockets were much too fractious to be tested near thickly populated areas\"; \"fractious components of a communication system\"'),
(52221, 'fractious', 3, '/ˈfræk.ʃəs/', 'stubbornly resistant to authority or control', '\"a fractious animal that would not submit to the harness\"; \"a refractory child\"'),
(52222, 'herculean', 3, '/ˌhɜː.kjəˈliː.ən/', 'extremely difficult; requiring the strength of a Hercules', '\"a herculean task\"'),
(52223, 'herculean', 3, '/ˌhɜː.kjəˈliː.ən/', 'displaying superhuman strength or power', '\"herculean exertions\"'),
(52224, 'nasty', 3, '/ˈnɑː.sti/', 'exasperatingly difficult to handle or circumvent', '\"a nasty problem\"; \"a good man to have on your side in a tight situation\"'),
(52225, 'nasty', 3, '/ˈnɑː.sti/', 'offensive or even (of persons) malicious; \"Will he say nasty things at my funeral?\"- Ezra Pound', '\"in a nasty mood\"; \"a nasty accident\"; \"a nasty shock\"; \"a nasty smell\"; \"a nasty trick to pull\"'),
(52226, 'rocky', 3, '/ˈrɒk.i/', 'full of hardship or trials', '\"the rocky road to success\"; \"they were having a rough time\"'),
(52227, 'rocky', 3, '/ˈrɒk.i/', 'abounding in rocks or stones', '\"rocky fields\"; \"stony ground\"; \"bouldery beaches\"'),
(52228, 'rocky', 3, '/ˈrɒk.i/', 'liable to rock', '\"on high rocky heels\"'),
(52229, 'serious', 3, '/ˈsɪə.ri.əs/', 'requiring effort or concentration; complex and not easy to answer or solve', '\"raised serious objections to the proposal\"; \"the plan has a serious flaw\"'),
(52230, 'serious', 3, '/ˈsɪə.ri.əs/', 'of great consequence', '\"marriage is a serious matter\"'),
(52231, 'serious', 3, '/ˈsɪə.ri.əs/', 'concerned with work or important matters rather than play or trivialities', '\"a serious student of history\"; \"a serious attempt to learn to ski\"; \"gave me a serious look\"; \"a serious young man\"; \"are you serious or joking?\"; \"Don\'t be so serious!\"'),
(52232, 'thorny', 3, '/ˈθɔː.ni/', 'bristling with perplexities', '\"the thorny question of states\' rights\"'),
(52233, 'troublesome', 3, '/ˈtrʌb.əl.səm/', 'difficult to deal with', '\"a troublesome infection\"; \"a troublesome situation\"'),
(52234, 'trying', 3, '/ˈtraɪ.ɪŋ/', 'hard to endure', '\"fell upon trying times\"'),
(52235, 'vexed', 3, '/vekst/', 'causing difficulty in finding an answer or solution; much disputed', '\"the vexed issue of priorities\"; \"we live in vexed and troubled times\"'),
(52236, 'cushy', 3, '/ˈkʊʃ.i/', 'not burdensome or demanding; borne or done easily and without hardship', '\"what a cushy job!\"; \"the easygoing life of a parttime consultant\"; \"a soft job\"'),
(52237, 'elementary', 3, '/ˌel.ɪˈmen.tər.i/', 'easy and not involved or complicated', '\"an elementary problem in statistics\"; \"elementary, my dear Watson\"; \"a simple game\"; \"found an uncomplicated solution to the problem\"'),
(52238, 'elementary', 3, '/ˌel.ɪˈmen.tər.i/', 'of or being the essential or basic part', '\"an elementary need for love and nurturing\"'),
(52239, 'elementary', 3, '/ˌel.ɪˈmen.tər.i/', 'of or pertaining to or characteristic of elementary school or elementary education', '\"the elementary grades\"; \"elementary teachers\"'),
(52240, 'painless', 3, '/ˈpeɪn.ləs/', 'requiring little hard work or exertion', '\"a painless solution to the problem\"'),
(52241, 'painless', 3, '/ˈpeɪn.ləs/', 'not causing physical or psychological pain', '\"painless dentistry\"'),
(52242, 'simplified', 3, '/ˈsɪm.plɪ.faɪd/', 'made easy or uncomplicated', NULL),
