(52264, 'negligent', 3, '/ˈneɡ.lɪ.dʒənt/', 'characterized by neglect and undue lack of concern', '\"negligent parents\"; \"negligent of detail\"; \"negligent in his correspondence\"'),
(52265, 'diluted', 3, '/daɪˈluː.tɪd/', 'reduced in strength or concentration or quality or purity', '\"diluted alcohol\"; \"a dilute solution\"; \"dilute acetic acid\"'),
(52266, 'watery', 3, '/ˈwɔː.tər.i/', 'overly diluted; thin and insipid', '\"washy coffee\"; \"watery milk\"; \"weak tea\"'),
(52267, 'watery', 3, '/ˈwɔː.tər.i/', 'relating to or resembling or consisting of water', '\"a watery substance\"; \"a watery color\"'),
