(52270, 'neat', 3, '/niːt/', 'without water', '\"took his whiskey neat\"'),
(52271, 'neat', 3, '/niːt/', 'free from what is tawdry or unbecoming', '\"a neat style\"; \"a neat set of rules\"; \"she hated to have her neat plans upset\"'),
(52272, 'neat', 3, '/niːt/', 'clean or organized', '\"her neat dress\"; \"a neat room\"'),
(52273, 'neat', 3, '/niːt/', 'showing care in execution', '\"neat homework\"; \"neat handwriting\"'),
