(52284, 'conciliatory', 3, '/kənˈsɪl.i.ə.tər.i/', 'intended to placate', '\"spoke in a conciliating tone\"; \"a conciliatory visit\"'),
(52285, 'pacific', 3, '/pəˈsɪf.ɪk/', 'promoting peace', '\"the result of this pacific policy was that no troops were called up\"'),
(52286, 'pacific', 3, '/pəˈsɪf.ɪk/', 'disposed to peace or of a peaceful nature', '\"the pacific temper seeks to settle disputes on grounds of justice rather than by force\"; \"a quiet and peaceable person\"; \"in a peaceable and orderly manner\"'),
(52287, 'alienating', 3, '/ˈeɪ.li.ə.neɪ.tɪŋ/', 'causing hostility or loss of friendliness', '\"her sudden alienating aloofness\"'),
(52288, 'nonstop', 3, '/ˈnɒn.stɒp/', '(of a journey especially a flight) occurring without stops', '\"a nonstop flight to Atlanta\"'),
(52289, 'nonstop', 4, '/ˈnɒn.stɒp/', 'without stopping', '\"we are flying nonstop form New York to Tokyo\"'),
(52290, 'straightforward', 3, '/ˌstreɪtˈfɔː.wəd/', 'pointed directly ahead', '\"a straightforward gaze\"'),
(52291, 'straightforward', 3, '/ˌstreɪtˈfɔː.wəd/', 'free from ambiguity', '\"a straightforward set of instructions\"'),
(52292, 'indirect', 3, '/ˌɪn.daɪˈrekt/', 'not direct in spatial dimension; not leading by a straight line or course to a destination', '\"sometimes taking an indirect path saves time\"; \"you must take an indirect course in sailing\"'),
(52293, 'indirect', 3, '/ˌɪn.daɪˈrekt/', 'extended senses; not direct in manner or language or behavior or action', '\"making indirect but legitimate inquiries\"; \"an indirect insult\"; \"doubtless they had some indirect purpose in mind\"; \"though his methods are indirect they are not dishonest\"; \"known as a shady indirect fellow\"'),
(52294, 'indirect', 3, '/ˌɪn.daɪˈrekt/', 'having intervening factors or persons or influences', '\"reflection from the ceiling provided a soft indirect light\"; \"indirect evidence\"; \"an indirect cause\"'),
(52295, 'indirect', 3, '/ˌɪn.daɪˈrekt/', 'not as a direct effect or consequence', '\"indirect benefits\"; \"an indirect advantage\"'),
(52296, 'askance', 3, '/əˈskæns/', '(used especially of glances) directed to one side with or as if with doubt or suspicion or envy; \"her eyes with their misted askance look\"- Elizabeth Bowen', '\"sidelong glances\"'),
(52297, 'askance', 4, '/əˈskæns/', 'with a side or oblique glance', '\"did not quite turn all the way back but looked askance at me with her dark eyes\"'),
(52298, 'askance', 4, '/əˈskæns/', 'with suspicion or disapproval', '\"he looked askance at the offer\"'),
(52299, 'devious', 3, '/ˈdiː.vi.əs/', 'deviating from a straight course', '\"a scenic but devious route\"; \"a long and circuitous journey by train and boat\"; \"a roundabout route avoided rush-hour traffic\"'),
(52300, 'devious', 3, '/ˈdiː.vi.əs/', 'indirect in departing from the accepted or proper way; misleading', '\"used devious means to achieve success\"; \"gave oblique answers to direct questions\"; \"oblique political maneuvers\"'),
