(52304, 'brutal', 3, '/ˈbruː.təl/', 'disagreeably direct and precise', '\"he spoke with brutal honesty\"'),
(52305, 'brutal', 3, '/ˈbruː.təl/', 'harsh', '\"the brutal summer sun\"; \"a brutal winter\"'),
(52306, 'pointed', 3, '/ˈpɔɪn.tɪd/', 'direct and obvious in meaning or reference; often unpleasant', '\"a pointed critique\"; \"a pointed allusion to what was going on\"; \"another pointed look in their direction\"'),
(52307, 'pointed', 3, '/ˈpɔɪn.tɪd/', 'having a point', NULL),
