(52460, 'arid', 3, '/ˈær.ɪd/', 'lacking vitality or spirit; lifeless; \"a prissy and emotionless creature...settles into a mold of desiccated snobbery\"-C.J.Rolo', '\"a technically perfect but arid performance of the sonata\"; \"a desiccate romance\"'),
(52461, 'arid', 3, '/ˈær.ɪd/', 'lacking sufficient water or rainfall', '\"an arid climate\"; \"a waterless well\"; \"miles of waterless country to cross\"'),
(52462, 'humdrum', 3, '/ˈhʌm.drʌm/', 'tediously repetitious or lacking in variety; \"a humdrum existence; all work and no play\"', '\"nothing is so monotonous as the sea\"'),
(52463, 'dynamic', 3, '/daɪˈnæm.ɪk/', 'characterized by action or forcefulness or force of personality', '\"a dynamic market\"; \"a dynamic speaker\"; \"the dynamic president of the firm\"'),
