(52468, 'eager', 3, '/ˈiː.ɡər/', 'having or showing keen interest or intense desire or impatient expectancy', '\"eager to learn\"; \"eager to travel abroad\"; \"eager for success\"; \"eager helpers\"; \"an eager look\"'),
(52469, 'overeager', 3, '/ˌəʊ.vəˈriː.ɡər/', 'excessively eager', '\"overeager in his pursuit of the girl\"'),
(52470, 'reluctant', 3, '/rɪˈlʌk.tənt/', 'not eager', '\"foreigners stubbornly reluctant to accept our ways\"; \"fresh from college and reluctant for the moment to marry him\"'),
(52471, 'reluctant', 3, '/rɪˈlʌk.tənt/', 'disinclined to become involved', '\"they were usually reluctant to socialize\"; \"reluctant to help\"'),
(52472, 'eared', 3, '/ɪəd/', 'having ears (or appendages resembling ears) or having ears of a specified kind; often used in combination', NULL),
(52473, 'earless', 3, '/ˈɪə.ləs/', 'lacking external ears', '\"earless seals\"'),
(52474, 'early', 3, '/ˈɜː.li/', 'at or near the beginning of a period of time or course of events or before the usual or expected time', '\"early morning\"; \"an early warning\"; \"early diagnosis\"; \"an early death\"; \"took early retirement\"; \"an early spring\"; \"early varieties of peas and tomatoes mature before most standard varieties\"'),
(52475, 'early', 3, '/ˈɜː.li/', 'being or occurring at an early stage of development', '\"in an early stage\"; \"early forms of life\"; \"early man\"; \"an early computer\"'),
(52476, 'early', 3, '/ˈɜː.li/', 'of an early stage in the development of a language or literature', '\"the Early Hebrew alphabetical script is that used mainly from the 11th to the 6th centuries B.C.\"; \"Early Modern English is represented in documents printed from 1476 to 1700\"'),
(52477, 'early', 3, '/ˈɜː.li/', 'very young', '\"at an early age\"'),
(52478, 'early', 3, '/ˈɜː.li/', 'expected in the near future', '\"look for an early end to the negotiations\"'),
(52479, 'early', 4, '/ˈɜː.li/', 'before the usual time or the time expected', '\"she graduated early\"; \"the house was completed ahead of time\"'),
