(52494, 'late', 4, '/leɪt/', 'later than usual or than expected', '\"the train arrived late\"; \"we awoke late\"; \"the children came late to school\"; \"notice came so tardily that we almost missed the deadline\"; \"I belatedly wished her a happy birthday\"'),
(52495, 'late', 4, '/leɪt/', 'at an advanced age or stage', '\"she married late\"; \"undertook the project late in her career\"'),
(52496, 'posthumous', 3, '/ˈpɒs.tʃʊ.məs/', 'occurring or coming into existence after a person\'s death', '\"a posthumous award\"; \"a posthumous book\"; \"a posthumous daughter\"'),
(52497, 'archaic', 3, '/ɑːˈkeɪ.ɪk/', 'little evolved from or characteristic of an earlier ancestral type', '\"archaic forms of life\"; \"primitive mammals\"; \"the okapi is a short-necked primitive cousin of the giraffe\"'),
