INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(52581, 'economic', 3, '/ˌiː.kəˈnɒm.ɪk/', 'using the minimum of time or resources necessary for effectiveness', '\"an economic use of home heating oil\"; \"a modern economical heating system\"; \"an economical use of her time\"'),
(52582, 'economic', 3, '/ˌiː.kəˈnɒm.ɪk/', 'financially rewarding', '\"it was no longer economic to keep the factory open\"; \"have to keep prices high enough to make it economic to continue the service\"'),
(52583, 'economic', 3, '/ˌiː.kəˈnɒm.ɪk/', 'concerned with worldly necessities of life (especially money)', '\"he wrote the book primarily for economic reasons\"; \"gave up the large house for economic reasons\"; \"in economic terms they are very privileged\"'),
(52584, 'economic', 3, '/ˌiː.kəˈnɒm.ɪk/', 'of or relating to the science of economics', '\"economic theory\"'),
(52585, 'economic', 3, '/ˌiː.kəˈnɒm.ɪk/', 'of or relating to an economy, the system of production and management of material wealth', '\"economic growth\"; \"aspects of social, political, and economical life\"'),
(52586, 'expeditious', 3, '/ˌek.spɪˈdɪʃ.əs/', 'marked by speed and efficiency', NULL),
(52587, 'streamlined', 3, '/ˈstriːm.laɪnd/', 'made efficient by stripping off nonessentials', '\"short streamlined meetings\"; \"a streamlined hiring process\"'),
