(52589, 'inefficient', 3, '/ˌɪn.ɪˈfɪʃ.ənt/', 'not producing desired results; wasteful', '\"an inefficient campaign against drugs\"; \"outdated and inefficient design and methods\"'),
(52590, 'uneconomical', 3, '/ˌʌn.iː.kəˈnɒm.ɪ.kəl/', 'inefficient in use of time and effort and materials', '\"a clumsy and wasteful process\"; \"wasteful duplication of effort\"; \"uneconomical ebb and flow of power\"'),
