(52940, 'exhausted', 3, '/ɪɡˈzɔː.stɪd/', 'depleted of energy, force, or strength', '\"impossible to grow tobacco on the exhausted soil\"; \"the exhausted food sources\"; \"exhausted oil wells\"'),
(52941, 'exhausted', 3, '/ɪɡˈzɔː.stɪd/', 'drained physically', '\"the day\'s events left her completely exhausted--her strength drained\"'),
(52942, 'exhausted', 3, '/ɪɡˈzɔː.stɪd/', 'drained of energy or effectiveness; extremely tired; completely exhausted', '\"the day\'s shopping left her exhausted\"; \"he went to bed dog-tired\"; \"was fagged and sweaty\"; \"the trembling of his played out limbs\"; \"felt completely washed-out\"; \"only worn-out horses and cattle\"; \"you look worn out\"'),
