(54287, 'unintentional', 3, '/ˌʌn.ɪnˈten.ʃən.əl/', 'not done with purpose or intent', '\"an unintended slight\"; \"an unintentional pun\"; \"the offense was unintentional\"; \"an unwitting mistake may be overlooked\"'),
(54288, 'unintentional', 3, '/ˌʌn.ɪnˈten.ʃən.əl/', 'without deliberate intent; \"my heart with unwilled love grew warm\"- George Macdonald', NULL),
(54289, 'designed', 3, '/dɪˈzaɪnd/', 'done or made or performed with purpose and intent; \"style...is more than the deliberate and designed creation\"- Havelock Ellis', '\"games designed for all ages\"; \"well-designed houses\"'),
(54290, 'fashioned', 3, '/ˈfæʃ.ənd/', 'planned and made or fashioned artistically', '\"beautifully fashioned dresses\"'),
(54291, 'undesigned', 3, '/ˌʌn.dɪˈzaɪnd/', 'not done or made or performed with purpose or intent', NULL),
(54292, 'intensifying', 3, '/ɪnˈten.sɪ.faɪ.ɪŋ/', 'increasing in strength or intensity', NULL),
