(54295, 'augmentative', 3, '/ɔːɡˈmen.tə.tɪv/', 'increasing or having the power to increase especially in size or amount or degree', '\"`up\' is an augmentative word in `hurry up\'\"'),
(54296, 'moderating', 3, '/ˈmɒd.ər.eɪ.tɪŋ/', 'lessening in intensity or strength', NULL),
(54297, 'tempering', 3, '/ˈtem.pər.ɪŋ/', 'moderating by making more temperate', NULL),
