(54300, 'interested', 3, '/ˈɪn.trəs.tɪd/', 'having or showing interest; especially curiosity or fascination or concern', '\"an interested audience\"; \"interested in sports\"; \"was interested to hear about her family\"; \"interested in knowing who was on the telephone\"; \"interested spectators\"'),
(54301, 'apathetic', 3, '/ˌæp.əˈθet.ɪk/', 'marked by a lack of interest; \"the universe is neither hostile nor friendly; it is simply indifferent\"', '\"an apathetic audience\"'),
(54302, 'apathetic', 3, '/ˌæp.əˈθet.ɪk/', 'showing little or no emotion or animation', '\"a woman who became active rather than apathetic as she grew older\"'),
