(54307, 'newsworthy', 3, '/ˈnjuːzˌwɜː.ði/', 'sufficiently interesting to be reported in a newspaper', NULL),
(54308, 'insipid', 3, '/ɪnˈsɪp.ɪd/', 'lacking interest or significance or impact', '\"an insipid personality\"; \"jejune novel\"'),
(54309, 'intramural', 3, '/ˌɪn.trəˈmjʊə.rəl/', 'carried on within the bounds of an institution or community', '\"most of the students participated actively in the college\'s intramural sports program\"'),
(54310, 'extramural', 3, '/ˌek.strəˈmjʊə.rəl/', 'carried on outside the bounds of an institution or community', '\"extramural sports\"'),
(54311, 'intercollegiate', 3, '/ˌɪn.tə.kəˈliː.dʒi.ət/', 'used of competition between colleges or universities', '\"intercollegiate basketball\"'),
