(54322, 'interfering', 3, '/ˌɪn.təˈfɪə.rɪŋ/', 'intrusive in a meddling or offensive manner', '\"an interfering old woman\"; \"bustling about self-importantly making an officious nuisance of himself\"; \"busy about other people\'s business\"'),
(54323, 'unintrusive', 3, '/ˌʌn.ɪnˈtruː.sɪv/', 'not interfering or meddling', NULL),
