(54364, 'sad', 3, '/sæd/', 'experiencing or showing sorrow or unhappiness; \"Better by far that you should forget and smile / Than that you should remember and be sad\"- Christina Rossetti', '\"feeling sad because his dog had died\"'),
(54365, 'sad', 3, '/sæd/', 'of things that make you feel sad; \"When I am dead, my dearest, / Sing no sad songs for me\"- Christina Rossetti', '\"sad news\"; \"she doesn\'t like sad movies\"; \"it was a very sad story\"'),
(54366, 'doleful', 3, '/ˈdəʊl.fəl/', 'filled with or evoking sadness', '\"the child\'s doleful expression\"; \"stared with mournful eyes\"; \"mournful news\"'),
