(55090, 'necromantic', 3, '/ˌnek.rəʊˈmæn.tɪk/', 'given to or produced by or used in the art of conjuring up the dead', '\"a necromantic sorcerer\"; \"necromantic delusions\"; \"necromantic powders and other weird objects\"'),
(55091, 'necromantic', 3, '/ˌnek.rəʊˈmæn.tɪk/', 'relating to or associated with necromancy', '\"mysterious necromantic rites\"'),
(55092, 'talismanic', 3, '/ˌtæl.ɪzˈmæn.ɪk/', 'possessing or believed to possess magic power especially protective power', '\"a talismanic amulet\"'),
