(55101, 'pathological', 3, '/ˌpæθ.əˈlɒdʒ.ɪ.kəl/', 'caused by or evidencing a mentally disturbed condition', '\"a pathological liar\"; \"a pathological urge to succeed\"'),
(55102, 'pathological', 3, '/ˌpæθ.əˈlɒdʒ.ɪ.kəl/', 'of or relating to the practice of pathology', '\"pathological laboratory\"'),
