(55141, 'freakish', 3, '/ˈfriː.kɪʃ/', 'characteristic of a freak', '\"a freakish extra toe\"'),
(55143, 'supernormal', 3, '/ˌsuː.pəˈnɔː.məl/', 'exceeding the normal or average', '\"years of supernormal employment during the war\"; \"a phase of supernormal excitability\"'),
(55144, 'supernormal', 3, '/ˌsuː.pəˈnɔː.məl/', 'beyond the range of the normal or scientifically explainable', '\"supernormal intimations\"'),
