(55148, 'psychokinetic', 3, '/ˌsaɪ.kəʊ.kɪˈnet.ɪk/', 'moving an object without apparent use of physical means', NULL),
(55149, 'northbound', 3, '/ˈnɔːθ.baʊnd/', 'moving toward the north', '\"the northbound lane\"; \"we took the north train\"; \"the northward flow of traffic\"'),
(55150, 'northerly', 3, '/ˈnɔː.ðə.li/', 'coming from the north; used especially of wind', '\"the north wind doth blow\"; \"a northern snowstorm\"; \"the winds are northerly\"'),
(55151, 'northerly', 3, '/ˈnɔː.ðə.li/', 'situated in or oriented toward the north', '\"the northern suburbs\"; \"going in a northerly direction\"'),
