(55199, 'determined', 3, '/dɪˈtɜː.mɪnd/', 'devoting full strength and concentrated attention to', '\"made continued and determined efforts to find and destroy enemy headquarters\"'),
(55200, 'ascertained', 3, '/əˈsɜː.teɪnd/', 'discovered or determined by scientific observation', '\"variation in the ascertained flux depends on a number of factors\"; \"the discovered behavior norms\"; \"discovered differences in achievement\"; \"no explanation for the observed phenomena\"'),
(55201, 'undetermined', 3, '/ˌʌn.dɪˈtɜː.mɪnd/', 'not yet having been ascertained or determined', '\"of undetermined species\"'),
(55202, 'noxious', 3, '/ˈnɒk.ʃəs/', 'injurious to physical or mental health', '\"noxious chemical wastes\"; \"noxious ideas\"'),
(55203, 'baneful', 3, '/ˈbeɪn.fəl/', 'exceedingly harmful', NULL),
(55204, 'innocuous', 3, '/ɪˈnɒk.ju.əs/', 'not injurious to physical or mental health', NULL),
(55205, 'innocuous', 3, '/ɪˈnɒk.ju.əs/', 'not causing disapproval', '\"it was an innocuous remark\"; \"confined himself to innocuous generalities\"; \"unobjectionable behavior\"'),
(55206, 'obedient', 3, '/əˈbiː.di.ənt/', 'dutifully complying with the commands or instructions of those in authority; \"the obedient colonies...are heavily taxed; the refractory remain unburdened\"- Edmund Burke', '\"an obedient soldier\"; \"obedient children\"; \"a little man obedient to his wife\"'),
(55207, 'acquiescent', 3, '/ˌæk.wiˈes.ənt/', 'willing to carry out the orders or wishes of another without protest', '\"too acquiescent to challenge authority\"'),
(55208, 'conformable', 3, '/kənˈfɔː.mə.bəl/', 'quick to comply; \"I have been to you a true and humble wife, at all times to your will conformable\"-Shakespeare', NULL),
(55209, 'dutiful', 3, '/ˈdjuː.tɪ.fəl/', 'willingly obedient out of a sense of duty and respect; \"Patient Griselda was a chaste and duteous wife\";', '\"a dutiful child\"; \"a dutiful citizen\"'),
(55210, 'disobedient', 3, '/ˌdɪs.əˈbiː.di.ənt/', 'not obeying or complying with commands of those in authority', '\"disobedient children\"'),
(55211, 'disobedient', 3, '/ˌdɪs.əˈbiː.di.ənt/', 'unwilling to submit to authority', '\"unruly teenagers\"'),
(55212, 'froward', 3, '/ˈfrəʊ.əd/', 'habitually disposed to disobedience and opposition', NULL),
(55213, 'recusant', 3, '/ˈrek.jʊ.zənt/', 'refusing to submit to authority; \"the recusant electors...cooperated in electing a new Senate\"- Mary W.Williams', NULL),
(55214, 'unobtrusive', 3, '/ˌʌn.əbˈtruː.sɪv/', 'not obtrusive or undesirably noticeable', '\"a quiet, unobtrusive life of self-denial\"'),
(55215, 'clinical', 3, '/ˈklɪn.ɪ.kəl/', 'scientifically detached; unemotional', '\"he spoke in the clipped clinical monotones typical of police testimony\"'),
(55216, 'clinical', 3, '/ˈklɪn.ɪ.kəl/', 'relating to a clinic or conducted in or as if in a clinic and depending on direct observation of patients', '\"clinical observation\"; \"clinical case study\"'),
