(55218, 'impersonal', 3, '/ɪmˈpɜː.sən.əl/', 'not relating to or responsive to individual persons', '\"an impersonal corporation\"; \"an impersonal remark\"'),
(55219, 'verifiable', 3, '/ˈver.ɪ.faɪ.ə.bəl/', 'capable of being verified', '\"a verifiable account of the incident\"'),
(55220, 'subjective', 3, '/səbˈdʒek.tɪv/', 'taking place within the mind and modified by individual bias', '\"a subjective judgment\"'),
(55221, 'tributary', 3, '/ˈtrɪb.jʊ.tər.i/', 'paying tribute', '\"a tributary colony\"'),
