(55223, 'unobligated', 3, '/ʌnˈɒb.lɪ.ɡeɪ.tɪd/', 'not obligated', NULL),
(55224, 'obvious', 3, '/ˈɒb.vi.əs/', 'easily perceived by the senses or grasped by the mind', '\"obvious errors\"'),
