(55862, 'seeded', 3, '/ˈsiː.dɪd/', 'having seeds as specified', '\"many-seeded\"; \"black-seeded\"'),
(55863, 'seeded', 3, '/ˈsiː.dɪd/', 'having the seeds extracted', '\"seeded raisins\"'),
(55864, 'unplanted', 3, '/ʌnˈplɑːn.tɪd/', 'not planted', NULL),
(55865, 'uncropped', 3, '/ʌnˈkrɒpt/', 'not used for growing crops', '\"uncropped soil\"'),
(55866, 'unseeded', 3, '/ʌnˈsiː.dɪd/', '(of a piece of ground) not have a crop sown on it', '\"farmland still unsown\"'),
(55867, 'unseeded', 3, '/ʌnˈsiː.dɪd/', 'not seeded; used of players of lesser skill', NULL),
(55868, 'plowed', 3, '/plaʊd/', '(of farmland) broken and turned over with a plow', '\"plowed fields\"'),
(55869, 'tilled', 3, '/tɪld/', 'turned or stirred by plowing or harrowing or hoeing', '\"tilled land ready for seed\"'),
(55870, 'unplowed', 3, '/ʌnˈplaʊd/', '(of farmland) not plowed', '\"unplowed fields\"; \"unbroken land\"'),
(55871, 'untilled', 3, '/ʌnˈtɪld/', 'not plowed or harrowed or hoed', '\"untilled land\"'),
(55872, 'cultivated', 3, '/ˈkʌl.tɪ.veɪ.tɪd/', '(of land or fields) prepared for raising crops by plowing or fertilizing', '\"cultivated land\"'),
(55873, 'cultivated', 3, '/ˈkʌl.tɪ.veɪ.tɪd/', 'no longer in the natural state; developed by human care and for human use', '\"cultivated roses\"; \"cultivated blackberries\"'),
(55874, 'uncultivated', 3, '/ʌnˈkʌl.tɪ.veɪ.tɪd/', '(of land or fields) not prepared for raising crops', '\"uncultivated land\"'),
(55875, 'applicative', 3, '/əˈplɪk.ə.tɪv/', 'readily applicable or practical', NULL),
(55876, 'interoperable', 3, '/ˌɪn.tərˈɒp.ər.ə.bəl/', 'able to exchange and use information', NULL),
(55877, 'serviceable', 3, '/ˈsɜː.vɪ.sə.bəl/', 'intended or able to serve a purpose without elaboration; \"serviceable low-heeled shoes\";', NULL),
(55878, 'serviceable', 3, '/ˈsɜː.vɪ.sə.bəl/', 'ready for service or able to give long service', '\"serviceable equipment\"; \"heavy serviceable fabrics\"'),
(55879, 'serviceable', 3, '/ˈsɜː.vɪ.sə.bəl/', 'capable of being put to good use', '\"a serviceable kitchen gadget\"'),
(55880, 'unimaginative', 3, '/ˌʌn.ɪˈmædʒ.ɪ.nə.tɪv/', 'dealing only with concrete facts', NULL),
(55881, 'impractical', 3, '/ɪmˈpræk.tɪ.kəl/', 'not practical; not workable or not given to practical matters', '\"refloating the ship proved impractical because of the expense\"; \"he is intelligent but too impractical for commercial work\"; \"an impractical solution\"'),
(55882, 'quixotic', 3, '/kwɪkˈsɒt.ɪk/', 'not sensible about practical matters; idealistic and unrealistic', '\"as quixotic as a restoration of medieval knighthood\"; \"a romantic disregard for money\"; \"a wild-eyed dream of a world state\"'),
(55883, 'unwieldy', 3, '/ʌnˈwiːl.di/', 'difficult to work or manipulate', '\"unwieldy rules and regulations\"'),
(55884, 'unwieldy', 3, '/ʌnˈwiːl.di/', 'difficult to use or handle or manage because of size or weight or shape', '\"we set about towing the unwieldy structure into the shelter\"; \"almost dropped the unwieldy parcel\"'),
(55885, 'precise', 3, '/prɪˈsaɪs/', 'sharply exact or accurate or delimited', '\"a precise mind\"; \"specified a precise amount\"; \"arrived at the precise moment\"'),
(55886, 'imprecise', 3, '/ˌɪm.prɪˈsaɪs/', 'not precise', '\"imprecise astronomical observations\"; \"the terms he used were imprecise and emotional\"'),
(55888, 'imbecile', 3, '/ˈɪm.bə.saɪl/', 'having a mental age of three to seven years', NULL),
(55889, 'moronic', 3, '/məˈrɒn.ɪk/', 'having a mental age of between eight and twelve years', NULL),
(55890, 'cretinous', 3, '/ˈkret.ɪ.nəs/', 'afflicted with cretinism', NULL),
(55891, 'delayed', 3, '/dɪˈleɪd/', 'not as far along as normal in development', NULL),
(55892, 'predictable', 3, '/prɪˈdɪk.tə.bəl/', 'capable of being foretold', NULL),
(55893, 'foreseeable', 3, '/fɔːˈsiː.ə.bəl/', 'capable of being anticipated', '\"foreseeable costs were well within the budget\"'),
(55894, 'aleatory', 3, '/ˈæl.i.ə.tər.i/', 'dependent on chance', '\"the aleatory element in life\"'),
(55895, 'unforeseeable', 3, '/ˌʌn.fɔːˈsiː.ə.bəl/', 'incapable of being anticipated', '\"unforeseeable consequences\"'),
(55896, 'premeditated', 3, '/ˌpriːˈmed.ɪ.teɪ.tɪd/', 'characterized by deliberate purpose and some degree of planning', '\"a premeditated crime\"'),
(55897, 'impulsive', 3, '/ɪmˈpʌl.sɪv/', 'without forethought', '\"letting him borrow her car was an impulsive act that she immediately regretted\"'),
(55898, 'impulsive', 3, '/ɪmˈpʌl.sɪv/', 'proceeding from natural feeling or impulse without external stimulus', '\"an impulsive gesture of affection\"'),
(55899, 'braced', 3, '/breɪst/', 'positioned so as to be ready for confrontation or danger', '\"he stood to attention with his shoulders braced\"'),
(55900, 'braced', 3, '/breɪst/', 'held up by braces or buttresses', NULL),
(55901, 'preconditioned', 3, '/ˌpriː.kənˈdɪʃ.ənd/', 'having already been put into a suitable condition', '\"a surface preconditioned to receive paint\"; \"customers preconditioned to buy a product\"'),
(55902, 'precooked', 3, '/ˌpriːˈkʊkt/', 'cooked partially or completely beforehand', '\"frozen precooked meals from the supermarket\"'),
(55903, 'processed', 3, '/ˈprəʊ.sest/', 'subjected to a special process or treatment', '\"prepared ergot\"; \"processed cheeses are easy to spread\"'),
(55904, 'processed', 3, '/ˈprəʊ.sest/', 'prepared or converted from a natural state by subjecting to a special process', '\"processed ores\"'),
(55905, 'unprepared', 3, '/ˌʌn.prɪˈpeəd/', 'without preparation; not prepared for; \"our treaty makers approached their immensely difficult problems unprepared\"- R.E.Danielson', '\"unprepared remarks\"; \"the shock was unprepared\"'),
(55906, 'omnipresent', 3, '/ˌɒm.nɪˈprez.ənt/', 'being present everywhere at once', NULL),
(55907, 'ostentatious', 3, '/ˌɒs.tenˈteɪ.ʃəs/', 'intended to attract notice and impress others', '\"an ostentatious sable coat\"'),
(55908, 'ostentatious', 3, '/ˌɒs.tenˈteɪ.ʃəs/', '(of a display) tawdry or vulgar', NULL),
(55909, 'flamboyant', 3, '/flæmˈbɔɪ.ənt/', 'marked by ostentation but often tasteless', '\"a cheap showy rhinestone bracelet\"; \"a splashy half-page ad\"'),
(55910, 'unostentatious', 3, '/ˌʌn.ɒs.tenˈteɪ.ʃəs/', 'not ostentatious', '\"his unostentatious office\"; \"unostentatious elegance\"'),
(55911, 'pretentious', 3, '/prɪˈten.ʃəs/', 'making claim to or creating an appearance of (often undeserved) importance or distinction', '\"a pretentious country house\"; \"a pretentious fraud\"; \"a pretentious scholarly edition\"'),
(55912, 'arty', 3, '/ˈɑː.ti/', 'showily imitative of art or artists', NULL),
(55913, 'grandiloquent', 3, '/ˌɡrænˈdɪl.ə.kwənt/', 'puffed up with vanity; \"pseudo-scientific gobbledygook and pontifical hooey\"- Newsweek', '\"a grandiloquent and boastful manner\"; \"overblown oratory\"; \"a pompous speech\"'),
(55914, 'grandiloquent', 3, '/ˌɡrænˈdɪl.ə.kwənt/', 'lofty in style', '\"he engages in so much tall talk, one never really realizes what he is saying\"');
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(55915, 'sententious', 3, '/senˈten.ʃəs/', 'abounding in or given to pompous or aphoristic moralizing; \"too often the significant episode deteriorates into sententious conversation\"- Kathleen Barnes', NULL),
(55916, 'unpretentious', 3, '/ˌʌn.prɪˈten.ʃəs/', 'lacking pretension or affectation', '\"an unpretentious country church\"; \"her quiet unpretentious demeanor\"'),
(55917, 'firsthand', 3, '/ˌfɜːstˈhænd/', 'received directly from a source', '\"firsthand information\"'),
(55918, 'firsthand', 4, '/ˌfɜːstˈhænd/', 'from the original source; directly', '\"I heard this story firsthand\"'),
(55919, 'auxiliary', 3, '/ɔːɡˈzɪl.i.ər.i/', 'functioning in a supporting capacity', '\"the main library and its auxiliary branches\"'),
(55920, 'thirdhand', 3, '/ˌθɜːdˈhænd/', 'derived from what is primary or original by two intermediate steps', '\"a thirdhand report\"'),
(55921, 'thirdhand', 4, '/ˌθɜːdˈhænd/', 'by doubly indirect means', '\"I got the news thirdhand\"'),
(55922, 'clannish', 3, '/ˈklæn.ɪʃ/', 'befitting or characteristic of those who incline to social exclusiveness and who rebuff the advances of people considered inferior', NULL),
(55923, 'clannish', 3, '/ˈklæn.ɪʃ/', 'characteristic of a clan especially in being unified', '\"clannish loyalty\"'),
(55924, 'cloistered', 3, '/ˈklɔɪ.stəd/', 'providing privacy or seclusion', '\"the cloistered academic world of books\"; \"sat close together in the sequestered pergola\"; \"sitting under the reclusive calm of a shade tree\"; \"a secluded romantic spot\"'),
(55925, 'cloistered', 3, '/ˈklɔɪ.stəd/', 'of communal life sequestered from the world under religious vows', NULL),
(55926, 'nonpublic', 3, '/ˌnɒnˈpʌb.lɪk/', 'not invested with or related to prominent position or status etc.', NULL),
(55927, 'privy', 3, '/ˈprɪv.i/', 'hidden from general view or use', '\"a privy place to rest and think\"; \"a secluded romantic spot\"; \"a secret garden\"'),
(55928, 'semiprivate', 3, '/ˌsem.iˈpraɪ.vət/', 'confined to a small number of hospital patients', '\"semiprivate room\"'),
(55929, 'inclusive', 3, '/ɪnˈkluː.sɪv/', 'including much or everything; and especially including stated limits', '\"an inclusive art form\"; \"an inclusive fee\"; \"his concept of history is modern and inclusive\"; \"from Monday to Friday inclusive\"'),
(55930, 'privileged', 3, '/ˈprɪv.əl.ɪdʒd/', 'blessed with privileges', '\"the privileged few\"'),
(55931, 'privileged', 3, '/ˈprɪv.əl.ɪdʒd/', 'not subject to usual rules or penalties', '\"a privileged statement\"'),
(55932, 'underprivileged', 3, '/ˌʌn.dəˈprɪv.əl.ɪdʒd/', 'lacking the rights and advantages of other members of society', NULL),
(55933, 'deprived', 3, '/dɪˈpraɪvd/', 'marked by deprivation especially of the necessities of life or healthful environmental influences', '\"a childhood that was unhappy and deprived, the family living off charity\"; \"boys from a deprived environment, wherein the family life revealed a pattern of neglect, moral degradation, and disregard for law\"'),
(55934, 'productive', 3, '/prəˈdʌk.tɪv/', 'producing or capable of producing (especially abundantly)', '\"productive farmland\"; \"his productive years\"; \"a productive collaboration\"'),
(55935, 'productive', 3, '/prəˈdʌk.tɪv/', 'yielding positive results', NULL),
(55936, 'arable', 3, '/ˈær.ə.bəl/', '(of farmland) capable of being farmed productively', NULL),
(55937, 'bootless', 3, '/ˈbuːt.ləs/', 'unproductive of success', '\"a fruitless search\"; \"futile years after her artistic peak\"; \"a sleeveless errand\"; \"a vain attempt\"'),
(55938, 'nonproductive', 3, '/ˌnɒn.prəˈdʌk.tɪv/', 'not directly productive', '\"nonproductive labor\"'),
(55939, 'exploitative', 3, '/ɪkˈsplɔɪ.tə.tɪv/', 'tending to exploit or make use of', NULL),
(55940, 'reproducible', 3, '/ˌriː.prəˈdʒuː.sə.bəl/', 'capable of being reproduced', '\"astonishingly reproducible results can be obtained\"'),
(55941, 'inimitable', 3, '/ɪˈnɪm.ɪ.tə.bəl/', 'defying imitation; matchless', '\"an inimitable style\"'),
(55942, 'unrepeatable', 3, '/ˌʌn.rɪˈpiː.tə.bəl/', 'unique; \"dogs and mice and flies are as unrepeatable as men are\"- Theodosius Dobzhansky', NULL),
(55943, 'unrepeatable', 3, '/ˌʌn.rɪˈpiː.tə.bəl/', 'not able or fit to be repeated or quoted', '\"what he said was funny but unquotable\"'),
(55944, 'nonprofessional', 3, '/ˌnɒn.prəˈfeʃ.ən.əl/', 'not professional; not engaged in a profession or engaging in as a profession or for gain', '\"the nonprofessional wives of his male colleagues\"; \"nonprofessional actors\"'),
