(55946, 'amateurish', 3, '/ˈæm.ə.tər.ɪʃ/', 'lacking professional skill or expertise', '\"a very amateurish job\"; \"inexpert but conscientious efforts\"; \"an unskilled painting\"'),
(55947, 'profitable', 3, '/ˈprɒf.ɪ.tə.bəl/', 'yielding material gain or profit', '\"profitable speculation on the stock market\"'),
(55948, 'gainful', 3, '/ˈɡeɪn.fəl/', 'yielding a fair profit', NULL),
(55949, 'lucrative', 3, '/ˈluː.krə.tɪv/', 'producing a sizeable profit', '\"a remunerative business\"'),
(55950, 'unprofitable', 3, '/ʌnˈprɒf.ɪ.tə.bəl/', 'producing little or no profit or gain', '\"deposits abandoned by mining companies as unprofitable\"'),
(55951, 'marginal', 3, '/ˈmɑː.dʒɪ.nəl/', 'producing at a rate that barely covers production costs', '\"marginal industries\"'),
(55952, 'superficial', 3, '/ˌsuː.pəˈfɪʃ.əl/', 'concerned with or comprehending only what is apparent or obvious; not deep or penetrating emotionally or intellectually', '\"superficial similarities\"; \"a superficial mind\"; \"his thinking was superficial and fuzzy\"; \"superficial knowledge\"; \"the superficial report didn\'t give the true picture\"; \"only superficial differences\"'),
(55953, 'superficial', 3, '/ˌsuː.pəˈfɪʃ.əl/', 'of little substance or significance', '\"a few superficial editorial changes\"; \"only trivial objections\"'),
(55954, 'superficial', 3, '/ˌsuː.pəˈfɪʃ.əl/', 'of, affecting, or being on or near the surface', '\"superficial measurements\"; \"the superficial area of the wall\"; \"a superficial wound\"'),
(55955, 'dilettante', 3, '/ˌdɪl.əˈtɑːnt/', 'showing frivolous or superficial interest; amateurish', '\"his dilettantish efforts at painting\"'),
(55956, 'chinless', 3, '/ˈtʃɪn.ləs/', 'having a receding chin', NULL),
(55957, 'advancing', 3, '/ədˈvɑːn.sɪŋ/', 'moving forward', NULL),
(55958, 'modernized', 3, '/ˈmɒd.ə.naɪzd/', 'brought up to date', '\"modernized methods\"'),
(55959, 'regressive', 3, '/rɪˈɡres.ɪv/', 'opposing progress; returning to a former less advanced state', NULL),
(55960, 'regressive', 3, '/rɪˈɡres.ɪv/', '(of taxes) adjusted so that the rate decreases as the amount of income increases', NULL),
(55961, 'atavistic', 3, '/ˌæt.əˈvɪs.tɪk/', 'characteristic of an atavist', NULL),
(55962, 'returning', 3, '/rɪˈtɜː.nɪŋ/', 'tending to return to an earlier state', NULL),
(55963, 'pronounceable', 3, '/prəˈnaʊn.sə.bəl/', 'capable of being uttered or pronounced', '\"a pronounceable group of letters\"'),
(55964, 'rolled', 3, '/rəʊld/', 'uttered with a trill', '\"she used rolling r\'s as in Spanish\"'),
(55965, 'priggish', 3, '/ˈprɪɡ.ɪʃ/', 'exaggeratedly proper', '\"my straitlaced Aunt Anna doesn\'t approve of my miniskirts\"'),
(55966, 'prophetic', 3, '/prəˈfet.ɪk/', 'foretelling events as if by supernatural intervention', '\"prophetic writings\"; \"prophetic powers\"; \"words that proved prophetic\"'),
(55967, 'apocalyptic', 3, '/əˌpɒk.əˈlɪp.tɪk/', 'prophetic of devastation or ultimate doom', NULL),
(55968, 'apocalyptic', 3, '/əˌpɒk.əˈlɪp.tɪk/', 'of or relating to an apocalypse', NULL),
(55969, 'divinatory', 3, '/dɪˈvɪn.ə.tər.i/', 'resembling or characteristic of a prophet or prophecy', '\"the high priest\'s divinatory pronouncement\"; \"mantic powers\"; \"a kind of sibylline book with ready and infallible answers to questions\"'),
(55970, 'precursory', 3, '/prɪˈkɜː.sər.i/', 'warning of future misfortune', NULL),
(55971, 'predictive', 3, '/prɪˈdɪk.tɪv/', 'of or relating to prediction; having value for making predictions', NULL),
(55972, 'prospective', 3, '/prəˈspek.tɪv/', 'of or concerned with or related to the future', '\"prospective earnings\"; \"a prospective mother\"; \"a prospective bride\"; \"the statute is solely prospective in operation\"'),
(55973, 'bastioned', 3, '/ˈbæs.ti.ənd/', 'secured with bastions or fortifications', NULL),
(55974, 'battlemented', 3, '/ˈbæt.əl.mən.tɪd/', 'protected with battlements or parapets with indentations or embrasures for shooting through', NULL),
(55975, 'moated', 3, '/ˈməʊ.tɪd/', 'protected by a deep wide ditch usually filled with water', NULL),
(55976, 'shielded', 3, '/ˈʃiːl.dɪd/', '(used especially of machinery) protected by a shield to prevent injury', NULL),
(55977, 'stormproof', 3, '/ˈstɔːm.pruːf/', 'protected against or able to withstand storms', NULL),
(55978, 'unprotected', 3, '/ˌʌn.prəˈtek.tɪd/', 'lacking protection or defense', NULL),
(55979, 'unshielded', 3, '/ʌnˈʃiːl.dɪd/', '(used especially of machinery) not protected by a shield', NULL),
(55980, 'protective', 3, '/prəˈtek.tɪv/', 'intended or adapted to afford protection of some kind', '\"a protective covering\"; \"the use of protective masks and equipment\"; \"protective coatings\"; \"kept the drunken sailor in protective custody\"; \"animals with protective coloring\"; \"protective tariffs\"'),
(55981, 'protective', 3, '/prəˈtek.tɪv/', 'showing care', '\"a protective mother\"'),
(55982, 'cautionary', 3, '/ˈkɔː.ʃən.ər.i/', 'warding off; \"the swastika...a very ancient prophylactic symbol occurring among all peoples\"- Victor Schultze', NULL),
(55983, 'custodial', 3, '/kʌsˈtəʊ.di.əl/', 'providing protective supervision; watching over or safeguarding', '\"daycare that is educational and not just custodial\"; \"a guardian angel\"; \"tutelary gods\"'),
(55984, 'overprotective', 3, '/ˌəʊ.və.prəˈtek.tɪv/', 'overly protective', '\"overprotective parents\"'),
(55985, 'restrictive', 3, '/rɪˈstrɪk.tɪv/', '(of tariff) protective of national interests by restricting imports', NULL),
(55986, 'restrictive', 3, '/rɪˈstrɪk.tɪv/', 'serving to restrict', '\"teenagers eager to escape restrictive home environments\"'),
(55987, 'proud', 3, '/praʊd/', 'feeling self-respect or pleasure in something by which you measure your self-worth; or being a reason for pride', '\"proud parents\"; \"proud of his accomplishments\"; \"a proud moment\"; \"proud to serve his country\"; \"a proud name\"; \"proud princes\"'),
(55988, 'arrogant', 3, '/ˈær.ə.ɡənt/', 'having or showing feelings of unwarranted importance out of overbearing pride', '\"an arrogant official\"; \"arrogant claims\"; \"chesty as a peacock\"'),
(55989, 'bigheaded', 3, '/ˈbɪɡˌhed.ɪd/', '(used colloquially) overly conceited or arrogant; \"a snotty little scion of a degenerate family\"-Laurent Le Sage', '\"they\'re snobs--stuck-up and uppity and persnickety\"'),
(55990, 'boastful', 3, '/ˈbəʊst.fəl/', 'exhibiting self-importance', '\"big talk\"'),
(55991, 'disdainful', 3, '/dɪsˈdeɪn.fəl/', 'having or showing arrogant superiority to and disdain of those one views as unworthy; \"a more swaggering mood than usual\"- W.L.Shirer', '\"some economists are disdainful of their colleagues in other social disciplines\"; \"haughty aristocrats\"; \"his lordly manners were offensive\"; \"walked with a prideful swagger\"; \"very sniffy about breaches of etiquette\"; \"his mother eyed my clothes with a supercilious air\"'),
(55992, 'conceited', 3, '/kənˈsiː.tɪd/', 'characteristic of false pride; having an exaggerated sense of self-importance', '\"a conceited fool\"; \"an attitude of self-conceited arrogance\"; \"an egotistical disregard of others\"; \"so swollen by victory that he was unfit for normal duty\"; \"growing ever more swollen-headed and arbitrary\"; \"vain about her clothes\"'),
(55993, 'proved', 3, '/pruːvd/', 'established beyond doubt', '\"a proven liar\"; \"a Soviet leader of proven shrewdness\"'),
(55994, 'evidenced', 3, '/ˈev.ɪ.dənst/', 'supported by evidence', '\"their evidenced friendliness to the US\"'),
(55995, 'verified', 3, '/ˈver.ɪ.faɪd/', 'proved to be true', '\"a verified claim\"'),
(55996, 'unproved', 3, '/ʌnˈpruːvd/', 'not proved', '\"unproved allegations\"; \"unproved assumptions\"'),
(55997, 'unverified', 3, '/ʌnˈver.ɪ.faɪd/', 'lacking proof or substantiation', NULL),
(55998, 'provident', 3, '/ˈprɒv.ɪ.dənt/', 'providing carefully for the future', '\"wild squirrels are provident\"; \"a provident father plans for his children\'s education\"'),
(55999, 'provident', 3, '/ˈprɒv.ɪ.dənt/', 'careful in regard to your own interests', '\"the prudent use and development of resources\"; \"wild squirrels are provident\"'),
(56000, 'improvident', 3, '/ɪmˈprɒv.ɪ.dənt/', 'not provident; not providing for the future', NULL),
(56001, 'provocative', 3, '/prəˈvɒk.ə.tɪv/', 'serving or tending to provoke, excite, or stimulate; stimulating discussion or exciting controversy; \"provocative Irish tunes which...compel the hearers to dance\"- Anthony Trollope', '\"a provocative remark\"; \"a provocative smile\"'),
(56002, 'provocative', 3, '/prəˈvɒk.ə.tɪv/', 'exciting sexual desire', '\"her gestures and postures became more wanton and provocative\"'),
(56003, 'challenging', 3, '/ˈtʃæl.ɪn.dʒɪŋ/', 'disturbingly provocative', '\"an intriguing smile\"'),
(56004, 'challenging', 3, '/ˈtʃæl.ɪn.dʒɪŋ/', 'stimulating interest or thought', '\"a challenging hypothesis\"; \"a thought-provoking book\"'),
(56005, 'rousing', 3, '/ˈraʊ.zɪŋ/', 'rousing to activity or heightened action as by spurring or goading', '\"tossed a rousing political comment into the conversation\"'),
(56006, 'rousing', 3, '/ˈraʊ.zɪŋ/', 'capable of arousing enthusiasm or excitement', '\"a rousing sermon\"; \"stirring events such as wars and rescues\"'),
(56007, 'noninflammatory', 3, '/ˌnɒn.ɪnˈflæm.ə.tər.i/', 'not inflammatory', NULL),
