(56155, 'coarse', 3, '/kɔːs/', 'of low or inferior quality or value; \"of what coarse metal ye are molded\"- Shakespeare', '\"produced...the common cloths used by the poorer population\"'),
(56156, 'crass', 3, '/kræs/', '(of persons) so unrefined as to be lacking in discrimination and sensibility', NULL),
(56157, 'robust', 3, '/rəʊˈbʌst/', 'rough and crude', '\"a robust tale\"'),
(56158, 'robust', 3, '/rəʊˈbʌst/', 'sturdy and strong in form, constitution, or construction', '\"a robust body\"; \"a robust perennial\"'),
(56159, 'robust', 3, '/rəʊˈbʌst/', 'strong enough to withstand or overcome intellectual challenges or adversity', '\"the experiment yielded robust results\"; \"a robust faith\"'),
