(56166, 'treated', 3, '/ˈtriː.tɪd/', 'given medical care or treatment; \"a treated cold is usually gone in 14 days; if left untreated it lasts two weeks\"', NULL),
(56167, 'aerated', 3, '/ˈeə.reɪ.tɪd/', '(of a liquid) treated by having air passed or bubbled through it for purification', NULL),
