(56174, 'recoverable', 3, '/rɪˈkʌv.ər.ə.bəl/', 'capable of being recovered or regained', '\"recoverable truth of a past event\"'),
(56175, 'retrievable', 3, '/rɪˈtriː.və.bəl/', 'capable of being regained especially with effort', '\"he believed the information was retrievable\"'),
