(56192, 'irreparable', 3, '/ɪˈrep.ər.ə.bəl/', 'impossible to repair, rectify, or amend', '\"irreparable harm\"; \"an irreparable mistake\"; \"irreparable damages\"'),
(56193, 'repeatable', 3, '/rɪˈpiː.tə.bəl/', 'able or fit to be repeated or quoted', '\"what he said was not repeatable in polite company\"; \"he comes up with so many quotable phrases\"'),
