(56197, 'requested', 3, '/rɪˈkwes.tɪd/', 'asked for', '\"the requested aid is forthcoming\"'),
(56198, 'unrequested', 3, '/ˌʌn.rɪˈkwes.tɪd/', 'not requested', '\"the merchandise was unrequested\"'),
(56199, 'unasked', 3, '/ʌnˈɑːskt/', 'not asked for', '\"unasked advice\"; \"unsolicited junk mail\"'),
(56200, 'rhymed', 3, '/raɪmd/', 'having corresponding sounds especially terminal sounds', '\"rhymed verse\"; \"rhyming words\"'),
(56201, 'alliterative', 3, '/əˈlɪt.ər.ə.tɪv/', 'having the same consonant at the beginning of each stressed syllable', '\"alliterative verse\"'),
(56202, 'unrhymed', 3, '/ʌnˈraɪmd/', 'not having rhyme', '\"writing unrhymed blank verse is like playing tennis without a net\"'),
(56203, 'multiform', 3, '/ˈmʌl.tɪ.fɔːm/', 'occurring in or having many forms or shapes or appearances; \"the multiform universe of nature and man\"- John Dewey', NULL),
(56204, 'polymorphic', 3, '/ˌpɒl.iˈmɔː.fɪk/', 'having or occurring in several distinct forms', '\"man is both polymorphic and polytypic\"; \"a polymorphous god\"'),
(56205, 'polymorphic', 3, '/ˌpɒl.iˈmɔː.fɪk/', 'relating to the occurrence of more than one kind of individual (independent of sexual differences) in an interbreeding population', '\"a polymorphic species\"'),
(56206, 'oscillatory', 3, '/əˈsɪl.ə.tər.i/', 'having periodic vibrations', NULL),
(56207, 'nightly', 3, '/ˈnaɪt.li/', 'happening every night', '\"nightly television now goes on until 3:00 or 4:00 a.m.\"'),
