(56246, 'reputable', 3, '/ˈrep.jʊ.tə.bəl/', 'having a good reputation', '\"a reputable business\"; \"a reputable scientist\"; \"a reputable wine\"'),
(56247, 'esteemed', 3, '/ɪˈstiːmd/', 'having an illustrious reputation; respected', '\"our esteemed leader\"; \"a prestigious author\"'),
(56248, 'redoubtable', 3, '/rɪˈdaʊ.tə.bəl/', 'worthy of respect or honor', '\"born of a redoubtable family\"'),
(56249, 'respected', 3, '/rɪˈspek.tɪd/', 'receiving deferential regard', '\"a respected family\"'),
(56250, 'disreputable', 3, '/dɪsˈrep.jʊ.tə.bəl/', 'lacking respectability in character or behavior or appearance', NULL),
(56251, 'discreditable', 3, '/dɪsˈkred.ɪ.tə.bəl/', 'tending to bring discredit or disrepute; blameworthy', '\"his marks were not at all discreditable\"'),
(56252, 'louche', 3, '/luːʃ/', 'of questionable taste or morality', '\"a louche nightclub\"; \"a louche painting\"'),
(56253, 'seamy', 3, '/ˈsiː.mi/', 'morally degraded; \"sleazy storefronts with...dirt on the walls\"- Seattle Weekly; \"the sordid details of his orgies stank under his very nostrils\"- James Joyce', '\"a seedy district\"; \"the seamy side of life\"; \"sleazy characters hanging around casinos\"; \"the squalid atmosphere of intrigue and betrayal\"'),
