(56294, 'trustworthy', 3, '/ˈtrʌstˌwɜː.ði/', 'taking responsibility for one\'s conduct and obligations', '\"trustworthy public servants\"'),
(56295, 'trustworthy', 3, '/ˈtrʌstˌwɜː.ði/', 'worthy of trust or belief', '\"a trustworthy report\"; \"an experienced and trustworthy traveling companion\"'),
(56296, 'irresponsible', 3, '/ˌɪr.ɪˈspɒn.sə.bəl/', 'showing lack of care for consequences', '\"behaved like an irresponsible idiot\"; \"hasty and irresponsible action\"'),
(56297, 'carefree', 3, '/ˈkeə.friː/', 'cheerfully irresponsible', '\"carefree with his money\"; \"freewheeling urban youths\"; \"had a harum-scarum youth\"'),
(56298, 'carefree', 3, '/ˈkeə.friː/', 'free of trouble and worry and care', '\"the carefree joys of childhood\"; \"carefree millionaires, untroubled financially\"'),
