(56949, 'syllabic', 3, '/sɪˈlæb.ɪk/', 'consisting of or using a syllabary', '\"eskimos of the eastern Arctic have a system of syllabic writing\"'),
(56950, 'syllabic', 3, '/sɪˈlæb.ɪk/', 'of or relating to syllables', '\"syllabic accent\"; \"syllabic characters each represent a syllable\"'),
(56951, 'disyllabic', 3, '/ˌdaɪ.sɪˈlæb.ɪk/', 'having or characterized by or consisting of two syllables', NULL),
(56952, 'monosyllabic', 3, '/ˌmɒn.ə.sɪˈlæb.ɪk/', 'having or characterized by or consisting of one syllable', NULL),
(56953, 'octosyllabic', 3, '/ˌɒk.təʊ.sɪˈlæb.ɪk/', 'having or characterized by or consisting of eight syllables', NULL),
(56954, 'accentual', 3, '/əkˈsen.tʃu.əl/', '(of verse) having a metric system based on stress rather than syllables or quantity', '\"accentual poetry is based on the number of stresses in a line\"; \"accentual rhythm\"'),
(56955, 'accentual', 3, '/əkˈsen.tʃu.əl/', 'of or pertaining to accent or stress', NULL),
(56956, 'lasting', 3, '/ˈlɑː.stɪŋ/', 'lasting a long time without change', '\"a lasting relationship\"'),
(56957, 'stabilized', 3, '/ˈsteɪ.bəl.aɪzd/', 'made stable or firm', NULL),
(56958, 'rickety', 3, '/ˈrɪk.ə.ti/', 'inclined to shake as from weakness or defect', '\"a rickety table\"; \"a wobbly chair with shaky legs\"; \"the ladder felt a little wobbly\"; \"the bridge still stands though one of the arches is wonky\"'),
(56959, 'rickety', 3, '/ˈrɪk.ə.ti/', 'affected with, suffering from, or characteristic of rickets', '\"rickety limbs and joints\"; \"a rachitic patient\"'),
(56960, 'seismic', 3, '/ˈsaɪz.mɪk/', 'subject to or caused by an earthquake or earth vibration', NULL),
(56961, 'tipsy', 3, '/ˈtɪp.si/', 'unstable and prone to tip as if intoxicated', '\"a tipsy boat\"'),
(56962, 'tottering', 3, '/ˈtɒt.ər.ɪŋ/', '(of structures or institutions) having lost stability; failing or on the point of collapse', '\"a tottering empire\"'),
(56963, 'tottering', 3, '/ˈtɒt.ər.ɪŋ/', 'unsteady in gait as from infirmity or old age', '\"a tottering skeleton of a horse\"; \"a tottery old man\"'),
(56964, 'staccato', 3, '/stəˈkɑː.təʊ/', '(music) marked by or composed of disconnected parts or sounds; cut short crisply', '\"staccato applause\"; \"a staccato command\"; \"staccato notes\"'),
(56965, 'staccato', 4, '/stəˈkɑː.təʊ/', 'separating the notes; in music', '\"play this staccato, please\"'),
(56966, 'legato', 3, '/ləˈɡɑː.təʊ/', '(music) without breaks between notes; smooth and connected', '\"a legato passage\"'),
(56967, 'legato', 4, '/ləˈɡɑː.təʊ/', 'connecting the notes; in music', '\"play this legato, please\"'),
(56968, 'staged', 3, '/steɪdʒd/', 'written for or performed on the stage', '\"a staged version of the novel\"'),
(56969, 'unstaged', 3, '/ʌnˈsteɪdʒd/', 'not performed on the stage', NULL),
(56970, 'unperformed', 3, '/ˌʌn.pəˈfɔːmd/', 'not performed', '\"the author of numerous unperformed plays\"'),
(56971, 'nonstandard', 3, '/ˌnɒnˈstæn.dəd/', 'not standard; not accepted as a model of excellence', '\"a nonstandard text\"'),
(56972, 'nonstandard', 3, '/ˌnɒnˈstæn.dəd/', 'varying from or not adhering to a standard', '\"nonstandard windows\"; \"envelopes of nonstandard sizes\"; \"nonstandard lengths of board\"'),
(56973, 'nonstandard', 3, '/ˌnɒnˈstæn.dəd/', 'not conforming to the language usage of a prestige group within a community; \"the common core of nonstandard words and phrases in folk speech\"- A.R.Dunlap', '\"a nonstandard dialect is one used by uneducated speakers or socially disfavored groups\"'),
(56974, 'modular', 3, '/ˈmɒdʒ.ʊ.lər/', 'constructed with standardized units or dimensions allowing flexibility and variety in use', '\"modular furniture\"; \"modular homes\"'),
(56975, 'standardized', 3, '/ˈstæn.də.daɪzd/', 'brought into conformity with a standard', '\"standardized education\"'),
(56976, 'starry', 3, '/ˈstɑː.ri/', 'abounding with or resembling stars', '\"a starry night\"; \"starry illumination\"'),
(56977, 'starlike', 3, '/ˈstɑː.laɪk/', 'resembling a star', '\"they saw a starlike object in the sky\"'),
(56978, 'starlit', 3, '/ˈstɑː.lɪt/', 'lighted only by stars', '\"the starlit darkness\"'),
(56979, 'starless', 3, '/ˈstɑː.ləs/', 'not starry; having no stars or starlike objects', '\"dark starless nights\"'),
(56980, 'nourished', 3, '/ˈnʌr.ɪʃt/', 'being provided with adequate nourishment', NULL),
(56981, 'overfed', 3, '/ˌəʊ.vəˈfed/', 'too well nourished', NULL),
(56982, 'malnourished', 3, '/ˌmælˈnʌr.ɪʃt/', 'not being provided with adequate nourishment', NULL),
(56983, 'foodless', 3, '/ˈfuːd.ləs/', 'being without food', NULL),
(56984, 'starved', 3, '/stɑːvd/', 'suffering from lack of food', NULL),
(56985, 'steadied', 3, '/ˈsted.id/', 'made steady or constant', '\"the noise became a steadied roaring\"'),
(56986, 'surefooted', 3, '/ˌʃɔːˈfʊt.ɪd/', 'not liable to stumble or fall', '\"on surefooted donkeys\"'),
(56987, 'unsteady', 3, '/ʌnˈsted.i/', 'subject to change or variation', '\"her unsteady walk\"; \"his hand was unsteady as he poured the wine\"; \"an unsteady voice\"'),
(56988, 'convulsive', 3, '/kənˈvʌl.sɪv/', 'affected by involuntary jerky muscular contractions; resembling a spasm', '\"convulsive motions\"; \"his body made a spasmodic jerk\"; \"spastic movements\"'),
(56989, 'convulsive', 3, '/kənˈvʌl.sɪv/', 'resembling a convulsion in being sudden and violent', '\"a convulsive rage\"; \"convulsive laughter\"'),
(56990, 'faltering', 3, '/ˈfɒl.tər.ɪŋ/', 'unsteady in speech or action', NULL),
(56991, 'flickering', 3, '/ˈflɪk.ər.ɪŋ/', 'shining unsteadily', NULL),
(56992, 'fluctuating', 3, '/ˈflʌk.tʃu.eɪ.tɪŋ/', 'having unpredictable ups and downs', '\"fluctuating prices\"'),
(56993, 'shaky', 3, '/ˈʃeɪ.ki/', 'vibrating slightly and irregularly; as e.g. with fear or cold or like the leaves of an aspen in a breeze', '\"a quaking bog\"; \"the quaking child asked for more\"; \"quivering leaves of a poplar tree\"; \"with shaking knees\"; \"seemed shaky on her feet\"; \"sparkling light from the shivering crystals of the chandelier\"; \"trembling hands\"'),
(56994, 'quavering', 3, '/ˈkweɪ.vər.ɪŋ/', '(of the voice) quivering as from weakness or fear', '\"the old lady\'s quavering voice\"; \"spoke timidly in a tremulous voice\"'),
(56995, 'shuddering', 3, '/ˈʃʌd.ər.ɪŋ/', 'shaking convulsively or violently', NULL),
(56996, 'wobbling', 3, '/ˈwɒb.lɪŋ/', '(of sound) fluctuating unsteadily', '\"a low-pitched wobbling sound\"'),
(56997, 'stemmed', 3, '/stemd/', 'having a stem or stems or having a stem as specified; often used in combination', '\"stemmed goblets\"; \"long-stemmed roses\"'),
(56998, 'stemmed', 3, '/stemd/', 'having the stem removed', '\"stemmed berries\"'),
(56999, 'stemless', 3, '/ˈstem.ləs/', 'not having a stem', '\"stemless glassware\"'),
(57000, 'stimulating', 3, '/ˈstɪmjəˌleɪtɪŋ/', 'rousing or quickening activity or the senses', '\"a stimulating discussion\"'),
(57001, 'piquant', 3, '/ˈpiːkɑːnt/', 'engagingly stimulating or provocative', '\"a piquant wit\"; \"salty language\"'),
(57002, 'piquant', 3, '/ˈpiːkɑːnt/', 'having an agreeably pungent taste', NULL),
(57003, 'thrilling', 3, '/ˈθrɪlɪŋ/', 'causing quivering or shivering as by cold or fear or electric shock', '\"a thrilling wind blew off the frozen lake\"'),
(57004, 'bland', 3, '/blænd/', 'lacking stimulating characteristics; uninteresting', '\"a bland little drama\"; \"a flat joke\"'),
(57005, 'bland', 3, '/blænd/', 'lacking taste or flavor or tang', '\"a bland diet\"; \"insipid hospital food\"; \"flavorless supermarket tomatoes\"; \"vapid beer\"; \"vapid tea\"'),
(57006, 'vapid', 3, '/ˈvæpɪd/', 'lacking significance or liveliness or spirit or zest', '\"a vapid conversation\"; \"a vapid smile\"; \"a bunch of vapid schoolgirls\"'),
(57007, 'depressant', 3, '/dɪˈprɛsənt/', 'capable of depressing physiological or psychological activity or response by a chemical agent', NULL),
(57008, 'stimulative', 3, '/ˈstɪmjəˌleɪtɪv/', 'capable of arousing or accelerating physiological or psychological activity or response by a chemical agent', NULL),
(57009, 'adrenocorticotropic', 3, '/əˌdriːnoʊˌkɔːrtɪkoʊˈtroʊpɪk/', 'stimulating or acting on the adrenal cortex', NULL),
(57010, 'unbent', 3, '/ʌnˈbɛnt/', 'not bent', '\"looking for an unbent nail\"; \"trees with straight unbent trunks make the best lumber\"'),
(57011, 'untwisted', 3, '/ʌnˈtwɪstɪd/', 'not twisted; formerly twisted but now straight', NULL),
(57012, 'crooked', 3, '/ˈkrʊkɪd/', 'having or marked by bends or angles; not straight or aligned', '\"crooked country roads\"; \"crooked teeth\"'),
(57013, 'crooked', 3, '/ˈkrʊkɪd/', 'not straight; dishonest or immoral or evasive', NULL),
(57014, 'aquiline', 3, '/ˈæk.wə.laɪn/', 'curved down like an eagle\'s beak', NULL),
(57015, 'askew', 3, '/əˈskjuː/', 'turned or twisted toward one side; \"a...youth with a gorgeous red necktie all awry\"- G.K.Chesterton', '\"his wig was, as the British say, skew-whiff\"'),
(57016, 'askew', 4, '/əˈskjuː/', 'turned or twisted to one side', '\"rugs lying askew\"; \"with his necktie twisted awry\"'),
(57017, 'contorted', 3, '/kənˈtɔːrtɪd/', 'twisted (especially as in pain or struggle); \"my writhen features\"- Walter scott', '\"his mad contorted smile\"; \"writhed lips\"'),
(57018, 'deflective', 3, '/dɪˈflɛktɪv/', 'capable of changing the direction (of a light or sound wave)', NULL),
(57019, 'geniculate', 3, '/dʒəˈnɪkjəlɪt/', 'bent at a sharp angle', NULL),
(57020, 'gnarled', 3, '/nɑːrld/', 'used of old persons or old trees; covered with knobs or knots', '\"gnarled and knotted hands\"; \"a knobbed stick\"'),
(57021, 'reflexed', 3, '/ˈriː.flɛkst/', '(of leaves) bent downward and outward more than 90 degrees', NULL),
(57022, 'squiggly', 3, '/ˈskwɪɡli/', 'wavy and twisting', NULL),
(57023, 'warped', 3, '/wɔːrpt/', 'used especially of timbers or boards; bent out of shape usually by moisture', '\"the floors were warped and cracked\"'),
(57024, 'windblown', 3, '/ˈwɪndˌbloʊn/', 'used especially of trees; growing in a shape determined by the prevailing winds', NULL),
(57025, 'wry', 3, '/raɪ/', 'bent to one side', '\"a wry neck\"'),
(57026, 'curved', 3, '/kɜːrvd/', 'having or marked by a curve or smoothly rounded bend', '\"the curved tusks of a walrus\"; \"his curved lips suggested a smile but his eyes were hard\"'),
(57027, 'arced', 3, '/ɑːrkt/', 'forming or resembling an arch', '\"an arched ceiling\"'),
(57028, 'falcate', 3, '/ˈfæl.keɪt/', 'curved like a sickle', '\"a falcate leaf\"; \"falcate claws\"; \"the falcate moon\"'),
(57029, 'curvy', 3, '/ˈkɜːrvi/', 'having curves', '\"a settee with only one curvy end\"'),
(57030, 'flexuous', 3, '/ˈflɛkʃuəs/', 'having turns or windings', '\"the flexuous bed of the stream\"'),
(57031, 'recurved', 3, '/rɪˈkɜːrvd/', 'curved backward or inward', NULL),
(57032, 'semicircular', 3, '/ˌsɛmiˈsɜːrkjələr/', 'curved into a half circle', NULL),
(57033, 'serpentine', 3, '/ˈsɜːrpənˌtiːn/', 'resembling a serpent in form', '\"a serpentine wall\"; \"snaky ridges in the sand\"'),
(57034, 'sinusoidal', 3, '/ˌsaɪnəˈsɔɪdəl/', 'having a succession of waves or curves', NULL);
INSERT INTO `wordmeaning` (`WMID`, `WordV`, `POSID`, `Phonetic`, `Definition`, `Example`) VALUES
(57035, 'coiled', 3, '/kɔɪld/', 'curled or wound (especially in concentric rings or spirals)', '\"a coiled snake ready to strike\"; \"the rope lay coiled on the deck\"'),
