(57037, 'convolute', 3, '/ˈkɒnvəˌluːt/', 'rolled longitudinally upon itself', '\"a convolute petal\"'),
(57038, 'involute', 3, '/ˈɪnvəˌluːt/', '(of some shells) closely coiled so that the axis is obscured', NULL),
(57039, 'involute', 3, '/ˈɪnvəˌluːt/', 'especially of petals or leaves in bud; having margins rolled inward', NULL),
(57040, 'uncoiled', 3, '/ʌnˈkɔɪld/', 'no longer coiled', NULL),
(57041, 'aboveboard', 3, '/əˈbʌvˌbɔːrd/', 'without concealment or deception; honest', '\"their business was open and aboveboard\"; \"straightforward in all his business affairs\"'),
(57042, 'guileless', 3, '/ˈɡaɪlləs/', 'free of deceit', NULL),
(57043, 'sneaky', 3, '/ˈsniːki/', 'marked by deception', '\"achieved success in business only by underhand methods\"'),
(57044, 'stressed', 3, '/strɛst/', 'bearing a stress or accent', '\"an iambic foot consists of an unstressed syllable followed by a stressed syllable as in `delay\'\"'),
(57045, 'stressed', 3, '/strɛst/', 'suffering severe physical strain or distress', '\"he dropped out of the race, clearly distressed and having difficulty breathing\"'),
(57046, 'unstressed', 3, '/ʌnˈstrɛst/', 'not bearing a stress or accent', '\"short vowels are unstressed\"'),
(57047, 'unaccented', 3, '/ˌʌnækˈsɛntɪd/', '(used of vowels or syllables) pronounced with little or no stress', '\"a syllable that ends in a short vowel is a light syllable\"; \"a weak stress on the second syllable\"'),
