(57049, 'atonic', 3, '/əˈtɒnɪk/', 'characterized by a lack of tonus', NULL),
(57050, 'brawny', 3, '/ˈbrɔːni/', '(of a person) possessing physical strength and weight; rugged and powerful', '\"a hefty athlete\"; \"a muscular boxer\"; \"powerful arms\"'),
(57051, 'fortified', 3, '/ˈfɔːrtɪˌfaɪd/', 'having something added to increase the strength', '\"fortified wine\"'),
(57052, 'reinforced', 3, '/ˌriːɪnˈfɔːrst/', 'given added strength or support', '\"reinforced concrete contains steel bars or metal netting\"'),
(57053, 'vehement', 3, '/ˈviːəmənt/', 'characterized by great force or energy', '\"vehement deluges of rain\"; \"vehement clapping\"; \"a vehement defense\"'),
(57054, 'virile', 3, '/ˈvɪrəl/', 'characterized by energy and vigor', '\"a virile and ever stronger free society\"; \"a new and virile leadership\"'),
(57055, 'anemic', 3, '/əˈniːmɪk/', 'lacking vigor or energy', '\"an anemic attempt to hit the baseball\"'),
(57056, 'anemic', 3, '/əˈniːmɪk/', 'relating to anemia or suffering from anemia', NULL),
(57057, 'vulnerable', 3, '/ˈvʌlnərəbəl/', 'capable of being wounded or hurt', '\"vulnerable parts of the body\"'),
(57058, 'vulnerable', 3, '/ˈvʌlnərəbəl/', 'susceptible to criticism or persuasion or temptation', '\"vulnerable to bribery\"; \"an argument vulnerable to refutation\"'),
(57059, 'vulnerable', 3, '/ˈvʌlnərəbəl/', 'susceptible to attack', '\"a vulnerable bridge\"'),
(57060, 'weakened', 3, '/ˈwiːkənd/', 'made weak or weaker', NULL),
(57061, 'stubborn', 3, '/ˈstʌbərn/', 'tenaciously unwilling or marked by tenacious unwillingness to yield', NULL),
(57062, 'bolshy', 3, '/ˈbɒlʃi/', 'obstreperous', NULL),
(57063, 'bullheaded', 3, '/ˈbʊlˌhɛdɪd/', 'obstinate and stupid', NULL),
(57064, 'dogged', 3, '/ˈdɔːɡɪd/', 'stubbornly unyielding; \"a mind not gifted to discover truth but tenacious to hold it\"- T.S.Eliot', '\"dogged persistence\"; \"dour determination\"; \"the most vocal and pertinacious of all the critics\"; \"men tenacious of opinion\"'),
(57065, 'docile', 3, '/ˈdoʊsaɪl/', 'willing to be taught or led or supervised or directed', '\"the docile masses of an enslaved nation\"'),
(57066, 'docile', 3, '/ˈdoʊsaɪl/', 'easily handled or managed', '\"a gentle old horse, docile and obedient\"'),
(57067, 'docile', 3, '/ˈdoʊsaɪl/', 'ready and willing to be taught', '\"docile pupils eager for instruction\"; \"teachable youngsters\"'),
(57068, 'feudatory', 3, '/ˈfjuːdətɔːri/', 'owing feudal allegiance to or being subject to a sovereign', '\"it remained feudatory to India until 1365\"'),
(57069, 'feudatory', 3, '/ˈfjuːdətɔːri/', 'of or pertaining to the relation of a feudal vassal to his lord', '\"a feudatory relationship\"'),
(57070, 'ruled', 3, '/ruːld/', 'subject to a ruling authority', '\"the ruled mass\"'),
(57071, 'subservient', 3, '/səbˈsɜːrviənt/', 'compliant and obedient to authority; \"editors and journalists who express opinions in print that are opposed to the interests of the rich are dismissed and replaced by subservient ones\"-G. B. Shaw', NULL),
(57072, 'contumacious', 3, '/ˌkɒntjuˈmeɪʃəs/', 'wilfully obstinate; stubbornly disobedient', '\"a contumaceous witness is subject to punishment\"'),
(57073, 'successful', 3, '/səkˈsɛsfəl/', 'having succeeded or being marked by a favorable outcome', '\"a successful architect\"; \"a successful business venture\"'),
(57074, 'boffo', 3, '/ˈbɒfoʊ/', 'resoundingly successful and popular', '\"for years he was a boffo box office certainty\"'),
(57075, 'victorious', 3, '/vɪkˈtɔːriəs/', 'having won', '\"the victorious entry\"; \"the winning team\"'),
(57076, 'unsuccessful', 3, '/ˌʌnsəkˈsɛsfəl/', 'not successful; having failed or having an unfavorable outcome', NULL),
(57077, 'attempted', 3, '/əˈtɛmptɪd/', 'tried unsuccessfully', '\"attempted murder\"'),
(57078, 'hitless', 3, '/ˈhɪtləs/', '(of a batter) without a hit', '\"he went hitless for three innings\"'),
(57079, 'scoreless', 3, '/ˈskɔːrləs/', 'having no points scores', '\"a scoreless inning\"'),
(57080, 'unfulfilled', 3, '/ˌʌnfʊlˈfɪld/', 'of persons; marked by failure to realize full potentialities', '\"unfulfilled and uneasy men\"; \"unrealized dreams and ambitions\"'),
(57081, 'unplaced', 3, '/ʌnˈpleɪst/', 'not one of the first three in a race or competition', NULL),
(57082, 'winless', 3, '/ˈwɪnləs/', 'having no wins', '\"the team had a very disappointing winless season\"'),
(57083, 'sufficient', 3, '/səˈfɪʃənt/', 'of a quantity that can fulfill a need or requirement but without being abundant', '\"sufficient food\"'),
(57084, 'insufficient', 3, '/ˌɪnsəˈfɪʃənt/', 'of a quantity not able to fulfill a need or requirement', '\"insufficient funds\"'),
(57085, 'depleted', 3, '/dɪˈpliːtɪd/', 'no longer sufficient', '\"supplies are low\"; \"our funds are depleted\"'),
(57086, 'sugary', 3, '/ˈʃʊɡəri/', 'containing sugar', '\"he eats too much sugary food\"'),
(57087, 'honeyed', 3, '/ˈhʌnid/', 'with honey added', NULL),
(57088, 'sugared', 3, '/ˈʃʊɡərd/', 'with sweetening added', NULL),
(57089, 'sugarless', 3, '/ˈʃʊɡərləs/', 'not containing sugar', NULL),
(57090, 'unsweetened', 3, '/ʌnˈswiːtnd/', 'not made sweet', NULL),
(57091, 'majestic', 3, '/məˈdʒɛstɪk/', 'majestic in manner or bearing; superior to mundane matters', '\"his majestic presence\"; \"olympian detachment\"; \"olympian beauty and serene composure\"'),
(57092, 'outclassed', 3, '/ˌaʊtˈklæst/', 'decisively surpassed by something else so as to appear to be of a lower class', NULL),
(57093, 'excellent', 3, '/ˈɛksələnt/', 'very good;of the highest quality', '\"made an excellent speech\"; \"the school has excellent teachers\"; \"a first-class mind\"'),
(57094, 'greatest', 3, '/ˈɡreɪtɪst/', 'highest in quality', NULL),
(57095, 'pukka', 3, '/ˈpʌkə/', 'absolutely first class and genuine', '\"pukka sahib\"; \"pukka quarters with a swarm of servants\"'),
(57096, 'spiffing', 3, '/ˈspɪfɪŋ/', 'excellent or splendid', '\"that\'s a perfectly spiffing idea\"'),
(57097, 'coarsened', 3, '/ˈkɔːrsənd/', 'made coarse or crude by lack of skill', NULL),
(57098, 'ropey', 3, '/ˈroʊpi/', '(British informal) very poor in quality', '\"ropey food\"; \"a ropey performance\"'),
(57099, 'scrawny', 3, '/ˈskrɔːni/', 'inferior in size or quality', '\"scrawny cattle\"; \"scrubby cut-over pine\"; \"old stunted thorn trees\"'),
(57100, 'overlying', 3, '/ˌoʊvərˈlaɪɪŋ/', 'placed on or over something else', '\"an overlying image\"'),
(57101, 'superincumbent', 3, '/ˌsuːpərɪnˈkʌmbənt/', 'lying or resting on and exerting pressure on something else', '\"superincumbent layers of dead plants cut off the air and arrested decomposition\"'),
(57102, 'subjacent', 3, '/səbˈdʒeɪsənt/', 'lying nearby but lower', '\"hills and subjacent valleys\"'),
(57103, 'underlying', 3, '/ˌʌndərˈlaɪɪŋ/', 'located beneath or below', NULL),
(57104, 'supervised', 3, '/ˈsuːpərˌvaɪzd/', 'under observation or under the direction of a superintendent or overseer', '\"supervised play\"'),
(57105, 'unsupervised', 3, '/ʌnˈsuːpərˌvaɪzd/', 'not supervised or under constant observation', '\"the school maintains unsupervised study halls during free periods\"; \"reliable workers are generally unsupervised\"'),
(57106, 'supported', 3, '/səˈpɔːrtɪd/', 'held up or having the weight borne especially from below', '\"supported joints in a railroad track have ties directly under the rail ends\"'),
(57107, 'supported', 3, '/səˈpɔːrtɪd/', 'sustained or maintained by aid (as distinct from physical support)', '\"a club entirely supported by membership dues\"; \"well-supported allegations\"'),
